window.__CHRONICLE_CHUNK["wd-10"] = [
  {id:"world--1946--p01",track:"world",year:1946,yearApprox:false,dim:"politics",weight:4,title:"丘吉尔富尔顿铁幕演说",summary:"丘吉尔称自什切青到的里雅斯特铁幕已降落，对苏强硬公开化。",detail:{background:"战后英苏在波兰、希腊、伊朗与德国问题上分歧公开化；英国财政濒于极限，丘吉尔以在野身份访美，希望巩固英美特殊关系。",process:"1946年3月5日，丘吉尔在密苏里州富尔顿韦斯特敏斯特学院发表题为《力量的渊源》的演说，杜鲁门陪同出席。演说称从波罗的海什切青到亚得里亚海的里雅斯特，铁幕已经降落，并主张英语民族联合。",impact:"莫斯科反应激烈，1946年3月11日斯大林在《真理报》答问中称演说「像是一个挑起战争的人」。双方对立自此进入公开话语。",figures:["温斯顿·丘吉尔","哈里·杜鲁门","约瑟夫·斯大林"],place:"美国密苏里州富尔顿",state:"英国／美国／苏联",sources:["丘吉尔1946年3月5日《力量的渊源》演说全文（伦敦《泰晤士报》1946年3月6日刊载）","斯大林1946年3月11日就丘吉尔演说答《真理报》记者问","John Lewis Gaddis, The Cold War: A New History (2005)"],tags:["冷战起源","演说","英苏关系"]},related:["world--1946--p03", "world--1947--p01"]},
  {id:"world--1946--p02",track:"world",year:1946,yearApprox:false,dim:"politics",weight:2,title:"联合国首届大会与安理会",summary:"联大与安理会在伦敦首次开会，联合国机构转入日常运转。",detail:{background:"《联合国宪章》1945年10月24日生效后，51个创始会员国决定首届会议在英国伦敦举行，纽约会址尚在修建。",process:"1946年1月10日第一届联合国大会在伦敦威斯敏斯特中央大厅开幕，61个代表团与会；1月17日安全理事会在伦敦教会大厦举行第一次会议并通过议事规则；2月1日赖伊当选首任秘书长；6月主要机构迁往纽约。",impact:"联大第1(Ⅰ)、2(Ⅰ)号决议（1946年1月24日）确立联合国工作原则并设立原子能委员会，联合国自此成为战后争端的常设记录与仲裁平台。",figures:["特里格韦·赖伊"],place:"英国伦敦",state:"联合国",sources:["《联合国宪章》（1945年6月26日旧金山会议通过，10月24日生效）","联合国大会第1(Ⅰ)号与第2(Ⅰ)号决议（1946年1月24日）","《联合国安全理事会正式记录》第一年（1946年）"],tags:["联合国","国际组织","战后秩序"]},related:["world--1946--e01"]},
  {id:"world--1946--p03",track:"world",year:1946,yearApprox:false,dim:"politics",weight:4,title:"凯南长电报",summary:"驻苏代办八千字电报论证苏联扩张根源，成为遏制政策底稿。",detail:{background:"1946年初伊朗危机与土耳其海峡照会使华盛顿对苏判断分歧扩大，国务院要求驻莫斯科使馆说明苏联为何拒绝按期自伊朗撤军。",process:"1946年2月22日，代办凯南自莫斯科向国务院发出八千余字电报，把苏联行为归因于传统安全焦虑与意识形态结合的扩张倾向，判断其「只在逻辑的力量面前退让」。",impact:"该电报成为此后数年遏制政策的分析底稿；凯南1947年以「X」署名在《外交》季刊发表《遏制思想的观察》，为杜鲁门主义提供学理表述。",figures:["乔治·凯南","迪安·艾奇逊"],place:"苏联莫斯科（发往美国华盛顿）",state:"美国／苏联",sources:["凯南1946年2月22日自莫斯科致国务院电报，载Foreign Relations of the United States, 1946, Vol. VI","「X」, The Sources of Soviet Conduct, Foreign Affairs (1947年7月)","加迪斯《冷战》中译本"],tags:["遏制","外交文件","冷战起源"]},related:["world--1947--p01"]},
  {id:"world--1946--p04",track:"world",year:1946,yearApprox:false,dim:"politics",weight:3,title:"意大利政体公投",summary:"首次男女普选决定废除君主制，共和国与制宪议会同时诞生。",detail:{background:"1943年投降后王室与北方抵抗运动并存，君主制因1922至1943年与法西斯政权的关系而合法性受损，1946年5月王储继位以图挽救。",process:"1946年6月2至3日，意大利以男女普选方式就政体举行公投并同时选举制宪议会。内政部公布共和制得约一千二百七十一万八千票、君主制约一千零七十一万九千票；6月10日最高法院确认共和制获胜。",impact:"1948年1月1日生效的共和国宪法确立议会制，意大利此后的多党竞争与大党长期执政格局自制宪时期奠定。",figures:["阿尔契德·加斯贝利","翁贝托二世"],place:"意大利",state:"意大利",sources:["意大利内政部1946年6月2至3日政体公投与制宪议会选举官方计票结果","《意大利共和国宪法》（1947年12月22日批准，1948年1月1日生效）"],tags:["公投","政体变更","战后重建"]},related:[]},
  {id:"world--1946--p05",track:"world",year:1946,yearApprox:false,dim:"politics",weight:2,title:"菲律宾共和国独立",summary:"美国依约承认菲律宾独立，同时以条约保留基地与贸易安排。",detail:{background:"1934年《泰丁斯—麦克杜菲法》规定十年过渡期结束后给予完全独立，太平洋战争使过渡日程延后至1946年。",process:"1946年7月4日美国承认菲律宾共和国独立，同日签订《美菲总关系条约》与《军事基地协定》，另以《菲律宾贸易法》规定十年关税配额过渡期，美军保留克拉克、苏比克等地。",impact:"名义主权与既有军事、经济条款并存，成为东南亚后殖民国家的典型起步形态，也为1950年代末起的基地收回争议埋下伏笔。",figures:["曼努埃尔·罗哈斯","哈里·杜鲁门"],place:"菲律宾马尼拉",state:"菲律宾共和国／美国",sources:["1946年7月4日《美菲总关系条约》与《军事基地协定》文本","菲律宾共和国第88号共和国法令（菲律宾贸易法，1946年）","《剑桥东南亚史》第2卷"],tags:["非殖民化","条约","东南亚"]},related:[]},
  {id:"world--1946--m01",track:"world",year:1946,yearApprox:false,dim:"military",weight:3,title:"第一次印度支那战争爆发",summary:"法军河内解除越盟武装，越盟转入山区打长期游击战。",detail:{background:"1945年9月2日越南民主共和国宣告成立；1946年3月6日初步协定与9月14日临时协定承认其在法兰西联邦内自治，但统一公投与关税问题未决。",process:"1946年12月19至20日，法军在河内海防等地解除越盟武装并占领市区，越盟发动全国抗法战争；1947年秋法军控制城市与交通线，越盟退守东京湾山区根据地。",impact:"战争持续消耗法国财政并把美国援助卷入印度支那，构成1954年奠边府战役与日内瓦会议的直接前因。",figures:["胡志明","武元甲","让·圣特尼"],place:"越南河内、越北山区",state:"越南民主共和国／法国",sources:["1946年3月6日法越初步协定与9月14日临时协定文本","Marilyn B. Young, The Vietnam Wars 1945—1990 (1991)","《剑桥东南亚史》第2卷"],tags:["印度支那","殖民战争","游击战"]},related:["world--1954--m01"]},
  {id:"world--1946--c01",track:"world",year:1946,yearApprox:false,dim:"culture",weight:3,title:"《存在主义是一种人道主义》",summary:"萨特讲演回应指控，把「存在先于本质」推向公共领域。",detail:{background:"战后巴黎知识界围绕自由、责任与马克思主义的关系激烈论争，萨特面临共产党与天主教方面关于「消极人生观」的批评。",process:"1946年秋萨特在巴黎「现在俱乐部」作公开讲演，同年以《存在主义是一种人道主义》刊行，主张存在先于本质、人被判定为自由并为全人类选择自身。",impact:"该文本把现象学哲学转为大众论战语言，直接影响战后法国戏剧、小说批评与1960年代学生运动的表达方式。",figures:["让-保罗·萨特","西蒙娜·德·波伏瓦","莫里斯·梅洛-庞蒂"],place:"法国巴黎",state:"法国",sources:["萨特《存在主义是一种人道主义》（1946年巴黎讲演与刊本）","梅洛-庞蒂《人道主义与恐怖》（1947）"],tags:["存在主义","讲演","法国知识界"]},related:["world--1949--c01"]},
  {id:"world--1946--e01",track:"world",year:1946,yearApprox:false,dim:"economy",weight:2,title:"布雷顿森林机构开始营业",summary:"基金组织与世界银行在华盛顿启动业务，货币框架投入运行。",detail:{background:"1944年7月布雷顿森林会议通过基金与世界银行协定，1945年12月27日两机构成立，总部设于华盛顿，1946年完成人员与投票权配置。",process:"1946年3月8日国际货币基金组织开始业务并于年内举行首次理事会会议；6月25日国际复兴开发银行开始营业，1947年5月向法国提供首笔贷款。",impact:"可调整盯住汇率与美元黄金双锚的框架自此运转，为西欧与日本1950年代的贸易扩张提供制度条件，美国在两大机构中的投票权优势同时确立。",figures:["哈里·怀特","约翰·梅纳德·凯恩斯"],place:"美国华盛顿",state:"国际货币基金组织／世界银行",sources:["《布雷顿森林会议最终文件》（1944年7月）","国际货币基金组织执行董事会1946年决议","国际复兴开发银行第一个年度报告（1947年）"],tags:["国际货币体系","黄金本位","战后重建"]},related:["world--1971--e01"]},
  {id:"world--1947--p01",track:"world",year:1947,yearApprox:false,dim:"politics",weight:5,title:"杜鲁门主义",summary:"总统以支援自由民族抵抗外来压力为名，向希土提供援助。",detail:{background:"1947年2月21日英国照会美国，声明自3月31日起停止对希腊与土耳其的财政军事援助，两处危机同时紧迫。",process:"1947年3月12日杜鲁门在国会两院联席会议发表咨文，主张「支持自由民族抵抗少数武装分子或外来压力的征服企图」，请求授权援助希土；5月22日《援助希腊与土耳其法》签署，拨款四亿美元并派遣军事顾问团。",impact:"该咨文把一国之内战解释为可类比的全球模式，成为美国此后对社会主义国家与民族解放运动取对抗政策的公开依据。",figures:["哈里·杜鲁门","乔治·马歇尔","欧内斯特·贝文"],place:"美国华盛顿国会",state:"美国／希腊／土耳其",sources:["杜鲁门1947年3月12日致国会两院联席会议咨文全文","1947年5月22日《援助希腊与土耳其法》（Public Law 80-84）","John Lewis Gaddis, The Cold War: A New History (2005)"],tags:["遏制","美国外交","希腊内战"]},related:["world--1947--p03", "world--1948--m01"]},
  {id:"world--1947--p02",track:"world",year:1947,yearApprox:false,dim:"politics",weight:4,title:"共产党和工人党情报局成立",summary:"九党开会提出两大阵营论，各国党路线取得统一公开表述。",detail:{background:"莫斯科外长会议破裂后，苏共需要以党际机制统一各国共产党对马歇尔计划与本国政治路线的立场。",process:"1947年9月22至27日，苏、波、捷、匈、罗、保、法、意、南九党代表在波兰什克拉尔斯卡-波多达成立情报局，日丹诺夫提出「两大阵营」论；机关刊物《争取和平与人民民主》1947年11月创刊，1948年6月南斯拉夫被开除，1956年4月解散。",impact:"法意两党据此在公开文件中否定马歇尔计划并转取街头对抗路线，西欧左翼与战后政府的合作关系就此终结。",figures:["安德烈·日丹诺夫","莫里斯·多列士","帕尔米罗·陶里亚蒂","约瑟普·铁托"],place:"波兰什克拉尔斯卡-波多达",state:"苏联与东欧各国共产党",sources:["情报局1947年9月《关于国际形势的宣言》","日丹诺夫1947年9月22日报告（《争取和平与人民民主》1947年11月创刊号）","Tony Judt, Postwar: A History of Europe Since 1945 (2005)"],tags:["情报局","两大阵营","意识形态"]},related:["world--1948--p02"]},
  {id:"world--1947--p03",track:"world",year:1947,yearApprox:false,dim:"politics",weight:5,title:"马歇尔计划提出",summary:"美国以欧洲共同拟案为条件提出复兴援助，十六国巴黎回应。",detail:{background:"1946至1947年冬西欧遭遇燃料短缺、歉收与美元荒，英国在1947年8月宣布无力继续承担海外援助义务。",process:"1947年6月5日国务卿马歇尔在哈佛大学毕业典礼提出美国援助欧洲复兴的设想，以欧洲国家共同拟定计划为条件；6月至9月十六国在巴黎成立欧洲经济合作委员会并于9月22日提交报告，同期莫斯科外长会议就德国问题谈判破裂。",impact:"设想经1948年《经济合作法》立法执行，至1952年6月计划结束时十六国共获得约一百三十亿美元援助，其中英国所得份额最大。",figures:["乔治·马歇尔","让·莫内","欧内斯特·贝文","维亚切斯拉夫·莫洛托夫"],place:"美国哈佛大学／法国巴黎",state:"美国／西欧十六国",sources:["马歇尔1947年6月5日哈佛大学演说全文","欧洲经济合作委员会巴黎报告（1947年9月22日）","美国经济合作总署《欧洲复兴计划终期报告》（1951年）"],tags:["马歇尔计划","欧洲复兴","美元荒"]},related:["world--1948--i01", "world--1949--p02"]},
  {id:"world--1947--p04",track:"world",year:1947,yearApprox:false,dim:"politics",weight:5,title:"印度与巴基斯坦分治",summary:"两个自治领依边界线成立，旁遮普孟加拉爆发教派仇杀。",detail:{background:"1946年8月穆盟「直接行动日」号召引发加尔各答大暴动，国大党与穆盟关于中央权力分享的谈判破裂。",process:"1947年6月3日蒙巴顿公布分治方案，7月18日英国议会通过《印度独立法》；8月14日巴基斯坦、15日印度先后独立，8月17日公布旁遮普与孟加拉的拉德克利夫边界线，随即爆发教派仇杀与双向迁徙。",impact:"约一千二百万人跨越新边界迁徙，据印巴官方登记与学界估算，骚乱死亡人数介于二十万至一百万之间；克什米尔自1947年10月起成为两次战争与长期对峙的起点。",figures:["路易斯·蒙巴顿","贾瓦哈拉尔·尼赫鲁","穆罕默德·阿里·真纳","西里尔·拉德克利夫"],place:"旁遮普与孟加拉（新德里、拉合尔、加尔各答）",state:"印度自治领／巴基斯坦自治领",sources:["《1947年印度独立法》（10 & 11 Geo. 6 c.30）","蒙巴顿1947年6月3日分治方案声明","Yasmin Khan, The Great Partition (2007)"],tags:["非殖民化","分治","印巴"]},related:["world--1948--p01"]},
  {id:"world--1947--p05",track:"world",year:1947,yearApprox:false,dim:"politics",weight:4,title:"联大通过巴勒斯坦分治计划",summary:"第181号决议把托管地划为两国，耶路撒冷设国际政权区。",detail:{background:"英国于1947年2月把巴勒斯坦问题移交联合国，联合国巴勒斯坦问题特别委员会9月建议终止托管并分区建国。",process:"1947年11月29日第二届联大第181(Ⅱ)号决议通过《巴勒斯坦将来政府计划》及附图：犹太国面积约1.49万平方公里、阿拉伯国约1.12万平方公里，耶路撒冷及近郊设为国际政权管理区；表决为赞成33、反对13、弃权10。",impact:"犹太方面接受、阿拉伯方面拒绝；1948年5月宣布建国后次日周边国家军队介入，决议设想被停战线与难民问题取代。",figures:["埃米尔·桑德斯特伦","戴维·本-古里安"],place:"美国纽约成功湖",state:"联合国",sources:["联合国大会第181(Ⅱ)号决议《巴勒斯坦将来政府计划》（1947年11月29日）及附图","联合国巴勒斯坦问题特别委员会报告（1947年9月）"],tags:["巴勒斯坦分治","联合国决议","中东"]},related:["world--1948--m01", "world--1949--m01"]},
  {id:"world--1947--e01",track:"world",year:1947,yearApprox:false,dim:"economy",weight:3,title:"苏联与东欧缔结贸易协定",summary:"苏联以双边协定把东欧贸易支付体系自西欧市场分隔开来。",detail:{background:"苏联拒绝参加巴黎十六国会议，并以双边安排回应马歇尔计划在东欧引起的兴趣。",process:"1947年2月至1948年间，苏联先后与保加利亚、捷克斯洛伐克、波兰、匈牙利、罗马尼亚缔结贸易与偿付协定，1948至1949年又签订多年期商品交换与付款协定，货单以原料与成套设备互补。",impact:"1949年1月经互会成立，把上述双边安排制度化；其内部以记账转账结算，与关贸总协定体系形成并行而分隔的两个市场。",figures:["维亚切斯拉夫·莫洛托夫"],place:"莫斯科与东欧各国首都",state:"苏联／东欧各国",sources:["苏联与保加利亚、捷克斯洛伐克、波兰、匈牙利、罗马尼亚1947至1949年贸易与支付协定汇编","《经济互助委员会章程》（1959年修订本，莫斯科）"],tags:["经济分裂","双边协定","经互会"]},related:["world--1949--e01"]},
  {id:"world--1947--i01",track:"world",year:1947,yearApprox:false,dim:"institution",weight:3,title:"美国国家安全法",summary:"设立国家安全会议与中央情报局，战时协调机制常设化。",detail:{background:"战时各机构分立的弊端在1945至1947年关于军事体制统一的争论中凸显，杜鲁门推动以立法整合。",process:"1947年7月26日《国家安全法》签署、9月18日生效：设立国家安全会议、中央情报局与陆海空三部，改组参谋长联席会议并设国防部长；1949年修正案撤销三军部的部级独立地位。",impact:"该法把战时协调机制常设化，国家安全会议与中情局成为此后冷战政策制定与隐蔽行动的固定枢纽。",figures:["哈里·杜鲁门","詹姆斯·福莱斯特"],place:"美国华盛顿",state:"美国",sources:["《1947年国家安全法》（Public Law 80-253, 61 Stat. 495）","《1949年国家安全法修正案》（Public Law 80-216, 63 Stat. 239）"],tags:["制度","情报","国家安全会议"]},related:["world--1950--p02"]},
  {id:"world--1947--s01",track:"world",year:1947,yearApprox:false,dim:"science",weight:5,title:"点接触晶体管制成",summary:"贝尔实验室以锗片金箔点接触实现电流放大，取代真空管。",detail:{background:"贝尔实验室自1930年代研究半导体表面性质，肖克利、巴丁与布拉顿组成固体物理研究组，战时材料研究提供了工艺条件。",process:"1947年12月，巴丁与布拉顿在锗片上用金箔点接触获得功率放大，制成第一只点接触晶体管；1948年6月30日贝尔实验室对外公布，同年7月《贝尔系统技术期刊》刊登论文，肖克利随后提出结型方案并于1951年制成。",impact:"晶体管使放大器件摆脱真空管的功耗与体积限制，为集成电路、微处理器与一切现代电子设备提供起点。",figures:["约翰·巴丁","沃尔特·布拉顿","威廉·肖克利"],place:"美国新泽西州默里山贝尔实验室",state:"美国",sources:["Bardeen 与 Brattain 论文，Bell System Technical Journal 第27卷（1948年7月）","贝尔实验室1948年6月30日新闻公布记录","Jon Gertner, The Idea Factory (2012)"],tags:["半导体","发明","信息时代"]},related:["world--1958--s01"]},
  {id:"world--1947--c01",track:"world",year:1947,yearApprox:false,dim:"culture",weight:2,title:"《启蒙辩证法》出版",summary:"霍克海默与阿多诺以文化工业解释启蒙理性的自我毁灭。",detail:{background:"流亡美国的法兰克福学派成员在1941至1944年间完成书稿，把纳粹极权与大众文化的出现视为同一过程的两个面向。",process:"1947年《启蒙辩证法：哲学断片》由阿姆斯特登出版，含《启蒙的概念》《文化工业：作为大众欺骗的启蒙》等章，提出工具理性、文化工业与反犹主义的关联论证。",impact:"该书成为此后批判理论与文化工业讨论的原点文本，阿多诺1951年《最低限度的道德》与1966年《否定的辩证法》延续其问题意识。",figures:["马克斯·霍克海默","西奥多·阿多诺"],place:"荷兰阿姆斯特登",state:"流亡知识界",sources:["霍克海默、阿多诺《启蒙辩证法》（1947年阿姆斯特登初版）","Martin Jay, The Dialectical Imagination (1973)"],tags:["法兰克福学派","批判理论","文化工业"]},related:["world--1966--c01"]},
  {id:"world--1948--p01",track:"world",year:1948,yearApprox:false,dim:"politics",weight:4,title:"以色列宣布建国",summary:"托管期满之夜特拉维夫宣读独立宣言，美苏先后承认。",detail:{background:"1948年5月14日午夜英国对巴勒斯坦的委任统治期满，犹太代办处同日起在特拉维夫筹备建国程序。",process:"5月14日下午，本-古里安宣读《独立宣言》，宣布以色列国成立并以临时国务委员会代行立法权；美国在十一分钟后宣布事实承认，苏联5月17日照会承认；阿拉伯国家联盟此前已决定托管终止后出兵。",impact:"宣言援引分治决议为依据而未划定国界，停战线、难民回归与耶路撒冷地位三项悬案成为此后历次中东冲突的直接起因。",figures:["戴维·本-古里安","哈里·杜鲁门","安德烈·葛罗米柯"],place:"特拉维夫罗斯柴尔德大街24号",state:"以色列",sources:["《以色列独立宣言》（1948年5月14日）","美国国务院1948年5月14日承认声明，载Foreign Relations of the United States, 1948, Vol. V","联合国大会第181(Ⅱ)号决议"],tags:["建国","承认","中东"]},related:["world--1948--m01", "world--1949--m01"]},
  {id:"world--1948--p02",track:"world",year:1948,yearApprox:false,dim:"politics",weight:3,title:"意大利大选与天民党获胜",summary:"天民党过半，意共与社会党阵线落败，意大利锚定西方阵营。",detail:{background:"1947年5月德·加斯贝利改组排共政府，意共与意社会党于1947年9月组成人民民主阵线，情报局要求以选举斗争对抗马歇尔计划。",process:"1948年4月18日举行众议院选举，天主教民主党得票约48.5%、人民民主阵线约31%、社会民主党约20.7%；竞选期间美国以公开照会与援助信件示警，梵蒂冈发布反共指示；5月德·加斯贝利组成新一届联合政府。",impact:"选举结果把意大利固定在北大西洋阵营内，左翼两党转入长期反对派，1949年7月圣部禁止信徒加入共产党即以该格局为背景。",figures:["阿尔契德·加斯贝利","帕尔米罗·陶里亚蒂","朱塞佩·萨拉盖特"],place:"意大利",state:"意大利",sources:["意大利内政部1948年4月18至19日众议院选举官方计票结果","Tony Judt, Postwar: A History of Europe Since 1945 (2005)"],tags:["大选","天主教民主党","冷战"]},related:["world--1947--p02"]},
  {id:"world--1948--p03",track:"world",year:1948,yearApprox:false,dim:"politics",weight:3,title:"南非国民党上台执政",summary:"白人选举中联盟胜出，种族隔离自此成为法定体制。",detail:{background:"战时城市化与阿非利卡工人阶层的不安使「保留白人就业、排斥黑人城市定居」成为竞选议题，统一党的史末资因坚持参战与征兵而失势。",process:"1948年5月26日白人普选中，国民党与南非党联盟赢得议会多数席位，联合党获得的选民票数更多却失掉议会多数；6月丹尼尔·马兰就任总理，随即以立法把种族区分制度化。",impact:"1949至1953年间的《移民法》《人口登记法》《团体区域法》《班图教育法》构成种族隔离的法律骨架，1960年夏普维尔枪击案与1961年共和国成立皆为其后果。",figures:["丹尼尔·马兰","扬·史末资","亨德里克·维沃尔德"],place:"南非",state:"南非联邦",sources:["南非内政厅1948年5月26日大选官方结果","《1950年人口登记法》与《1950年团体区域法》文本（南非议会）"],tags:["种族隔离","大选","白人少数统治"]},related:["world--1950--i01"]},
  {id:"world--1948--p04",track:"world",year:1948,yearApprox:false,dim:"politics",weight:2,title:"缅甸独立",summary:"依1947年独立法脱离英联邦，吴努政府随即面对多线叛乱。",detail:{background:"1947年1月27日昂山与艾德礼政府签订协定同意缅甸独立，7月19日昂山等六名部长遇刺，制宪与选举仍按约完成。",process:"1947年12月10日英国《缅甸独立法》获王室同意，1948年1月4日缅甸脱离英联邦成为独立共和国，苏瑞泰任总统、吴努任总理，同日英缅换文确认互派使节。",impact:"缅甸成为东南亚战后较早以民族主义力量建制的独立国，同年2月起掸族、克伦族与共产党武装先后起事，内战延续数十年。",figures:["吴努","苏瑞泰","昂山"],place:"缅甸仰光",state:"缅甸联邦",sources:["《缅甸独立法》（1947年12月10日英国王室同意）","1948年1月4日缅甸独立公告与英缅换文","《剑桥东南亚史》第2卷"],tags:["非殖民化","东南亚","独立"]},related:[]},
  {id:"world--1948--p05",track:"world",year:1948,yearApprox:false,dim:"politics",weight:4,title:"世界人权宣言通过",summary:"联大以四十八票赞成零票反对通过首份全球性权利清单。",detail:{background:"人权委员会自1947年4月起草国际权利宪章，1948年经社理事会通过草案并提交联大第三委员会逐条表决。",process:"1948年12月10日第三届联大第217甲(Ⅲ)号决议通过《世界人权宣言》，表决为赞成48、反对0、弃权8；宣言第1至29条列举人身、政治、经济社会与文化权利，法律性质为宣言而非条约。",impact:"宣言成为此后国际人权文书与各国宪法援引的原点，1966年两项国际公约沿用其权利分类；投弃权票的八国包括苏联、波兰、捷克斯洛伐克、南非与沙特阿拉伯。",figures:["埃莉诺·罗斯福","勒内·卡桑","夏尔·马利克","约翰·汉弗莱"],place:"法国巴黎夏乐宫",state:"联合国",sources:["联合国大会第217甲(Ⅲ)号决议与《世界人权宣言》（1948年12月10日）","《世界人权宣言》起草过程记录（联大第三委员会第180至184次会议，1948年11至12月）","Mary Ann Glendon, A World Made New (2001)"],tags:["人权","联大决议","宣言"]},related:["world--1948--i03", "world--1966--i01"]},
  {id:"world--1948--p06",track:"world",year:1948,yearApprox:false,dim:"politics",weight:3,title:"朝鲜半岛南北分别建国",summary:"南部与北部分别成立两个互不承认的政权，三八线成对峙线。",detail:{background:"1945年8月以北纬38度线为受降分界；1947年9月联大第112(Ⅱ)号决议要求在全境举行选举，苏联拒绝联合国委员会进入北部。",process:"1948年5月10日南部举行单独选举，8月15日大韩民国成立、李承晚任总统；9月9日朝鲜民主主义人民共和国成立、金日成任内阁首相；1948年12月苏军完成自北部撤出，1949年6月美军自南部撤出。",impact:"联合国朝鲜临时委员会1948年报告确认其无法在全国行使职能，两个政权互不承认使三八线成为1950年6月战争的分界。",figures:["李承晚","金日成"],place:"汉城、平壤（三八线）",state:"大韩民国／朝鲜民主主义人民共和国",sources:["联合国大会第112(Ⅱ)号决议（1947年9月20日）","《大韩民国宪法》（1948年7月12日制定）与1948年9月9日朝鲜民主主义人民共和国建国文件"],tags:["分裂","联合国","东亚"]},related:["world--1950--m01"]},
  {id:"world--1948--m01",track:"world",year:1948,yearApprox:false,dim:"military",weight:4,title:"第一次中东战争",summary:"五国军队进入前托管地，联合国两次停火与逐段反攻并行。",detail:{background:"1947年11月起托管地内已发生武装冲突与补给线袭击，1948年5月14日英国文官撤离后战事转为国与国作战。",process:"1948年5月15日起埃及、外约旦、叙利亚、伊拉克与黎巴嫩军队进入前托管地；联合国调解人贝纳多特伯爵促成6月11日至7月8日第一次停火，10月29日「希拉姆行动」夺取加利利，12月下旬「霍雷夫行动」进入西奈；1949年1月7日埃及接受停火。",impact:"以色列控制区大于分治计划所划边界；据联合国1948至1950年估算，阿拉伯方面流离人口约七十万至一百万。",figures:["戴维·本-古里安","阿卜杜拉一世","福尔克·贝纳多特"],place:"前英国巴勒斯坦托管地、加利利、内格夫、西奈",state:"以色列／埃及、外约旦、叙利亚、伊拉克、黎巴嫩",sources:["联合国安全理事会第54、56、60(1948)号决议与停火命令","联合国大会第194(Ⅲ)号决议（1948年12月11日）","Benny Morris, 1948: A History of the First Arab-Israeli War (2008)"],tags:["中东战争","停火","难民"]},related:["world--1949--m01"]},
  {id:"world--1948--m02",track:"world",year:1948,yearApprox:false,dim:"military",weight:4,title:"柏林封锁与空运",summary:"苏联切断西柏林水陆交通，西方以十一个月空运维持供应。",detail:{background:"1948年6月18日西方三国宣布西占区货币改革，6月21日新马克进入柏林，苏方以交通与检查限制回应。",process:"1948年6月24日起苏联切断西柏林与西占区之间的铁路、公路与水道；美英以三条空中走廊空运煤粮与原料，至1949年5月12日封锁解除，据战后公布的作战统计共飞行约二十七万架次、运入约二百三十万吨物资，1949年复活节期间单日运量达一万三千吨。",impact:"封锁未能迫使西方放弃货币改革与合并西区，反而加速联邦德国建国与北大西洋条约谈判，并确立以空运维持陆上飞地的作战范式。",figures:["卢修斯·克雷","恩斯特·罗伊特","威廉·图纳"],place:"德国柏林与三条空中走廊",state:"美英法占领区／苏联占领区",sources:["美国空军历史处战后编制的柏林空运作战研究报告（1948年6月至1949年9月）","1949年5月5日四大国驻德管制机构关于解除封锁的协议照会"],tags:["封锁","空运","德国问题"]},related:["world--1949--p01", "world--1949--p02"]},
  {id:"world--1948--i01",track:"world",year:1948,yearApprox:false,dim:"institution",weight:3,title:"美国对外援助法（经济合作法）",summary:"把马歇尔设想转为财政与监督安排，五十三亿美元头期拨款。",detail:{background:"1947年12月19日杜鲁门将欧洲复兴计划咨文提交国会，两院就援助规模与监督权辩论至1948年春。",process:"1948年4月3日《对外援助法》（经济合作法）签署，设经济合作署，头十五个月拨款五十三亿美元，并要求受援国提交联合复原计划与扩大贸易的措施；其后国会两度追加拨款并把执行期延至1952年6月30日。",impact:"该法使欧洲复兴援助获得常设行政机构与年度审计，其第三、四款关于原料采购与军火生产的安排，构成1951年共同安全法的直接前身。",figures:["哈里·杜鲁门","保罗·霍夫曼"],place:"美国华盛顿",state:"美国",sources:["《1948年对外援助法（经济合作法）》（Public Law 80-472，1948年4月3日）","美国经济合作署向国会提交的年度报告（1948至1951年）"],tags:["援助立法","经济合作署","欧洲复兴"]},related:["world--1947--p03"]},
  {id:"world--1948--i02",track:"world",year:1948,yearApprox:false,dim:"institution",weight:4,title:"关贸总协定临时适用",summary:"国际贸易组织流产，二十三国关税减让安排成为唯一多边框架。",detail:{background:"1945至1948年各国筹建国际贸易组织，1947年4月起在日内瓦进行关税减让谈判并起草总协定作为过渡文书。",process:"1947年10月30日23国在日内瓦签署《关税与贸易总协定》与《临时适用议定书》，1948年1月1日起临时适用；1948年3月哈瓦那会议通过《国际贸易组织宪章》（哈瓦那宪章），因美国国会未予批准而未生效。",impact:"最惠国待遇与关税约束原则自1948年施行，总协定在此后四十余年间主持七轮多边谈判，直到1995年世界贸易组织取代这一临时安排。",figures:["克莱尔·威尔科克斯"],place:"瑞士日内瓦／古巴哈瓦那",state:"缔约23国",sources:["《关税与贸易总协定》文本与《临时适用议定书》（1947年10月30日日内瓦）","《国际贸易组织哈瓦那宪章》（1948年3月24日通过）"],tags:["多边贸易","关税减让","最惠国"]},related:["world--1947--e01"]},
  {id:"world--1948--i03",track:"world",year:1948,yearApprox:false,dim:"institution",weight:3,title:"灭绝种族罪公约通过",summary:"联大通过首份定义种族灭绝的国际公约，1951年生效。",detail:{background:"联大1946年12月11日第96甲(Ⅰ)号决议宣告灭绝种族为国际法上的犯罪，1947年起由特设委员会起草文本。",process:"1948年12月9日联大第260甲(Ⅲ)号决议通过《防止及惩治灭绝种族罪公约》，第二条以全部或部分消灭民族、族裔、种族或宗教团体的意图定义该罪，缔约国须自行立法且不得以宪法豁免；1951年1月12日生效。",impact:"该公约把国家对本国居民的杀害纳入国际刑法规制，但其定义在此后数十年长期未被实际援引，1993年前南刑庭规约与1998年罗马规约沿用了同一条款结构。",figures:["拉斐尔·莱姆金"],place:"法国巴黎",state:"联合国",sources:["《防止及惩治灭绝种族罪公约》（联大第260甲(Ⅲ)号决议附件，1948年12月9日通过，1951年1月12日生效）","联合国大会第96甲(Ⅰ)号决议（1946年12月11日）"],tags:["国际法","公约","种族灭绝"]},related:["world--1948--p05"]},
  {id:"world--1949--p01",track:"world",year:1949,yearApprox:false,dim:"politics",weight:4,title:"德国分裂为两个国家",summary:"基本法与民主德国宪法先后生效，波恩与东柏林互不承认。",detail:{background:"1948年3月伦敦六国外长会议决定在西占区建立联邦式国家，苏联抵制并加强东区管制，同年6月起封锁柏林。",process:"1949年5月23日《德意志联邦共和国基本法》公布生效，9月联邦议院选举后天民党领袖阿登纳当选联邦总理，首都设波恩；10月7日苏占区宪法生效，德意志民主共和国成立，皮克任总统、格罗提渥任部长会议主席；柏林仍由四国共管。",impact:"两个德国互不承认并以对方为非法，1955年联邦德国加入北大西洋公约、民主德国加入华沙条约，欧洲的分界同时是两大军事集团的界线。",figures:["康拉德·阿登纳","威廉·皮克","奥托·格罗提渥","路德维希·埃哈德"],place:"波恩与东柏林",state:"德意志联邦共和国／德意志民主共和国",sources:["《德意志联邦共和国基本法》（1949年5月23日公布生效）","《德意志民主共和国宪法》（1949年10月7日生效）","Tony Judt, Postwar (2005)"],tags:["德国问题","分裂","建国"]},related:["world--1948--m02", "world--1955--p02"]},
  {id:"world--1949--p02",track:"world",year:1949,yearApprox:false,dim:"politics",weight:5,title:"北大西洋公约签署",summary:"十二国把对一国的攻击视为对全体的攻击，美国承诺入欧。",detail:{background:"1948年3月17日比英法荷卢五国签订《布鲁塞尔条约》，捷克斯洛伐克2月事件与柏林封锁使加拿大与美国同意缔结跨大西洋军事同盟。",process:"1949年4月4日美国、加拿大与十个欧洲国家在华盛顿签署《北大西洋公约》，8月24日生效；第3条要求维持并发展集体抵抗能力，第5条规定对一国或数国的武装攻击视为对全体的攻击，第4条设协商机制。",impact:"公约把美国对西欧的安全义务写成常设条款，为1950年后美军常驻欧洲与联邦德国重新武装提供制度外壳；1955年苏联以华沙条约对应。",figures:["迪安·艾奇逊","欧内斯特·贝文","路易·圣劳伦特"],place:"美国华盛顿",state:"缔约十二国",sources:["《北大西洋公约》正文（1949年4月4日华盛顿签署）","《布鲁塞尔条约》（1948年3月17日布鲁塞尔签署）","加迪斯《冷战》中译本"],tags:["军事同盟","集体防御","美国与欧洲"]},related:["world--1955--p01"]},
  {id:"world--1949--p03",track:"world",year:1949,yearApprox:false,dim:"politics",weight:3,title:"荷兰移交印尼主权",summary:"海牙圆桌会议承认印尼联邦独立，西伊里安问题延后谈判。",detail:{background:"1948年12月18日荷军发动第二次「警察行动」并拘押印尼领导人，联合国安全理事会1949年1月28日设立调解委员会施压。",process:"1949年8月23日至11月2日双方在海牙举行圆桌会议，12月27日签署最后文件：荷兰承认印尼联邦为主权国家，联邦承接原殖民债务并承诺补偿荷属企业资产，西伊里安地位延后一年谈判。",impact:"联邦成立一年后即改行单一共和国与1950年8月临时宪法；西伊里安至1963年才经联合国临时权力机构移交，成为此后荷印尼关系的长期争点。",figures:["苏加诺","穆罕默德·哈达"],place:"荷兰海牙／日惹、雅加达",state:"印度尼西亚共和国／荷兰",sources:["《荷兰—印尼圆桌会议最后文件与附件》（1949年12月27日海牙）","联合国安全理事会第67(1949)号决议（1949年1月28日）","《剑桥东南亚史》第2卷"],tags:["非殖民化","主权移交","东南亚"]},related:["world--1948--p04"]},
  {id:"world--1949--m01",track:"world",year:1949,yearApprox:false,dim:"military",weight:3,title:"罗德岛四项停战协定",summary:"以色列与四国分签停战线，协定声明不构成边界划定。",detail:{background:"1949年1月起各方在联合国调解人邦奇主持下，于希腊罗德岛分岸谈判停战条件。",process:"1949年2月23日埃以、3月23日以黎、4月3日以约旦、7月20日以叙先后签订总停战协定，划定停战线、设混合停战委员会并规定监督条款，各约均明定停战线不构成政治或领土划定。",impact:"协定带来十年相对稳定的边界线，但1948年12月联大第194(Ⅲ)号决议所确认的难民回归或赔偿未被执行，和解委员会的登记成为难民问题的长期记录。",figures:["拉尔夫·邦奇","莫舍·夏里特"],place:"希腊罗德岛与前托管地停战线",state:"以色列／埃及、黎巴嫩、外约旦、叙利亚",sources:["以色列与埃及、黎巴嫩、外约旦、叙利亚四项停战协定（1949年2月23日至7月20日罗德岛签署）","联合国大会第194(Ⅲ)号决议（1948年12月11日）"],tags:["停战","联合国调解","中东"]},related:["world--1948--m01"]},
  {id:"world--1949--e01",track:"world",year:1949,yearApprox:false,dim:"economy",weight:3,title:"经济互助委员会成立",summary:"苏联与五国在莫斯科建制，把东欧贸易纳入双边货单体系。",detail:{background:"1949年初苏联以双边协定回应经济合作法，并阻止东欧国家参加巴黎十六国与后来成立的合作机构。",process:"1949年1月5至25日经互会在莫斯科成立，初始成员为苏、保、匈、波、罗、捷六国，1950年阿尔巴尼亚与民主德国、1962年蒙古先后加入；秘书处设莫斯科，以年度双边货单与记账转账结算协调贸易与生产分工。",impact:"该机制以原料供应与成套设备分工把东欧经济长期绑定于苏联，1956年后关于国际分工与定价方式的争论成为成员国间摩擦的主线。",figures:["阿纳斯塔斯·米高扬","维亚切斯拉夫·莫洛托夫"],place:"苏联莫斯科",state:"苏联与东欧六国",sources:["1949年1月25日经互会成立决议（莫斯科）","《经济互助委员会章程》（1959年修订本）"],tags:["经互会","计划贸易","东欧"]},related:["world--1947--e01"]},
  {id:"world--1949--i01",track:"world",year:1949,yearApprox:false,dim:"institution",weight:3,title:"日内瓦四公约通过",summary:"新增保护平民公约，共同第三条延及非国际性武装冲突。",detail:{background:"红十字国际委员会自1947年起推动修订1929年公约，并就战时平民保护起草新约，1949年4月召集外交会议。",process:"1949年4月21日至8月12日六十余国代表在日内瓦通过四部公约：伤者病者、海上武装部队、战俘与战时平民保护，另附两项规章；共同第三条首次把非国际性武装冲突纳入人道法义务，1950年10月21日生效。",impact:"四公约成为此后武装冲突法的基准文本，1977年两项附加议定书与其1949年条款衔接，前南刑庭与罗马规约的指控多以公约条款为法律依据。",figures:["让·皮克特"],place:"瑞士日内瓦",state:"与会六十余国",sources:["《改善战地武装部队伤者病者境遇之日内瓦公约》等四部日内瓦公约（1949年8月12日通过，1950年10月21日生效）","红十字国际委员会《日内瓦四公约评注》（1952至1960年）"],tags:["人道法","战俘","平民保护"]},related:["world--1948--p05"]},
  {id:"world--1949--i02",track:"world",year:1949,yearApprox:false,dim:"institution",weight:2,title:"欧洲委员会成立",summary:"十国签约设斯特拉斯堡机构，欧洲人权公约由此产生。",detail:{background:"1948年5月海牙欧洲大会在丘吉尔等人居间推动下通过决议，要求建立政治性的欧洲联盟机构。",process:"1949年5月5日英、法、意、比、荷、卢、丹、挪、瑞典、爱尔兰十国在伦敦签署《欧洲委员会章程》，8月3日生效后总部设斯特拉斯堡，设部长委员会与由各国议会指派的协商议会。",impact:"该组织成为1950年《欧洲人权公约》与欧洲人权法院的母体，与后来的共同市场路径并行，构成战后西欧两套欧洲机构的格局。",figures:["罗伯特·舒曼","保罗-亨利·斯巴克","温斯顿·丘吉尔"],place:"英国伦敦／法国斯特拉斯堡",state:"西欧十国",sources:["《欧洲委员会章程》（1949年5月5日伦敦签署，8月3日生效）","《欧洲人权公约》（1950年11月4日罗马签署，1953年9月3日生效）"],tags:["欧洲一体化","人权机构","政府间合作"]},related:["world--1950--i02"]},
  {id:"world--1949--s01",track:"world",year:1949,yearApprox:false,dim:"science",weight:4,title:"苏联试爆第一颗原子弹",summary:"塞米巴拉金斯克爆炸结束美国核垄断，军备竞赛升级。",detail:{background:"苏联自1943年恢复铀研究，1945年后以特种设计局与第二总局并行推进，两年内完成首枚钚装药装置。",process:"1949年8月29日苏联在哈萨克塞米巴拉金斯克试验场试爆第一颗原子弹，装药结构取自美国钚内爆式装置；9月22日美国飞机在阿留申方向采到放射性微粒，9月23日杜鲁门公开宣布苏联已发生核爆炸。",impact:"核垄断终结使美国安全假设失效，1950年1月31日杜鲁门批准热核武器研制计划，同年4月第68号国家安全指令把军备扩张列为政策依据。",figures:["伊戈尔·库尔恰托夫","拉夫连季·贝利亚","哈里·杜鲁门"],place:"哈萨克塞米巴拉金斯克试验场",state:"苏联／美国",sources:["杜鲁门1949年9月23日关于苏联核试验的总统声明","David Holloway, Stalin and the Bomb: The Soviet Union and Atomic Energy 1939—1956 (1994)","加迪斯《冷战》中译本"],tags:["核武器","军备竞赛","试验"]},related:["world--1950--p02"]},
  {id:"world--1949--c01",track:"world",year:1949,yearApprox:false,dim:"culture",weight:3,title:"《第二性》出版",summary:"波伏瓦以「女人并非天生」重写性别处境的历史与经验。",detail:{background:"法国1944年赋予妇女选举权后，就业、家庭法与生育问题的辩论持续；波伏瓦自1945年起以四年时间收集医学、历史与文学材料。",process:"1949年10月伽利玛出版社出版两卷本《第二性》，分「事实与神话」「当代体验」「走向解放」三部，提出「女人不是天生的，而是后天形成的」，并以他者概念分析女性在被定义位置上的经验。",impact:"该书成为此后妇女研究与第二波妇女运动的常引文本，贝蒂·弗里丹1963年《女性的奥秘》与1970年代性别社会学的议题设置皆受其影响。",figures:["西蒙娜·德·波伏瓦","让-保罗·萨特"],place:"法国巴黎",state:"法国",sources:["波伏瓦《第二性》（1949年巴黎伽利玛出版社初版）","波伏瓦《事物的力量》（1963）"],tags:["女性主义","哲学","法国知识界"]},related:["world--1946--c01"]},
  {id:"world--1949--a01",track:"world",year:1949,yearApprox:false,dim:"art",weight:2,title:"《一九八四》出版",summary:"奥威尔以大洋国与「新话」写出极权语言的文学样板。",detail:{background:"奥威尔1946年因肺结核迁居苏格兰朱拉岛，1948年秋完成书稿，原定书名《最后一个英国人》。",process:"1949年6月8日《一九八四》由伦敦塞克与沃伯格出版社刊行，书中新设真理部、思想警察、「新话」「双重思想」与「101房间」等装置，把语言改造与历史改写写成同一过程。",impact:"该书与《动物农场》（1945）共同构成反极权文学样板，「奥威尔式」与书中年份成为描述监控与语言操纵的常用词汇，1989年后在东欧多国重印。",figures:["乔治·奥威尔"],place:"英国伦敦",state:"英国",sources:["奥威尔《一九八四》（1949年6月8日伦敦初版）","奥威尔《我为什么写作》（1946）"],tags:["小说","极权书写","语言"]},related:["world--1947--c01"]},
  {id:"world--1950--p01",track:"world",year:1950,yearApprox:false,dim:"politics",weight:4,title:"安理会授权联合国军",summary:"三项决议认定北朝鲜进攻并授权各国军队归入统一司令部。",detail:{background:"1950年6月25日战事爆发时苏联代表正因第七届联大关于中国代表权问题的争论而缺席安理会会议。",process:"6月25日安理会第82(1950)号决议认定北朝鲜武装进攻构成破坏和平并要求撤军；6月27日第83号决议建议会员国提供援助以击退进攻；7月7日第84号决议核准设立由美国指定的统一司令部，并授权使用联合国旗与韩国旗。",impact:"共有十六国提供部队或医疗单位，联合国首次以本组织名义实施军事行动；苏联自8月起返回安理会并动用否决权，此后大国直接介入的冲突难以再获同类授权。",figures:["欧内斯特·格罗斯","雅可夫·马立克"],place:"美国纽约成功湖",state:"联合国安全理事会",sources:["联合国安全理事会第82、83、84(1950)号决议（1950年6月25日、6月27日、7月7日）","《联合国安全理事会正式记录》第五年"],tags:["集体安全","朝鲜战争","否决权"]},related:["world--1950--m01"]},
  {id:"world--1950--p02",track:"world",year:1950,yearApprox:false,dim:"politics",weight:4,title:"第68号国家安全会议文件",summary:"秘密报告把军备扩张写成生存问题，为朝鲜战争预算定调。",detail:{background:"苏联1949年核试验与国务院、国防部关于援助与出口管制的复审，促使杜鲁门责成两部门联合评估国家战略目标。",process:"1950年4月14日杜鲁门批准第68号国家安全会议文件《美国国家安全目标与规划》，文件由尼采主持起草，判断苏联力求摧毁美国制度，主张以「更为快速而果敢的规划」扩充常规与核军备，全文列为机密。",impact:"该文件在6月25日战事爆发后被用作预算扩张的解释框架，1951财年国防开支由约十三亿美元量级跃升至数百亿美元，国家安全与凯恩斯式财政由此结合。",figures:["保罗·尼采","迪安·艾奇逊","哈里·杜鲁门"],place:"美国华盛顿",state:"美国",sources:["美国国家安全会议第68号文件（1950年4月14日批准，1975年解密）","《美国对外关系文件集》1950年第1卷"],tags:["军备扩张","国家安全","秘密文件"]},related:["world--1949--s01"]},
  {id:"world--1950--p03",track:"world",year:1950,yearApprox:false,dim:"politics",weight:4,title:"舒曼声明提出煤钢共管",summary:"法国外长建议把法德煤钢置于共同高级机构之下并向欧洲开放。",detail:{background:"美英要求联邦德国参与欧洲复兴与安全体系，法国需要以超国家安排约束鲁尔与萨尔的重工业，同时回应美国1949年《迪奇计划》。",process:"1950年5月9日法国外长舒曼在奥朗多克厅宣读声明，建议把法德两国煤钢生产整体并入一个对其他国家开放的高级机构，以共同高级机构取代国家管制，并声明此步骤使两国间战争「不仅不可想象，而且物质上不可能」。",impact:"声明把主权让渡限定于特定工业部门，直接导致1951年《巴黎条约》签订与欧洲煤钢共同体成立，成为此后欧洲一体化制度设计的原型。",figures:["罗伯特·舒曼","让·莫内","康拉德·阿登纳"],place:"法国巴黎",state:"法国",sources:["法国外交部1950年5月9日《舒曼声明》全文","美国国务院1949年9月8日《迪奇计划》备忘录"],tags:["欧洲一体化","煤钢共管","法国"]},related:["world--1951--p01"]},
  {id:"world--1950--p04",track:"world",year:1950,yearApprox:false,dim:"politics",weight:3,title:"麦卡锡发起忠诚指控",summary:"参议员声称握有国务院共党名单，忠诚调查蔓延至文化与学界。",detail:{background:"1947年杜鲁门设立联邦雇员忠诚委员会，希斯案与1949年核机密案使「渗透」议题升温。",process:"1950年2月9日共和党参议员麦卡锡在西弗吉尼亚州惠灵演讲中声称手握一份载有两百零五个「已知共党党员」仍在国务院工作的名单，2月20日将该演说载入《国会记录》；参院设蒂林森小组委员会复查，结论为查无实据。",impact:"忠诚调查扩展至军队、图书馆、学者与好莱坞，1954年12月2日参议院通过第301号决议对其行为予以谴责，该事件成为此后美国公共生活中「红色恐慌」的通称来源。",figures:["约瑟夫·麦卡锡","米勒德·蒂林森","阿尔杰·希斯"],place:"美国西弗吉尼亚州惠灵／华盛顿",state:"美国",sources:["麦卡锡1950年2月9日惠灵演说（载《国会记录》第96卷第1部，1950年2月20日）","美国参议院外交委员会小组委员会《国务院忠诚调查报告》（1950年6月）","美国参议院第301号谴责决议（1954年12月2日）"],tags:["忠诚调查","参议院","国内政治"]},related:["world--1954--p02"]},
  {id:"world--1950--p05",track:"world",year:1950,yearApprox:false,dim:"politics",weight:3,title:"印度共和国宪法生效",summary:"宪法确立世俗共和国与普选，种姓歧视失去法律基础。",detail:{background:"1947年分治后制宪议会自1946年起起草宪法，1949年11月26日通过，历时近三年完成两院式条文与附表。",process:"1950年1月26日《印度共和国宪法》生效，宣告印度为主权的民主共和国，规定基本权利与国家政策指导原则，废除不可接触制并确立成年男女普选；拉金德拉·普拉萨德于同日当选首任总统。",impact:"1951至1952年首届人民院大选由选举委员会独立组织，合格选民约一点七亿，国大党获胜，成为亚洲后殖民国家中延续最久的选举实验。",figures:["贾瓦哈拉尔·尼赫鲁","比姆拉奥·安贝德卡","拉金德拉·普拉萨德"],place:"印度新德里",state:"印度共和国",sources:["《印度共和国宪法》（1949年11月26日制宪议会通过，1950年1月26日生效）","印度选举委员会《第一届人民院大选报告（1951至1952年）》"],tags:["宪法","普选","世俗主义"]},related:["world--1947--p04"]},
  {id:"world--1950--m01",track:"world",year:1950,yearApprox:false,dim:"military",weight:5,title:"朝鲜战争爆发",summary:"6月25日人民军越过三八线，战争一年之内三次改变战线。",detail:{background:"1948年南北分别建国后，三八线沿线武装冲突与强制迁移持续两年，1949年6月美军撤离南方。",process:"1950年6月25日拂晓朝鲜人民军越过三八线发起进攻，28日进入汉城；9月15日美军仁川登陆，10月19日联合国军进入平壤，10月25日起中国人民志愿军参战并把战线推回三八线附近，次年7月10日开始停战谈判。",impact:"据美国国防部战后统计口径，美军死亡三万六千九百四十人（其中战斗死亡三万三千七百三十人）；双方公布与学界估算的军民死亡总数差异极大，常见推算为百万至数百万级。",figures:["金日成","李承晚","道格拉斯·麦克阿瑟","彭德怀"],place:"朝鲜半岛三八线、汉城、仁川、平壤、开城",state:"朝鲜民主主义人民共和国／大韩民国／联合国军与中国人民志愿军",sources:["美国国防部阵亡分析系统与《美国陆军在朝鲜战争》官方战史（1950至1953年卷次）","联合国安全理事会第82(1950)号决议","加迪斯《冷战》中译本"],tags:["朝鲜战争","停战谈判","大国介入"]},related:["world--1953--p01", "world--1950--p01", "cn--1950--m01"]},
  {id:"world--1950--i01",track:"world",year:1950,yearApprox:false,dim:"institution",weight:3,title:"南非1950年种族隔离立法",summary:"人口登记与团体区域两法把居住与身份按种族强行划分。",detail:{background:"1948年国民党执政后成立种族隔离委员会，把战时已存在的通行法与职业保留法转为系统立法。",process:"1950年议会通过《人口登记法》，设种族分类局与种族划分委员会，按白人、土著、有色人等登记全体居民；同年《团体区域法》授权划定单一种族区，为强制迁移与拆除混居街区提供法律依据；《压制共产主义法》6月26日生效。",impact:"身份登记与居住分区构成种族隔离的两根支柱，1960年夏普维尔事件、1976年索韦托起义与1991年废止相关法律皆围绕这套登记与迁移体系展开。",figures:["亨德里克·维沃尔德","丹尼尔·马兰"],place:"南非",state:"南非联邦",sources:["《人口登记法》与《团体区域法》（南非议会1950年通过）","《压制共产主义法》（南非议会1950年）"],tags:["种族隔离","立法","身份登记"]},related:["world--1948--p03"]},
  {id:"world--1950--i02",track:"world",year:1950,yearApprox:false,dim:"institution",weight:3,title:"欧洲人权公约签署",summary:"十二国签约设个人申诉机制，人权保障越出国内管辖。",detail:{background:"欧洲委员会协商议会1949年9月通过决议，要求在《世界人权宣言》基础上订立具有约束力并可个人申诉的公约。",process:"1950年11月4日十二国在罗马签署《保护人权与基本自由公约》，1953年9月3日生效；公约第1项议定书保障财产权与选举权，第25条允许个人向新设的欧洲人权委员会申诉，1959年欧洲人权法院在斯特拉斯堡开始受理。",impact:"该机制使缔约国国民可就本国政府诉至国际法庭，1953至1998年间法院与委员会累积的判例成为欧洲刑法、新闻与程序规则的共同参照。",figures:["戴维·马克斯韦尔·法伊夫","费尔南·德胡斯"],place:"意大利罗马",state:"欧洲委员会缔约国",sources:["《保护人权与基本自由公约》（1950年11月4日罗马签署，1953年9月3日生效）与第一号议定书","《欧洲委员会章程》（1949年5月5日伦敦签署）"],tags:["人权法院","个人申诉","欧洲一体化"]},related:["world--1949--i02"]},
  {id:"world--1950--i03",track:"world",year:1950,yearApprox:false,dim:"institution",weight:2,title:"联合国难民署设立",summary:"联大决议设立高级专员方案，处理欧洲流离者的长期身份。",detail:{background:"战后欧洲仍有约一百万未遣返流离人员与难民，国际难民组织1950年结束任务后其职能待承接。",process:"1950年12月14日第五届联大第428(五)号决议通过《联合国难民事务高级专员章程》，设高级专员与咨询委员会（1951年改为执委会），1951年1月1日开始运作，初期任务期三年并以自愿捐款筹资。",impact:"1951年7月28日《关于难民地位的公约》据其第35条规定缔设不推回原则，难民署自此成为跨越冷战与去殖民化冲突的常设人道机构。",figures:["戈特弗里德·雅科布森"],place:"美国纽约／瑞士日内瓦",state:"联合国",sources:["联合国大会第428(五)号决议与《联合国难民事务高级专员章程》（1950年12月14日）","国际难民组织结束活动报告（1950年联大第427号决议所附文件）"],tags:["难民","人道机构","联大决议"]},related:["world--1951--i01"]},
  {id:"world--1950--s01",track:"world",year:1950,yearApprox:false,dim:"science",weight:4,title:"图灵提出机器智能判据",summary:"以模仿游戏替「机器能否思考」设问，奠定人工智能议题。",detail:{background:"1945至1948年图灵参与国家物理实验室自动计算引擎与曼彻斯特马克一号的设计，数字计算机的可编程性已成工程事实。",process:"1950年10月《心灵》杂志刊出图灵《计算机器与智能》，开篇回避「思考」定义，改以「模仿游戏」设判据：若机器在询问中令人无法分辨其身份，则可称其能思维；文中并逐条反驳九种反对意见，给出编程与学习机器的设计路线。",impact:"该文把智能问题转为可操作的行为判据，1956年达特茅斯会议与此后人工智能、机器学习研究均以这一问题设定为起点。",figures:["艾伦·图灵"],place:"英国曼彻斯特",state:"英国",sources:["图灵《计算机器与智能》，Mind 第59卷第236期（1950年10月）","安德鲁·霍奇斯《艾伦·图灵：密码与计算机的创造者》（1983）"],tags:["人工智能","计算","哲学"]},related:["world--1947--s01"]},
  {id:"world--1951--p01",track:"world",year:1951,yearApprox:false,dim:"politics",weight:4,title:"欧洲煤钢共同体条约签署",summary:"六国把煤钢生产交予超国家高级机构，期限五十年。",detail:{background:"1950年6月起六国谈判机构方案，法国以共同高级机构取代鲁尔国际管制局为条件，联邦德国要求同时结束占领管制。",process:"1951年4月18日法、联邦德国、意、比、荷、卢六国在巴黎签署《欧洲煤钢共同体条约》，设高级机构、共同议会、法院与协商委员会，取消卡特尔与歧视性运价，1952年7月23日生效，期限五十年。",impact:"条约把煤钢生产置于凌驾成员国政府的机构之下，1957年《罗马条约》沿用其机构架构，鲁尔与萨尔争端转入共同市场的法律程序。",figures:["罗伯特·舒曼","让·莫内","康拉德·阿登纳","朱塞佩·佩拉"],place:"法国巴黎",state:"欧洲煤钢共同体六国",sources:["《欧洲煤钢共同体条约》（1951年4月18日巴黎签署，1952年7月23日生效）","让·莫内《回忆录》（1976年巴黎版）"],tags:["欧洲一体化","超国家机构","煤钢"]},related:["world--1950--p03", "world--1957--p01"]},
  {id:"world--1951--i01",track:"world",year:1951,yearApprox:false,dim:"institution",weight:3,title:"关于难民地位的公约",summary:"公约首次定义难民身份并确立不推回原则。",detail:{background:"难民署章程要求以国际文书界定难民法律地位，1950至1951年联合国在欧洲召开全权代表会议起草条文。",process:"1951年7月28日《关于难民地位的公约》在日内瓦通过、1954年4月22日生效；第一条以1951年前发生于欧洲的事件为定义基准并容许地域保留，第33条规定不得将难民推回其生命或自由受威胁之地。",impact:"1967年1月31日《难民地位议定书》取消时间与地域限制，公约与议定书构成此后各国庇护制度的法律基础，不推回原则在海域拦截与境外审查实践中反复受到挑战。",figures:["赫里特·范许温·胡德哈特","费利克斯·施尼德"],place:"瑞士日内瓦",state:"联合国",sources:["《关于难民地位的公约》（1951年7月28日日内瓦通过，1954年4月22日生效）与《1967年难民地位议定书》","联合国大会第428(五)号决议（1950年12月14日）"],tags:["难民","不推回原则","公约"]},related:["world--1950--i03"]},
  {id:"world--1951--m01",track:"world",year:1951,yearApprox:false,dim:"military",weight:3,title:"埃及废除英埃同盟条约",summary:"开罗单方面废约，运河区游击袭击与英军清剿并行。",detail:{background:"1936年英埃条约允许英军驻运河区至战时结束，战后华夫德党与军队要求全部撤军，1951年10月谈判破裂。",process:"1951年10月8日纳赫哈斯政府宣布废除1936年条约并取消英国在运河区的基地权利；此后游击队袭击哨所与输水管线，英军以装甲巡逻与焚毁村庄回应；1952年1月25至26日伊斯梅利亚守军包围埃及警营，埃方警队死伤数十人。",impact:"运河区驻军的存废成为1954年撤军条约与1956年国有化危机的直接引线，1952年7月军官团政变即以此冲突为背景。",figures:["萨拉·纳赫哈斯","安东尼·艾登"],place:"埃及苏伊士运河区、伊斯梅利亚",state:"埃及／英国",sources:["埃及政府1951年10月8日废约声明与照会","英国国家档案馆藏英国外交部1951至1952年开罗电报（解密）"],tags:["运河区","废约","反殖民"]},related:["world--1952--p02", "world--1956--m01"]},
  {id:"world--1951--s01",track:"world",year:1951,yearApprox:false,dim:"science",weight:3,title:"UNIVAC一号交付使用",summary:"首台商用电子计算机进入美国人口普查局，计算走向行政。",detail:{background:"埃克特与莫奇利离宾夕法尼亚大学后组建雷明顿兰德公司，以承接政府统计业务为目标研制商用机。",process:"1951年3月31日第一台UNIVAC一号交付美国人口普查局、6月14日投入运行，用水银延迟线存储器与单指令流结构处理普查与经济报表，至1954年共交付约四十余台。",impact:"该批机器使电子计算自军方与实验室进入政府统计与企业管理，1952年11月哥伦比亚广播公司用它预测总统选举结果，公众对计算机的认知随之改变。",figures:["普雷斯珀·埃克特","约翰·莫奇利"],place:"美国华盛顿与费城",state:"美国",sources:["美国人口普查局1951年关于UNIVAC一号验收与运行的报告","IEEE《计算史年鉴》关于早期商用计算机的专题刊载"],tags:["计算机","人口普查","商用机"]},related:[]},
  {id:"world--1951--a01",track:"world",year:1951,yearApprox:false,dim:"art",weight:2,title:"《罗生门》获威尼斯金狮奖",summary:"黑泽明影片在威尼斯获奖，日本电影进入西方艺术院线。",detail:{background:"影片1950年8月在日本上映时评价与票房俱淡，制片公司随后将其送展欧洲电影节。",process:"1951年9月《罗生门》在第12届威尼斯国际电影节获金狮奖，1952年获美国电影艺术与科学学院荣誉奖，成为在欧美大规模上映的首部日本电影。",impact:"该片以互斥证词结构进入欧洲艺术电影讨论，促成1950年代日本电影与作者电影观念的双向影响，也开启了此后国际电影节对亚洲影片的常规接纳。",figures:["黑泽明","桥本忍","芥川龙之介"],place:"意大利威尼斯",state:"日本",sources:["第12届威尼斯国际电影节（1951年）评奖决议记录","美国电影艺术与科学学院第24届（1952年）颁奖记录"],tags:["电影","日本","电影节"]},related:["world--1952--a01"]},
  {id:"world--1952--p01",track:"world",year:1952,yearApprox:false,dim:"politics",weight:3,title:"欧洲煤钢共同体高级机构就职",summary:"莫内领导的高级机构在卢森堡接管六国煤钢管制权。",detail:{background:"条约生效后六国协商人选与驻地，法国主张设于卢森堡，各国就高级机构的征税与干预权限仍有分歧。",process:"1952年8月10日高级机构在卢森堡就职，让·莫内任首任主席，共同议会由六国议会指派七十八名代表组成；1953年5月1日该机构自鲁尔国际管制局接管煤钢生产管制权。",impact:"这是战后首次由超国家机构直接行使行业管制与征税权，成员国的价格与运价规则改由共同机构执行，为1957年总委员会提供了行政先例。",figures:["让·莫内","保罗-亨利·斯巴克","朱塞佩·佩拉"],place:"卢森堡",state:"欧洲煤钢共同体",sources:["《欧洲煤钢共同体条约》第2至第8条与过渡条款","欧洲煤钢共同体高级机构第一年度报告（1953年）"],tags:["欧洲一体化","高级机构","卢森堡"]},related:["world--1951--p01"]},
  {id:"world--1952--p02",track:"world",year:1952,yearApprox:false,dim:"politics",weight:4,title:"埃及七月革命",summary:"自由军官组织夺权，法鲁克退位并转向共和与土改。",detail:{background:"1948年战败、1951至1952年运河区冲突与军队装备丑闻使王室合法性流失，军官团自1949年起秘密组网。",process:"1952年7月22至23日凌晨，自由军官组织占领开罗军营、广播电台与机场，26日法鲁克一世退位离境；纳吉布任革命指导委员会主席与总理，纳赛尔掌实权，1953年6月18日宣布成立共和国。",impact:"新政以1952年9月9日土地改革法与军队改组为支柱，并把英军自运河区撤出列入谈判（1954年10月条约），埃及此后走向阿拉伯民族主义与不结盟政策。",figures:["加迈勒·阿卜杜勒·纳赛尔","穆罕默德·纳吉布","法鲁克一世"],place:"埃及开罗与亚历山大",state:"埃及",sources:["埃及革命指导委员会1952年7月26日公告与1953年6月18日共和国宣言","《1952年9月9日土地改革法》文本（埃及）"],tags:["军官团","共和","土地改革"]},related:["world--1951--m01", "world--1956--m01"]},
  {id:"world--1952--e01",track:"world",year:1952,yearApprox:false,dim:"economy",weight:3,title:"伦敦债务协定",summary:"联邦德国外债减半并延后偿付，出口盈余与偿债挂钩。",detail:{background:"1948至1951年联邦德国以援助与出口积累偿债能力，但战前债务与赔偿数额远超其支付能力，1951年伦敦谈判启动。",process:"1952年2月27日《伦敦债务协定》签署，把战前德国外债削减约半，将1948年后新债务的偿付比例与其出口盈余挂钩，并规定赔偿与债务余额待对德和约签订后再议。",impact:"该协定使西德得以在1950年代把资本用于投资而非偿债，出口导向增长模式与1953年《联邦赔偿法》的补偿安排同时确立，债权国亦接受以贸易而非强制收债为条件。",figures:["赫尔曼·阿布思","康拉德·阿登纳"],place:"英国伦敦",state:"联邦德国与二十余个债权方",sources:["1952年2月27日《伦敦债务协定》（德国外债问题最终解决协定）文本","《联邦赔偿法》（联邦德国1953年6月29日通过）"],tags:["外债","西德","战后赔偿"]},related:["world--1953--p02"]},
  {id:"world--1952--e02",track:"world",year:1952,yearApprox:false,dim:"economy",weight:3,title:"玻利维亚锡矿国有化",summary:"起义政府收回三家锡业公司，并随后颁行土地改革法。",detail:{background:"民族主义革命运动自1940年代在矿工与农民中组织起来，1951年大选胜选后政权被军方取消。",process:"1952年4月9日起义后该党执政，10月31日以法令将帕蒂尼奥、霍希柴尔德与阿拉马亚三家锡业公司的矿场收归国有并组建国家矿业公司；1953年8月2日颁布土地改革法，同时取消识字投票限制实行普选。",impact:"锡矿收入成为国家工业化的财源与军队改组的预算基础，国家矿业公司至1980年代末仍是财政支柱；1964年军方政变后经济政策再度右转。",figures:["维克托·帕斯·埃斯登索罗"],place:"玻利维亚拉巴斯与奥鲁罗、波托西矿区",state:"玻利维亚",sources:["玻利维亚1952年10月31日锡业国有化法令与1953年8月2日土地改革法文本","《剑桥拉丁美洲史》第8卷"],tags:["国有化","锡矿","普选"]},related:["world--1956--p01"]},
  {id:"world--1952--s01",track:"world",year:1952,yearApprox:false,dim:"science",weight:3,title:"英国试爆首枚原子弹",summary:"蒙特贝洛群岛爆炸使英国成为第三个核武器国家。",detail:{background:"英国内阁1947年1月作出独立研制原子弹的决定，1950年在澳大利亚伍默拉设试验场并完成钚生产堆。",process:"1952年10月3日，英国以「飓风行动」在澳大利亚西北蒙特贝洛群岛试爆首枚钚内爆式装置，成为第三个核武器国家；1957年11月8日在圣诞岛试爆首枚热核装置。",impact:"核能力使英国在美苏之间保有一条独立威慑论证，也促成1958年7月《美英共同防御协定》恢复技术共享，并支撑其后以导弹采购为内容的拿索安排。",figures:["温斯顿·丘吉尔","威廉·彭尼"],place:"澳大利亚蒙特贝洛群岛",state:"英国",sources:["英国内阁1947年1月关于研制原子弹的决议（解密）","英国政府1952年10月关于首次核试验成功的公告"],tags:["核武器","试验","英国"]},related:["world--1949--s01", "world--1963--p01"]},
  {id:"world--1952--d01",track:"world",year:1952,yearApprox:false,dim:"disaster",weight:3,title:"伦敦烟雾事件",summary:"反气旋下的煤烟与雾笼罩五日，超额死亡以万计。",detail:{background:"伦敦冬季长期以家庭燃煤取暖，1952年12月5至9日出现无风逆温，烟尘与二氧化硫在市区积聚。",process:"五日内能见度降至数米，公交与出租停驶、医院超员、殡葬服务排队；据英国登记总署当期统计，8周内死于支气管炎与肺炎者约两千八百七十人，2004年回顾研究以超额死亡口径估算约一万两千人。",impact:"该事件直接推动1956年《清洁空气法》禁止黑烟排放并划定烟尘控制区，也成为大气污染流行病学研究中反复引用的基准案例。",figures:["哈罗德·麦克米伦"],place:"英国伦敦",state:"英国",sources:["英国登记总署1952至1953年周死亡统计报告","Bell、Davis 与 Fletcher, Retrospective Study of Mortality from the London Smog Episode of 1952, Environmental Health Perspectives (2004)"],tags:["烟雾","燃煤","公共卫生"]},related:["world--1956--i01"]},
  {id:"world--1952--a01",track:"world",year:1952,yearApprox:false,dim:"art",weight:2,title:"凯奇《4分33秒》首演",summary:"钢琴家全程不按键，把静默与时间定为作品内容。",detail:{background:"凯奇自1940年代末研究无声与偶然音响，受印度美学与罗伯特·劳森伯格白色绘画的影响。",process:"1952年8月29日在纽约州伍德斯托克莫弗特音乐厅，钢琴家大卫·都铎首演《4分33秒》，全曲分三乐章、依指挥手势开合琴盖而不奏一音，演出时长即标题所示的四分三十三秒。",impact:"该作把音乐的定义从声响组织转向聆听行为与时间界定，直接影响1960年代激浪派、偶发艺术与声景研究，并引发关于作品与演奏的持续法律与美学争论。",figures:["约翰·凯奇","大卫·都铎"],place:"美国纽约州伍德斯托克",state:"美国",sources:["约翰·凯奇《4分33秒》乐谱与首演说明（1952年）","John Cage, Silence: Lectures and Writings (1961)"],tags:["偶发音乐","先锋派","无声"]},related:["world--1962--a01"]},
  {id:"world--1953--p01",track:"world",year:1953,yearApprox:false,dim:"politics",weight:4,title:"斯大林逝世",summary:"最高权力者突然去世，贝利亚兼掌安全机关后被处决。",detail:{background:"1952年10月苏共十九大改组政治局，1953年1月「医生案件」公开，高层处于清洗阴影之下。",process:"1953年3月5日斯大林在莫斯科近郊孔策沃去世，官方诊断为脑出血，3月9日举行国葬；马林科夫任部长会议主席，贝利亚把内务部与国家安全部合并于一身；6月26日贝利亚被逮捕，12月经最高法院特别庭审判后处决。",impact:"集体领导与对安全机关的收权成为新阶段的起点，1956年赫鲁晓夫在二十大作《关于个人崇拜及其后果》报告，苏联对内政策与对外关系均据此转向。",figures:["约瑟夫·斯大林","格奥尔基·马林科夫","拉夫连季·贝利亚","尼基塔·赫鲁晓夫"],place:"苏联莫斯科",state:"苏联",sources:["苏联部长会议与苏共中央1953年3月5日关于斯大林逝世的联合公告","1953年12月贝利亚案审判的新闻报道与官方公报"],tags:["权力交接","苏联","清洗"]},related:["world--1956--p01"]},
  {id:"world--1953--p02",track:"world",year:1953,yearApprox:false,dim:"politics",weight:4,title:"朝鲜停战协定签署",summary:"板门店划非军事区，政治会议条款落空。",detail:{background:"1951年7月10日起开城与板门店谈判长期僵持，焦点是军事分界线与战俘遣返原则。",process:"1953年7月27日，朝中方面代表与联合国军司令在板门店签署《朝鲜军事停战协定》，设军事停战委员会与中立国监察委员会、划定非军事区，并约定三个月后召开政治会议解决朝鲜问题；1954年4至6月日内瓦会议未获政治解决。",impact:"停战把临时军事线固化为长达数十年的分界，半岛未签署和平条约的状态成为此后东北亚安全结构与驻军安排的制度前提。",figures:["马克·克拉克","金日成","彭德怀","南日"],place:"板门店",state:"朝鲜民主主义人民共和国与中国人民志愿军／联合国军与大韩民国",sources:["《朝鲜军事停战协定》（1953年7月27日板门店签署）","1954年日内瓦会议关于朝鲜问题的宣言与会议记录"],tags:["停战","非军事区","半岛"]},related:["world--1950--m01", "world--1954--p01", "cn--1953--m02", "cn--1951--m02"]},
  {id:"world--1953--p03",track:"world",year:1953,yearApprox:false,dim:"politics",weight:3,title:"东德六月十七日事件",summary:"柏林建筑工人罢工蔓延全国，苏联驻军以坦克恢复秩序。",detail:{background:"1952年7月统一社会党第二次代表大会提出「建设社会主义基础」，消费品短缺；5月28日政府决定在不增薪前提下提高劳动定额。",process:"6月16日柏林东区建筑工人罢工要求撤销定额，17日蔓延至莱比锡、哈雷等工业城市，据东德与苏联管制机构档案停工者达数十万人；苏联驻军以坦克与戒严恢复秩序，死亡与逮捕人数各方统计长期存在出入。",impact:"事件后统一社会党放弃部分重工业提速指标，苏联于1953年9月宣布提高民主德国地位、削减驻军并放弃赔偿；该事件在东西德各自的记忆政治中被赋予相反含义。",figures:["瓦尔特·乌布利希","格奥尔基·马林科夫"],place:"柏林（东柏林）、莱比锡、哈雷",state:"德意志民主共和国／苏联驻德管制机构",sources:["苏联内务机构与苏共中央关于1953年6月事件的档案（1990年代公布）","美国中央情报局1953年关于东德罢工与镇压的解密评估报告"],tags:["罢工","坦克","东德"]},related:["world--1953--p01"]},
  {id:"world--1953--p04",track:"world",year:1953,yearApprox:false,dim:"politics",weight:3,title:"摩萨台政府倒台",summary:"德黑兰数日暴动后首相被捕，石油国有化被重新谈判。",detail:{background:"1951年4月伊朗议会通过石油国有化法并封锁英国石油公司资产，出口中断与英方封锁使经济陷入困境。",process:"1953年8月16至19日，国王两次罢免首相、摩萨台解散议会并举行信任公投后，德黑兰爆发规模对立的两派示威；8月19日支持与反对政府的部队及部落力量控制市政府，摩萨台次日被捕，经军事法庭判罪后软禁，扎赫迪重新执政。",impact:"1954年8月伊朗与英美法等组成的国际财团达成协议恢复出口并按比例分成，王室与安全机关的权力自此扩大，1979年革命的反对外资话语以此为历史依据。",figures:["穆罕默德·摩萨台","法兹卢拉·扎赫迪","穆罕默德·礼萨·巴列维"],place:"伊朗德黑兰",state:"伊朗",sources:["美国参议院政府活动委员会《对外情报机构活动》第2编（1976年，丘奇委员会）","1954年8月《关于伊朗石油财团协议的声明》文本"],tags:["石油国有化","政变","伊朗"]},related:["world--1951--m01"]},
  {id:"world--1953--s01",track:"world",year:1953,yearApprox:false,dim:"science",weight:5,title:"DNA双螺旋结构发表",summary:"《自然》同期刊出三篇论文，确立碱基配对的复制机制。",detail:{background:"艾弗里1944年与赫尔希-蔡斯1952年的实验指向DNA是遗传物质，查加夫1950年的碱基比例法则与国王学院的衍射数据提供结构线索。",process:"1953年4月25日《自然》第171卷同期刊登沃森与克里克的双螺旋模型论文、威尔金斯等组的衍射研究以及富兰克林与戈斯林的数据论文，模型以两条反向平行链与腺嘌呤-胸腺嘧啶、鸟嘌呤-胞嘧啶配对构成。",impact:"碱基互补把遗传信息表述为可复制的序列，1958年梅塞尔森与斯塔尔实验验证半保留复制，分子生物学由此成为独立学科。",figures:["詹姆斯·沃森","弗朗西斯·克里克","罗莎琳·富兰克林","莫里斯·威尔金斯"],place:"英国剑桥与伦敦",state:"英国／美国",sources:["Watson 与 Crick, Molecular Structure of Nucleic Acids, Nature 171 (1953) 第737至738页","Franklin 与 Gosling 同期刊于 Nature 171 的分子构型论文"],tags:["分子生物学","DNA","结构"]},related:["world--1953--s02", "world--1961--s01"]},
  {id:"world--1953--s02",track:"world",year:1953,yearApprox:false,dim:"science",weight:3,title:"米勒模拟原始大气实验",summary:"电火花作用于还原性混合气，一周内生成多种氨基酸。",detail:{background:"奥巴林1920年代提出早期海洋由无机物逐步合成有机物的假说，尤里关于还原性大气的判断提供了实验前提。",process:"1953年米勒在尤里指导下，使甲烷、氨、氢与水蒸气循环通过电火花并冷凝收集，约一周后检出甘氨酸等五种氨基酸，成果以《在可能原始地球条件下氨基酸的生成》发表于《科学》第117卷。",impact:"该实验使生命起源研究转为可在实验室重复并检验的化学问题，1953年以后的前生物合成与RNA世界争论皆以其装置与限制条件为参照。",figures:["斯坦利·米勒","哈罗德·尤里"],place:"美国芝加哥大学",state:"美国",sources:["Miller, A Production of Amino Acids Under Possible Primitive Earth Conditions, Science 117 (1953)","奥巴林《生命的起源》（1924年俄文初版，1936年英文版）"],tags:["生命起源","化学演化","实验"]},related:["world--1953--s01"]},
  {id:"world--1954--p01",track:"world",year:1954,yearApprox:false,dim:"politics",weight:4,title:"日内瓦会议结束印度支那战事",summary:"中苏美英法与会划界停火，法国撤出中南半岛。",detail:{background:"朝鲜停战后印度支那战事未决，1954年2月柏林外长会议决定召开有苏联、美国、英国、法国及交战各方参加的国际会议。",process:"会议于1954年5月8日至7月21日在日内瓦万国宫举行；奠边府陷落三天后，与会方签署恢复印度支那和平宣言与逐项停战协定，将越南临时军事分界线划在北纬17度附近，并规定1956年7月前举行全国自由选举。",impact:"法国军队撤出越南，越南、老挝、柬埔寨分别停火；美国未在最后宣言上签字，此后以南越为扶植重点，统一选举未举行成为新一轮介入的起点。",figures:["彼得·孟戴斯-弗朗斯","周恩来","约翰·福斯特·杜勒斯"],place:"瑞士日内瓦",state:"多国会议",sources:["《恢复印度支那和平的日内瓦宣言》（1954年7月21日）及所附停止敌对行动协定","Fredrik Logevall, Embers of War: The Fall of an Empire and the Making of America's Vietnam (2012)"],tags:["日内瓦","停火","分裂"]},related:["world--1954--m01", "world--1953--p02", "cn--1954--p04", "cn--1953--p02"]},
  {id:"world--1954--m01",track:"world",year:1954,yearApprox:false,dim:"military",weight:4,title:"奠边府战役与守军投降",summary:"越盟以重炮与近迫作业包围河谷据点，5月7日陷之。",detail:{background:"1953年11月法军空降奠边府并构筑据点群，意图切断越盟通往老挝的通道并诱其决战；该河谷仅靠两个机场空投维持补给。",process:"1954年3月13日越盟发起进攻，以人力牵引火炮进入山地阵地并挖掘交通壕逐步压缩机场与指挥所；在苏联与中国的炮兵、防空与后勤支援下于5月7日攻入指挥中心，守军指挥部投降。",impact:"战役直接推动日内瓦协议签订，法国在中南半岛的军事存在终结；法国方面档案记录己方阵亡、伤病与被俘数以万计，越盟伤亡数字各方估算差异较大。",figures:["武元甲","克里斯蒂安·德·卡斯特里"],place:"越南奠边府",state:"越南／法国",sources:["法国国防部历史服务处藏奠边府作战与参谋档案","Bernard Fall, Street Without Joy: An History of the French Indochina Campaign 1946–1954 (1961)"],tags:["围城","炮兵","印度支那"]},related:["world--1946--m01", "world--1954--p01", "cn--1954--p04"]},
  {id:"world--1954--p02",track:"world",year:1954,yearApprox:false,dim:"politics",weight:3,title:"参议院通过谴责麦卡锡决议",summary:"以67票对22票认定其言行有辱参议院声誉。",detail:{background:"1950年以来麦卡锡以国务院、军队与广播系统内的忠诚指控持续施压，1954年4至6月的军队听证会经电视直播，其质询方式引发公众反弹。",process:"中期选举后由参议员阿瑟·沃特金斯主持特别委员会复审各项指控，1954年12月2日参议院以67票对22票通过谴责决议，认定其针对参议院及该委员会的言论有辱参议院声誉，并要求其不再担任委员会主席。",impact:"谴责后麦卡锡的调查权与舆论影响迅速衰减，1957年5月去世；这一表决成为立法机构内部对忠诚调查扩张作出制度性纠正的少数记录之一。",figures:["约瑟夫·麦卡锡","阿瑟·沃特金斯"],place:"美国华盛顿",state:"美国",sources:["美国参议院1954年12月2日谴责决议及表决记录（第83届国会第2会期）","美国参议院历史办公室：1954年参议院对麦卡锡的谴责"],tags:["参议院","忠诚调查","谴责"]},related:["world--1950--p04"]},
  {id:"world--1954--p03",track:"world",year:1954,yearApprox:false,dim:"politics",weight:3,title:"阿尔及利亚民族解放阵线起事",summary:"11月1日多地同时袭击，战争自此开始。",detail:{background:"1947年阿尔及利亚组织法未能开放政治空间，同年选后暴力事件镇压了温和独立派；1954年3月流亡骨干秘密成立团结与行动革命委员会。",process:"1954年11月1日晨，民族解放阵线在奥雷斯山区等地同时发动数十次袭击，并发表告阿尔及利亚人民书，要求恢复国家主权；法国政府同日宣布紧急措施，议会随后授权增拨经费与治安权力。",impact:"战争以乡村清剿、空袭与强制集中营等方式展开，1956年后升级并外溢至摩洛哥、突尼斯边界及法国本土政治；至1962年停火，双方公布的死亡人数估算差距极大。",figures:["艾哈迈德·本·贝拉","阿巴内·拉姆达纳"],place:"阿尔及利亚奥雷斯山区",state:"法国／阿尔及利亚",sources:["民族解放阵线1954年11月1日《告阿尔及利亚人民书》","Matthew Connelly, A Diplomatic Revolution: Algeria's Fight for Independence and the Origins of the Post-Cold War Era (2002)"],tags:["起义","殖民战争","民族解放阵线"]},related:["world--1954--p01", "world--1955--p03"]},
  {id:"world--1954--i01",track:"world",year:1954,yearApprox:false,dim:"institution",weight:3,title:"最高法院裁定公立学校隔离违宪",summary:"一致判决推翻教育领域的隔离但平等先例。",detail:{background:"1930年代起全国有色人种协进会以判例逐步攻击高等教育中的种族隔离，1951年托皮卡家长就黑人学童乘车与学区分离提起诉讼，1952年四案并审。",process:"1954年5月17日首席大法官厄尔·沃伦代笔全体一致意见，认定仅因种族而将儿童隔离于公立学校即剥夺平等法律保护，推翻1896年普莱西诉弗格森案在教育领域的先例；次年另以审慎速度裁定执行方式。",impact:"南方多州以大规模抵制回应，1957年小石城事件需联邦军队护送入学；本判决成为此后民权立法与诉讼策略的宪法依据。",figures:["瑟古德·马歇尔","厄尔·沃伦"],place:"美国华盛顿",state:"美国",sources:["Brown v. Board of Education, 347 U.S. 483 (1954) 判决书及1955年救济裁定","Richard Kluger, Simple Justice: The History of Brown v. Board of Education and Black America's Struggle for Equality (1975)"],tags:["判决","种族隔离","教育"]},related:["world--1955--p05", "world--1948--p03"]},
  {id:"world--1954--a01",track:"world",year:1954,yearApprox:false,dim:"art",weight:2,title:"《七武士》公映并获威尼斯银狮",summary:"三小时群像片成为日本电影国际流通样板。",detail:{background:"《罗生门》1951年获威尼斯金狮奖后，东宝公司支持黑泽明拍摄战国题材群像片，以票房回收弥补超支的制片预算。",process:"1954年4月26日《七武士》在日本公映，片长约三小时二十分钟，写七名武士受雇护卫屡遭贼盗掠夺的山村；同年9月在威尼斯国际电影节获银狮奖。",impact:"影片确立了此后被多国类型电影反复改编的护卫叙事框架，其外景调度与多机位剪辑成为战后日本电影的技术参照；1956年美国剪辑版以较短片长上映并带动重映。",figures:["黑泽明","三船敏郎"],place:"日本东京与意大利威尼斯",state:"日本",sources:["东宝株式会社《七武士》制作与发行档案（1954年）","威尼斯国际电影节1954年度获奖记录","John D. Borders, The Films of Akira Kurosawa (1983)"],tags:["日本电影","群像","电影节"]},related:["world--1951--a01"]},
  {id:"world--1954--s01",track:"world",year:1954,yearApprox:false,dim:"science",weight:3,title:"首座并网核电站在奥布宁斯克运行",summary:"石墨水冷小型反应堆并入莫斯科电网持续供电。",detail:{background:"苏联把军用钚生产堆的技术积累转向民用，科学院相关设计单位提出小型石墨慢化、水冷却反应堆方案并配套建设实验设施。",process:"1954年6月27日奥布宁斯克第一原子能电站并入电网持续发电，热功率约三十兆瓦、电功率约五兆瓦，同时承担供热与中子物理实验任务。",impact:"核能利用由武器扩展到发电与供热，1956年英国考尔德霍尔与苏联别洛亚尔斯克等电站相继建成，核电在各国能源结构中的份额自此进入官方统计序列。",figures:["伊戈尔·库尔恰托夫","德米特里·布洛欣采夫"],place:"苏联卡卢加州奥布宁斯克",state:"苏联",sources:["苏联科学院关于第一座原子能电站投入运行的公报（1954年）","国际原子能机构动力堆信息系统所载奥布宁斯克机组投运与容量记录"],tags:["核电","并网","和平利用原子能"]},related:["world--1949--s01"]},
  {id:"world--1955--p01",track:"world",year:1955,yearApprox:false,dim:"politics",weight:4,title:"华沙友好合作互助条约签署",summary:"八国在华沙结成与北约对口的军事同盟。",detail:{background:"1954年10月巴黎协定批准联邦德国加入北约，苏联与东欧各国先以宣言反对，又在协定生效前召集欧洲各国安全会议商量对策。",process:"1955年5月14日苏联、波兰、捷克斯洛伐克、德意志民主共和国、罗马尼亚、匈牙利、保加利亚与阿尔巴尼亚在华沙签署条约，设立政治协商委员会与联合武装部队总司令部，总司令一职由苏联军官担任。",impact:"条约为苏联在东欧驻军与统一指挥提供了法律依据，1956年匈牙利与1968年捷克斯洛伐克事件中的行动皆援引其机制；阿尔巴尼亚于1968年宣布退出。",figures:["克利门特·伏罗希洛夫","瓦西里·索科洛夫斯基"],place:"波兰华沙",state:"苏联与东欧七国",sources:["《友好合作互助条约》（1955年5月14日华沙签署）条约正文","苏联《真理报》1955年5月15日刊载的华沙会议公报全文"],tags:["军事同盟","联合司令部","驻军"]},related:["world--1949--p02", "world--1955--p02"]},
  {id:"world--1955--p02",track:"world",year:1955,yearApprox:false,dim:"politics",weight:3,title:"巴黎协定生效，西德恢复主权",summary:"联邦德国加入北约，占领法规同步终止。",detail:{background:"1952年签署的欧洲防务共同体条约于1954年8月30日被法国国民议会否决，美英在伦敦九国会议提出替代方案，1954年10月23日各签约方于巴黎签署一揽子协定。",process:"1955年5月5日至6日协定先后生效：联邦德国取得主权并加入北大西洋公约组织，占领法规由驻德部队关系公约取代，英法结束对科隆的占领，西德获准在本土生产限定类别常规武器但不得拥有核武器。",impact:"北约前沿推进至中欧，苏联以华沙条约回应，欧洲两大军事集团的地理分界自此固定；西德军力建设随后纳入北约军事一体化框架。",figures:["康拉德·阿登纳","安东尼·艾登"],place:"波恩、巴黎与伦敦",state:"德意志联邦共和国",sources:["《巴黎协定》（1954年10月23日）文本与1955年5月生效换文","德意志联邦共和国政府关于主权恢复与驻军关系的政府声明（1955年5月）"],tags:["主权","北约","占领法规"]},related:["world--1949--p01", "world--1955--p01"]},
  {id:"world--1955--p03",track:"world",year:1955,yearApprox:false,dim:"politics",weight:4,title:"亚非会议在万隆召开",summary:"二十九国通过十项原则，自居第三种力量。",detail:{background:"1954年12月科伦坡五国外长在茂物发表声明倡议召开亚非会议，埃及、南斯拉夫与中华人民共和国等受邀，议程围绕殖民主义、和平共处与种族歧视展开。",process:"1955年4月18日至24日二十九国代表在印度尼西亚万隆开会，中国代表团在4月19日发言中提出求同存异；闭幕公报通过以和平共处五项原则为基底的十项原则，确认尊重主权与不干涉内政。",impact:"会议把印度支那、阿尔及利亚与巴勒斯坦问题列入同一议程，形成此后不结盟运动的组织基础；其措辞此后进入联合国大会非殖民化决议的语言。",figures:["周恩来","贾瓦哈拉尔·尼赫鲁","苏加诺"],place:"印度尼西亚万隆",state:"亚非二十九国",sources:["万隆会议最后公报与促进世界和平与合作十项原则（1955年4月24日）","科伦坡五国外长茂物声明（1954年12月28日至29日）"],tags:["不结盟","十项原则","亚非"]},related:["world--1954--p03", "cn--1955--p05"]},
  {id:"world--1955--p04",track:"world",year:1955,yearApprox:false,dim:"politics",weight:2,title:"四国日内瓦峰会与开放天空案",summary:"四大国十六年后复会，裁军议程无协议告终。",detail:{background:"1954年柏林外长会议同意举行四大国政府首脑会谈，预定议程为德国问题、欧洲安全、裁军与东西方接触。",process:"1955年7月18日至23日，艾森豪威尔、布尔加宁、艾登与富尔在日内瓦会谈；艾森豪威尔于7月21日提出相互空中侦察计划，要求交换军事设施平面图并允许无武装机组飞行视察，苏联主张先行禁止核武器试验，会议未达成协议。",impact:"峰会未解决德国与裁军问题，但恢复了最高级别对话渠道；开放天空建议未被接受，其核查思路在此后的军控谈判与技术手段发展中反复被引用。",figures:["德怀特·艾森豪威尔","尼古拉·布尔加宁","埃德加·富尔"],place:"瑞士日内瓦",state:"美国／苏联／英国／法国",sources:["1955年日内瓦四国首脑会议公报与记者会记录","美国国务院《美国对外关系文件》1955–1957年第11卷所载开放天空案文件"],tags:["峰会","裁军","核查"]},related:["world--1955--p01"]},
  {id:"world--1955--p05",track:"world",year:1955,yearApprox:false,dim:"politics",weight:2,title:"蒙哥马利公交车抵制开始",summary:"帕克斯被捕后，当地黑人社区抵制381天。",detail:{background:"1954年布朗案判决后南方隔离制度承压，1955年12月1日蒙哥马利裁缝罗莎·帕克斯因拒绝在车上让座被捕，当地妇女政治会议早有抵制预案。",process:"12月5日起由新成立的蒙哥马利改进协会组织全面抵制，黑人居民步行或乘合用车，教堂承担集会与募款；1956年6月联邦地区法院判决巴士隔离违宪，12月最高法院予以维持，12月21日抵制结束。",impact:"持续381天的抵制促成南方基督教领袖会议1957年成立，金由此进入全国政治；非暴力直接行动与司法诉讼结合成为民权运动的常规做法。",figures:["罗莎·帕克斯","马丁·路德·金"],place:"美国亚拉巴马州蒙哥马利",state:"美国",sources:["美国亚拉巴马中区联邦地区法院布劳德诉盖尔案判决书（1956年）及最高法院维持裁定","Aldon D. Morris, The Origins of the Civil Rights Movement (1984)"],tags:["抵制","民权","非暴力"]},related:["world--1954--i01"]},
  {id:"world--1955--s01",track:"world",year:1955,yearApprox:false,dim:"science",weight:3,title:"脊髓灰质炎灭活疫苗获准使用",summary:"现场试验覆盖约180万儿童，接种随即推开。",detail:{background:"脊髓灰质炎在欧美每年夏季流行，1952年美国报告病例约5.7万例；索尔克在匹兹堡大学研制灭活疫苗，1954年由公共卫生机构组织大规模现场试验。",process:"1955年4月12日试验结果公布并颁发生产许可，各州展开儿童接种；同年5月加州伯克利一家药厂部分批次灭活不彻底，造成接种儿童及其家庭成员瘫痪，即卡特实验室事件。",impact:"美国报告病例由1952年约5.7万例降至1960年代初的千例以下，1961年后口服减毒活疫苗取代注射疫苗；卡特事件促成联邦强化生物制品批签发与现场检查。",figures:["乔纳斯·索尔克","托马斯·弗朗西斯"],place:"美国匹兹堡与加利福尼亚伯克利",state:"美国",sources:["美国公共卫生局与全国小儿麻痹基金会1954年现场试验报告（1955年4月公布）","美国国会与公共卫生部门关于1955年脊髓灰质炎疫苗事件的调查记录"],tags:["疫苗","公共卫生","脊髓灰质炎"]},related:["world--1954--s01"]},
  {id:"world--1955--c01",track:"world",year:1955,yearApprox:false,dim:"culture",weight:2,title:"《洛丽塔》在巴黎初版",summary:"美国出版商拒稿后由巴黎出版社刊行，随即遭查禁。",detail:{background:"纳博科夫在美国大学任教期间以英文写作该小说，1954年至1955年间多家美国出版商因题材拒稿，最终由巴黎一家出版社列入外文丛书印行。",process:"1955年9月巴黎初版问世，随后在法国与英国被查禁，1958年由美国出版商正式刊行；各国查禁、没收与诉讼过程使该书成为出版审查讨论中的常引案例。",impact:"小说的叙事视角与道德距离成为此后文学批评的长期题目，1962年库布里克改编电影进一步扩大争议；其出版与查禁史被用作战后跨大西洋审查与版权流通的样本。",figures:["弗拉基米尔·纳博科夫"],place:"法国巴黎与美国纽约",state:"法国／美国",sources:["Lolita, Olympia Press (Paris, 1955) 初版版权页与书志记录","Brian Boyd, Vladimir Nabokov: The American Years (1991)"],tags:["小说","审查","跨大西洋"]},related:[]},
  {id:"world--1955--a01",track:"world",year:1955,yearApprox:false,dim:"art",weight:2,title:"首届文献展在卡塞尔开幕",summary:"以二十世纪常设展重建西德与现代艺术的联系。",detail:{background:"1955年卡塞尔举办联邦园艺展，画家阿尔诺德·博德提议同期以大型现代艺术展恢复曾被纳粹定为退化的艺术传统，获市方与联邦州政府支持。",process:"首届文献展于1955年7月2日至9月18日开放，按二十世纪各阶段分室陈列绘画、雕塑与图形作品，重新展出毕加索、克利与德国表现主义诸家，不设竞赛性奖项。",impact:"文献展此后以四年为周期，与威尼斯双年展并列成为欧洲大型国际展体制的一部分；其公共资助与学术委员会模式成为战后西德文化重建的可核查样本。",figures:["阿尔诺德·博德"],place:"德国卡塞尔",state:"德意志联邦共和国",sources:["首届文献展展览目录与展厅平面图（卡塞尔，1955年）","卡塞尔市档案馆关于1955年文献展筹备与资助的市政决议"],tags:["展览","现代艺术","公共资金"]},related:["world--1955--c01"]},
  {id:"world--1956--p01",track:"world",year:1956,yearApprox:false,dim:"politics",weight:5,title:"苏共二十大与赫鲁晓夫秘密报告",summary:"闭幕夜的报告列举大镇压数字，传达至全党各层级。",detail:{background:"斯大林死后贝利亚案与平反委员会已启动部分复权，1956年2月14至26日苏共二十大概召开，主席团内围绕个人崇拜问题的材料收集持续一年。",process:"2月25日深夜闭幕会议上，赫鲁晓夫宣读《关于个人崇拜及其后果》报告，援引十七大增选与代表数据称139名中央委员及候补委员中98名被捕并被枪决，并列举1937至1938年镇压与二战初期的指挥失误。",impact:"报告以党内传达朗读的方式扩散，动摇东欧各国党的合法性论述；同年6月30日苏共中央作出决议，把责任归于斯大林个人及其亲近者。",figures:["尼基塔·赫鲁晓夫","拉扎尔·卡冈诺维奇"],place:"苏联莫斯科",state:"苏联",sources:["赫鲁晓夫1956年2月25日《关于个人崇拜及其后果》报告文本（美国国务院1956年6月刊布译本）","俄罗斯国家当代史档案馆藏苏共中央1956年6月30日决议及传达指示"],tags:["个人崇拜","平反","档案数字"]},related:["world--1953--p01", "world--1956--p03"]},
  {id:"world--1956--p02",track:"world",year:1956,yearApprox:false,dim:"politics",weight:5,title:"匈牙利十月事件与苏军再入",summary:"10月23日示威升级为武装冲突，11月4日苏军进占布达佩斯。",detail:{background:"拉科西时期的工业指标压低消费，1953年后纳吉的让步与其去职激化不满；10月23日声援波兰的示威由大学与裴多菲俱乐部发起。",process:"10月23日斯大林雕像被拉倒，保安部队开枪后冲突扩大；10月30日至11月1日纳吉政府宣布结束一党制并退出华沙条约；11月4日苏军以旋风行动进占布达佩斯，卡达尔另组政府，11月中旬战斗结束。",impact:"据联合国特别委员会1957年报告与1990年代开放的匈苏档案，匈方死亡约两千至三千人，苏军阵亡数百人，约二十万人离境；纳吉等于1958年6月被处决。",figures:["纳吉·伊姆雷","卡达尔·亚诺什"],place:"布达佩斯与匈牙利各州",state:"匈牙利／苏联",sources:["联合国《匈牙利问题特别委员会报告》（1957年，大会正式文件）","1956年匈牙利事件苏联方面决策与行动档案（1990年代公布选编）"],tags:["起义","华沙条约","武装干预"]},related:["world--1956--p01", "world--1955--p01"]},
  {id:"world--1956--p03",track:"world",year:1956,yearApprox:false,dim:"politics",weight:3,title:"波兹南罢工与哥穆尔卡复职",summary:"六月工人要求面包与改革遭开枪，十月党内改组完成。",detail:{background:"1955年波兰重工业指标与农产品征购同时收紧，斯大林格勒厂（原波兹南工厂）工人自6月初开始罢工请愿，要求调高工资与退税。",process:"1956年6月28日清晨波兹南工人游行前往省委与监狱，军警开枪，官方统计死亡五十余人、伤者数百；10月19日中央全会选举哥穆尔卡为第一书记，苏联代表团当日抵达华沙，10月21日达成不进一步军事干预的协议。",impact:"事件使波兰获得集体农庄化放缓、宗教组织空间与有限新闻放开的让步，其模式与同年匈牙利的结局构成两种结果；11月苏波签订驻军新协定。",figures:["瓦迪斯瓦夫·哥穆尔卡","罗科索夫斯基"],place:"波兰波兹南与华沙",state:"波兰",sources:["波兰统一工人党1956年7月关于波兹南事件的中央全会决议与官方调查材料","1956年10月苏波会谈记录（俄罗斯国家当代史档案馆藏，1990年代公布）"],tags:["罢工","党内改组","驻军协定"]},related:["world--1956--p01", "world--1956--p02"]},
  {id:"world--1956--p04",track:"world",year:1956,yearApprox:false,dim:"politics",weight:4,title:"纳赛尔宣布苏伊士运河国有化",summary:"贷款被撤三日后，埃及接管运河公司并宣布补偿股份持有者。",detail:{background:"世界银行与美英的贷款条件谈判持续一年，7月19日美国宣布撤销提议，英国跟进；埃及把运河公司利润视为本国资金来源。",process:"1956年7月26日纳赛尔在亚历山大发表演讲，宣布依1888年君士坦丁堡公约与1954年英埃协定将苏伊士运河国际公司收归国有，由运河管理机构接管运营，并向股份持有者提供等额补偿。",impact:"英法以冻结埃及海外资产、停止运河通行与提出国际管制方案回应；10月13日安全理事会就埃方提案的表决草案因英法否决未获通过，两周后战争爆发。",figures:["贾迈勒·阿卜杜勒·纳赛尔","克里斯蒂安·皮诺"],place:"埃及亚历山大与塞得港",state:"埃及",sources:["埃及共和国1956年7月26日关于苏伊士运河公司国有的法令文本","1888年君士坦丁堡公约关于战时与平时运河通行的条款（埃及方面引用文件）"],tags:["国有化","运河","股份补偿"]},related:["world--1956--e01", "world--1956--m01"]},
  {id:"world--1956--m01",track:"world",year:1956,yearApprox:false,dim:"military",weight:4,title:"苏伊士战争与紧急部队进驻",summary:"三阶段空降与西奈攻势在联大干预下十一月初停火。",detail:{background:"1956年7月起英法以三国就运河问题秘密协调；10月30日至31日安理会两份停火草案分别遭苏联与英法否决。",process:"10月29日以军横穿西奈至米特拉山口，31日英法空军轰炸埃及机场，11月5日至6日英法伞兵在塞得港空降登陆；联合国紧急部队于11月15日后接防，12月22日英法军最后撤离。",impact:"以色列1957年3月完成从西奈与加沙撤军，紧急部队驻守至1967年5月；此役显示英法的军事投射已无法脱离美国财政与外交条件，苏联以核威胁言论抬高地区地位。",figures:["摩西·达扬","安东尼·艾登","贾迈勒·阿卜杜勒·纳赛尔"],place:"西奈半岛、塞得港与加沙",state:"埃及／英国／法国／以色列",sources:["联合国大会第一届紧急特别会议第998号与第1001号决议（1956年11月）","英国议会辩论记录（1956年11月至1957年3月关于塞得港与西奈行动的答辩）"],tags:["空降","停火","紧急部队"]},related:["world--1956--p04", "world--1951--m01"]},
  {id:"world--1956--f01",track:"world",year:1956,yearApprox:false,dim:"figure",weight:3,title:"纳吉·伊姆雷的最后四十八小时",summary:"11月4日清晨两次广播求援，次日被劫出使馆处决在两年后。",detail:{background:"纳吉1953年6月至1955年4月任部长会议主席，因农业与民族政策被撤职并开除党籍，10月27日夜被卡达尔阵营推入总理职位。",process:"11月4日清晨5时许与4时50分，纳吉两次在广播中呼告匈牙利人民与各国人民，宣布苏军入侵并要求联合国大会审议；同日进入南斯拉夫大使馆避难，11月22日在使馆安全通行承诺下离开时被掳。",impact:"1958年6月16日以叛国罪被处决；1989年6月16日遗骸归国重新安葬，同日匈牙利共和国宣布成立，纳吉案在1960年代起的历次平反文件中被重新定性。",figures:["纳吉·伊姆雷"],place:"布达佩斯",state:"匈牙利",sources:["纳吉1956年11月4日广播呼告词文本与后续审判记录（1958年）","匈牙利最高法庭1989年关于纳吉等人案件复审与平反的裁定"],tags:["广播","审判","平反"]},related:["world--1956--p02"]},
  {id:"world--1956--i01",track:"world",year:1956,yearApprox:false,dim:"institution",weight:3,title:"英国通过1956年清洁空气法",summary:"以烟煤控制区与黑烟禁令回应四年前的烟雾事件。",detail:{background:"1952年12月伦敦烟雾后的皇家空气污染委员会于1954年提出以燃气与无烟燃料替代家庭散煤、划定烟尘控制区的建议。",process:"《1956年清洁空气法》于1956年7月19日获御准，授权地方政府划定烟尘控制区、禁止在该区燃用烟煤并给予改装炉具与迁居补助，同时禁止工业与家庭排放黑烟。",impact:"该法把空气污染写成可执法的公共危害，其烟尘控制区模式在1957至1960年代为英联邦与欧洲多国立法引用；伦敦地区1960年代冬季浓烟雾日数明显下降，1968年另立新法扩展管制范围。",figures:["哈罗德·麦克米伦"],place:"英国伦敦",state:"英国",sources:["英国《1956年清洁空气法》文本（1956年御准）","英国空气污染委员会报告（1954年，议会文件）"],tags:["环境立法","烟尘控制区","燃煤"]},related:["world--1952--d01"]},
  {id:"world--1956--i02",track:"world",year:1956,yearApprox:false,dim:"institution",weight:3,title:"国际原子能机构规约开放签署",summary:"十八国在纽约签署规约，核查与援助双职并立。",detail:{background:"1953年12月美国提出原子能和平利用计划，1954年伦敦八国会议与1955年日内瓦和平利用原子能会议为规约草案铺路。",process:"1956年8月20日至10月21日纽约会议通过规约，10月26日开放签署，1957年7月29日生效；机构设总干事、理事会与大会，职权为促成民用核能合作并对受援项目施用保障监督。",impact:"机构1957年11月召开首届大会并开始执行核燃料与技术支持计划，其保障监督制度成为1968年《不扩散核武器条约》第三条所采用的核查模式的技术底座。",figures:["威廉·拜尔霍费尔"],place:"美国纽约",state:"国际组织",sources:["《国际原子能机构规约》（1956年10月26日纽约开放签署，1957年7月29日生效）","1955年日内瓦和平利用原子能会议文件与1953年12月8日美国关于原子能和平利用的演说"],tags:["核查","民用核能","国际组织"]},related:["world--1954--s01"]},
  {id:"world--1956--i03",track:"world",year:1956,yearApprox:false,dim:"institution",weight:3,title:"联合国紧急部队成军",summary:"紧急特别会议以条例组建首支联合国武装。",detail:{background:"1956年10月30日至31日安理会停火草案因否决权未能通过，联大依1950年第377(V)号决议召开第一届紧急特别会议处理苏伊士局势。",process:"大会11月4日请秘书长在三十日内提出组建紧急部队的方案，11月7日批准部队条例，明确其以联合国旗帜行动、经东道国同意驻留、仅以自卫使用武力；11月15日后首批部队进入运河区，由加拿大将领伯恩斯任指挥官。",impact:"这支部队确立了维和行动的三项基本原则与大会主导的先例，1960年刚果行动与1973年第二次紧急部队沿用其指挥模式。",figures:["达格·哈马舍尔德","埃洛·伯恩斯"],place:"塞得港与纽约联合国总部",state:"联合国",sources:["联合国大会第一届紧急特别会议第998号与第1001号决议及部队条例（1956年11月）","联合国秘书长1956年11月关于组建紧急部队的报告"],tags:["维和","部队条例","自卫"]},related:["world--1956--m01", "world--1946--p02"]},
  {id:"world--1956--s01",track:"world",year:1956,yearApprox:false,dim:"science",weight:2,title:"IBM 305 RAMAC 硬盘装置交付",summary:"五十片磁盘构成随机存取单元，容量以五百万字符计。",detail:{background:"1950年代初期计算机以外存储为纸带与磁鼓，随机存取大容量数据的需求来自库存、账务与银行批处理场景。",process:"1956年9月美国国际商用机器公司发布305型RAMAC数据处理机，其配用的350磁盘存储装置以五十片可旋转磁盘与单读写臂构成，标称容量约五百万字符，整机重量以吨计。",impact:"磁盘随机存取使联机库存与账务处理在技术上可行，1962年IBM 1301与1311把该路线产品化，此后硬盘的单位容量成本下降成为1970年代小型机与个人计算机的前提条件之一。",figures:["托马斯·瓦特森"],place:"美国圣何塞",state:"美国",sources:["美国IBM公司1956年《RAMAC 305型电子数据处理机》产品说明书（史密森学会美国历史博物馆藏）","美国康奈尔大学计算机历史图书馆藏IBM 305 RAMAC 技术资料"],tags:["硬盘","随机存取","数据处理"]},related:["world--1951--s01"]},
  {id:"world--1956--c01",track:"world",year:1956,yearApprox:false,dim:"culture",weight:2,title:"第一张摇滚专辑登上美国排行榜",summary:"唱片与电视把节奏布鲁斯推向白人青少年市场。",detail:{background:"1951年起克利夫兰与纽约的电台开始播放节奏布鲁斯曲目，1954至1955年孟菲斯的小型唱片公司以混合曲目打开南部市场。",process:"1956年1月单曲在RCA胜利公司发行后登上流行榜首位，3月发行首张同名专辑，9月起在全国电视综艺节目中出演；唱片公司与电视节目在同期把黑人艺人的曲目转由白人歌手翻唱发行。",impact:"唱片与电视的复合渠道使摇滚乐在数年内进入西欧、日本与拉美的青年文化，1957年起各国出现本土化翻唱与审查争议；唱片工业的销售分级与青年消费市场由此定型。",figures:["埃尔维斯·普雷斯利"],place:"美国孟菲斯与纽约",state:"美国",sources:["RCA胜利公司1956年3月发行的首张同名专辑原版封套与曲目表","Peter Guralnick, Last Train to Memphis: The Rise of Elvis Presley (1994)"],tags:["唱片","电视","青年文化"]},related:["world--1952--a01"]},
  {id:"world--1956--e01",track:"world",year:1956,yearApprox:false,dim:"economy",weight:3,title:"美国撤销阿斯旺高坝贷款提议",summary:"条件谈判破裂三日后撤贷，埃及以运河收入取而代之。",detail:{background:"1955年末美国与英国同意为阿斯旺高坝提供头期贷款，世界银行则要求以硬通货偿还并承认1891年与1929年尼罗水协定下的既得水量。",process:"1956年7月18日至19日美国国务院宣布撤回贷款提议，理由包括埃及的支付能力、货币不稳定及其对东欧粮食采购的信贷安排；英国随后表示不再参与。",impact:"埃及以运河国有化与通行费作为坝体资金来源，并把尼罗水谈判推迟；撤贷与国有化在十周内演变为军事冲突，此后世界银行在中东的基础设施融资更强调多边担保。",figures:["约翰·福斯特·杜勒斯","尤金·布莱克"],place:"美国华盛顿与埃及开罗",state:"美国／埃及",sources:["美国国务院1956年7月19日关于撤销阿斯旺贷款提议的声明与新闻稿","埃及政府1956年关于高坝资金与运河收入的公开说明"],tags:["贷款","尼罗河","基建融资"]},related:["world--1956--p04"]},
  {id:"world--1957--p01",track:"world",year:1957,yearApprox:false,dim:"politics",weight:4,title:"六国签署罗马条约",summary:"共同市场与原子能共同体并立，过渡期十二年。",detail:{background:"1955年6月墨西拿会议决定把煤钢共同体的方法推广至全面经济一体化，1956年起由斯巴克委员会起草两部条约。",process:"1957年3月25日六国在罗马签署《欧洲经济共同体条约》与《欧洲原子能共同体条约》，规定十二年过渡期内逐步取消内部关税并设共同农业政策，1958年1月1日生效。",impact:"共同体委员会与部长理事会并行运转，1962年7月共同农业政策市场组织实施；1965至1966年的空座危机迫使各方就表决规则妥协，两种路线的分歧延续至后来历次条约。",figures:["沃尔特·哈尔施泰因","保罗-亨利·斯巴克","克里斯蒂安·皮诺"],place:"意大利罗马",state:"欧洲六国",sources:["Treaty establishing the European Economic Community（1957年3月25日罗马签署）正式文本","Alan S. Milward, The European Rescue of the Nation-State (1992)"],tags:["共同市场","超国家","农业政策"]},related:["world--1951--p01", "world--1955--p02"]},
  {id:"world--1957--s01",track:"world",year:1957,yearApprox:false,dim:"science",weight:5,title:"第一颗人造地球卫星入轨",summary:"83.6千克球体九十二分钟一圈，无线电信号被全球接收。",detail:{background:"苏联在洲际火箭基础上改用运载体型号，国际地球物理年苏联委员会自1956年起预告将发射结构简单的卫星；总设计师姓名当时未公开。",process:"1957年10月4日拜科努尔发射场把直径58厘米、重83.6千克的斯普特尼克一号送入周期约92分钟的轨道，以20与29兆赫连续发报三周；11月3日第二颗卫星携犬莱卡入轨。",impact:"美国12月6日先锋号在发射台上失败，1958年2月国会听证追究军种责任，7月立法设立国家航空与航天局并把民用航天自军方分出；科学资助与课程改革的争论同时展开。",figures:["米哈伊尔·克尔德什","谢尔盖·科罗廖夫"],place:"苏联拜科努尔",state:"苏联",sources:["塔斯社1957年10月4日关于第一颗人造地球卫星的公报","美国海军研究实验室1957年12月6日先锋号发射失败的记录"],tags:["人造卫星","轨道","太空竞赛"]},related:["world--1955--p04"]},
  {id:"world--1958--p01",track:"world",year:1958,yearApprox:false,dim:"politics",weight:3,title:"法国第五共和国宪法交付公投",summary:"制宪全权交由戴高乐政府，10月4日公布新宪法。",detail:{background:"1958年5月13日阿尔及尔民众占领政府总部，第四共和国面临军人干预与国家分裂的危机。",process:"5月29日总统科蒂邀请戴高乐组阁，国民议会6月3日授予六个月制宪全权并限定总统直选、议会不信任与公民投票等原则；10月4日新宪法依公投结果公布，12月21日戴高乐当选总统。",impact:"宪法以紧急权与议程控制条款强化行政主导，1962年10月总统改由直选并再度经公投确认；阿尔及利亚问题由同一程序在1961至1962年走向自决公投。",figures:["夏尔·戴高乐","勒内·科蒂","米歇尔·德勃雷"],place:"法国巴黎",state:"法国",sources:["《1958年10月4日宪法》文本与公民投票官方计票公告","法国国民议会1958年6月3日关于制宪全权法的辩论记录"],tags:["制宪","公投","半总统制"]},related:["world--1956--p04", "world--1962--p02"]},
  {id:"world--1958--s01",track:"world",year:1958,yearApprox:false,dim:"science",weight:4,title:"第一块集成电路在实验室演示",summary:"同一片锗上做出晶体管、电阻与电容。",detail:{background:"电子设备的可靠性受限于分立元件的焊接节点，军方与计算机工业提出组件化需求，美国两家公司自平面工艺切入。",process:"1958年7月24日得州仪器的基尔比在实验本记录把晶体管、电阻与电容做于同一片锗的方案，9月12日以相移振荡器样机演示，次年2月申请专利；诺伊斯在仙童公司以平面工艺提出可批量制造的同类设计。",impact:"集成电路使单位功能成本随产量下降，1960年代初军用计算机与1964年IBM 360系列相继采用集成与混合电路，制导设备小型化与1970年代微处理器皆以此工艺为基础。",figures:["杰克·基尔比","罗伯特·诺伊斯"],place:"美国达拉斯与加利福尼亚",state:"美国",sources:["Kilby, Genealogy of the Integrated Circuit（1966年12月7日诺贝尔讲演）","得州仪器1958年7月与9月实验记录及1959年微型电路专利申请文件"],tags:["半导体","微缩化","可靠性"]},related:["world--1947--s01", "world--1969--s01"]},
  {id:"world--1958--c01",track:"world",year:1958,yearApprox:false,dim:"culture",weight:2,title:"《日瓦戈医生》米兰刊出与诺奖风潮",summary:"手稿出境后在意大利出版，作者被迫谢绝诺贝尔奖。",detail:{background:"帕斯捷尔纳克自1945年起写这部以革命与个人命运为题的长篇，1956年被《新世界》杂志退稿，苏联作家协会对其展开公开批判。",process:"1957年11月意大利费尔特里内利出版社以俄文原文出版《日瓦戈医生》，1958年10月23日作者获诺贝尔文学奖；在作协压力与驱逐威胁下，他于10月27日发电报谢绝接受。",impact:"小说1965年由大卫·里恩改编为电影，1988年经《新世界》杂志在苏联全文刊出并获平反；该事件使文学奖成为冷战文化对峙中被双方公开引用的证据。",figures:["鲍里斯·帕斯捷尔纳克","贾恩贾科莫·费尔特里内利"],place:"意大利米兰与苏联佩列德尔金诺",state:"苏联／意大利",sources:["Boris Pasternak, Il dottor Zivago, Feltrinelli (Milano, 1957) 初版版权页","瑞典学院1958年诺贝尔文学奖颁奖词与帕斯捷尔纳克1958年10月27日电报"],tags:["小说","诺贝尔奖","审查"]},related:["world--1956--p01", "world--1970--f01"]},
  {id:"world--1959--p01",track:"world",year:1959,yearApprox:false,dim:"politics",weight:4,title:"卡斯特罗进入哈瓦那",summary:"元旦巴蒂斯塔出逃，1月8日起义军入城。",detail:{background:"1952年巴蒂斯塔政变后，反对派武装袭击蒙卡达兵营失败，1956年格拉玛号登陆后在马埃斯特拉山区坚持游击战；1958年12月31日圣克拉拉陷落。",process:"1959年1月1日凌晨巴蒂斯塔出逃，1月8日卡斯特罗率部进入哈瓦那，乌鲁蒂亚出任临时总统；2月16日卡斯特罗任总理，5月17日颁布以限额与补偿为内容的土地改革法。",impact:"土地改革与糖配额争端使美古关系在1960至1961年破裂，苏联自1960年起成为古巴的贸易与军售对象；美方的敌对行动与入侵威胁成为1962年危机的背景。",figures:["菲德尔·卡斯特罗","埃尔内斯托·格瓦拉","福尔亨西奥·巴蒂斯塔"],place:"古巴哈瓦那与圣克拉拉",state:"古巴",sources:["古巴临时政府1959年5月17日《土地改革法》文本","古巴革命政府1959年1月公报与哈瓦那市政交接档案"],tags:["游击战","土地改革","美古关系"]},related:["world--1962--p01"]},
  {id:"world--1959--s01",track:"world",year:1959,yearApprox:false,dim:"science",weight:3,title:"十二国签署南极条约",summary:"冻结领土要求，把该洲限定为和平与科研用途。",detail:{background:"1957至1958年国际地球物理年期间各国在南极设站并共享观测数据，领土主张重叠的七国与互不承认的美苏立场使安排难产。",process:"1959年12月1日美国、苏联、英国、法国、阿根廷、智利等十二国在华盛顿签署条约，规定南极只用于和平目的、禁止核爆炸与放射性废物处置、冻结领土主权要求并保障考察与核查自由。",impact:"条约1961年6月23日生效，其信息共享与相互视察机制成为后来外层空间与海底非军事化安排的参照；缔约国此后增至五十余国，1991年《马德里议定书》另禁止矿产资源活动。",figures:["德怀特·艾森豪威尔","埃尔沃思·班克"],place:"美国华盛顿",state:"十二缔约国",sources:["《南极条约》正文（1959年12月1日华盛顿签署，1961年6月23日生效）","国际地球物理年南极考察协调记录与各国科考站报告（1957至1958年）"],tags:["南极","非军事化","科研合作"]},related:["world--1957--s01", "world--1967--i01"]},
  {id:"world--1960--i01",track:"world",year:1960,yearApprox:false,dim:"institution",weight:5,title:"联大通过非殖民化宣言",summary:"十七个新会员入场后，殖民统治被指否定基本人权。",detail:{background:"1960年9月联大第十五届会议接纳十七个新会员国，其中十六个在非洲；亚非集团会前起草要求立即结束的决议草案。",process:"1960年12月14日大会通过第1514(XV)号决议《给予殖民地国家和人民独立宣言》，宣布殖民主义否定基本人权、与宪章相抵触，要求迅速无条件结束；表决无反对票，弃权者包括维持殖民统治的政府。",impact:"宣言把自决与领土完整配为一条，1961年设二十四国特别委员会监督执行，1963年非统组织把它列入宪章附件；1970年代纳米比亚与津巴布韦的议程皆援引它。",figures:["弗雷德里克·博兰","塞库·杜尔"],place:"美国纽约",state:"联合国",sources:["联合国大会第1514(XV)号决议《给予殖民地国家和人民独立宣言》（1960年12月14日）","联合国大会第1654(XV)号决议设立非殖民化特别委员会（1961年11月27日）"],tags:["自决","非洲年","联合国"]},related:["world--1955--p03", "world--1962--p02"]},
  {id:"world--1960--s01",track:"world",year:1960,yearApprox:false,dim:"science",weight:3,title:"第一台红宝石激光器运转",summary:"闪光灯泵浦红宝石晶体输出相干红光。",detail:{background:"1954年起微波激射器先后在氨与铷上实现，汤斯与肖洛1958年的论文把放大原理推至红外与可见光波段并提出开放光腔方案。",process:"1960年5月16日休斯研究实验室的梅曼以闪光灯泵浦红宝石晶体获得694.3纳米相干输出，7月对外公布，成果以一篇短文刊于《自然》第187卷。",impact:"激光随即用于光谱学、测距与眼科手术，1962年半导体激光器与1970年低损耗光纤使光通信成为可行路线；光盘、激光打印与光纤网络的产业形态皆源于该装置。",figures:["西奥多·梅曼","查尔斯·汤斯","阿瑟·肖洛"],place:"美国加利福尼亚马利布",state:"美国",sources:["Maiman, Stimulated Optical Radiation from Ruby, Nature 187 (1960)","Townes 与 Schawlow, Infrared and Optical Masers, Physical Review 112 (1958)"],tags:["激光","相干光","光通信"]},related:["world--1958--s01", "world--1970--s01"]},
  {id:"world--1961--p01",track:"world",year:1961,yearApprox:false,dim:"politics",weight:3,title:"猪湾登陆与维也纳首脑会谈",summary:"雇佣军三日投降，两元首脑月底在维也纳交锋。",detail:{background:"入侵计划经上一届政府批准并由中央情报局训练流亡者，1961年4月肯尼迪听取最后方案后取消对古巴机场的空中掩护。",process:"1961年4月17日至19日约一千四百名登陆者在吉隆滩（猪湾）上岸，古巴部队还击并俘获大部分人员；4月安理会就双方指控辩论，6月3日至4日肯尼迪与赫鲁晓夫在维也纳会谈，会后苏方提出德国与柏林问题新照会。",impact:"失败使华盛顿转向以颠覆与破坏行动对付古巴，并促成1962年5月古巴公开宣布走社会主义道路；维也纳会谈的强硬交锋被视为随后柏林墙与导弹危机的近因。",figures:["约翰·肯尼迪","菲德尔·卡斯特罗","尼基塔·赫鲁晓夫"],place:"古巴吉隆滩与奥地利维也纳",state:"美国／古巴／苏联",sources:["联合国安全理事会1961年4月关于古巴指控的会议记录","美国参议院外交关系委员会1961年11月关于猪湾事件的执行听证记录"],tags:["登陆","流亡者","峰会"]},related:["world--1959--p01", "world--1962--p01"]},
  {id:"world--1961--p02",track:"world",year:1961,yearApprox:false,dim:"politics",weight:5,title:"柏林墙封闭东西柏林边界",summary:"8月13日凌晨拉起铁丝网，两个德国自此有形。",detail:{background:"1949至1961年间约二百七十万人由东德经西柏林出境，苏联1958年11月照会与1961年6月维也纳的最后通牒均未改变现状。",process:"1961年8月12日深夜至13日凌晨，东德部队与工人战斗队沿分区边界拉起铁丝网并切断地铁与电话线；乌布利希6月曾公开否认筑墙，东德方面此后称其为反法西斯防卫墙。",impact:"逃亡通道被切断后东德人口外流止住，美方接受既成事实而不作军事反应；至1989年11月9日开放，据柏林墙研究机构的记录，死于墙下与射击者至少一百三十余人，各方统计出入长期存在。",figures:["瓦尔特·乌布利希","约翰·肯尼迪","尼基塔·赫鲁晓夫"],place:"柏林",state:"德意志民主共和国／德意志联邦共和国",sources:["德意志民主共和国人民议院1961年8月12日关于共和国边界保护的决议与政府公告","柏林墙研究中心与13·8工作团体关于1961至1989年死亡人数的记录"],tags:["边墙","逃亡","两个德国"]},related:["world--1948--m02", "world--1961--p01"]},
  {id:"world--1961--s01",track:"world",year:1961,yearApprox:false,dim:"science",weight:3,title:"无细胞体系译出第一个密码子",summary:"人工多聚尿苷酸指导合成苯丙氨酸多肽。",detail:{background:"双螺旋模型把遗传信息表述为可复制的序列，但基因与氨基酸顺序的对应无法直接观察；无细胞蛋白合成体系与人工合成多聚核苷酸成为可用手段。",process:"1961年尼伦伯格与马太在洛克菲勒医学研究所向除去脱氧核糖核酸的大肠杆菌抽提物加入人工合成的多聚尿苷酸，产物为仅由苯丙氨酸组成的多肽，同年7月在莫斯科第六届国际生物化学会议上报告。",impact:"该结果给出第一个密码子的对应关系，1964年科拉纳的重复序列法与1966年三核苷酸结合法完成六十四个密码的指定，分子生物学由此进入可操作序列的阶段。",figures:["马歇尔·尼伦伯格","海因里希·马太"],place:"美国纽约",state:"美国",sources:["Nirenberg 与 Matthaei 关于无细胞蛋白合成依赖核糖核酸的论文（《生物化学杂志》第237卷，1962年）","Judson, The Eighth Day of Creation (1979)"],tags:["遗传密码","无细胞体系","分子生物学"]},related:["world--1953--s01", "world--1978--s01"]},
  {id:"world--1961--x01",track:"world",year:1961,yearApprox:false,dim:"explore",weight:4,title:"第一名宇航员完成轨道飞行",summary:"东方一号108分钟绕地球一周后返回。",detail:{background:"苏联在1960年的返回式卫星上先后验证生命保障与再入回收，1961年3月25日完成一次载假人的轨道飞行。",process:"1961年4月12日尤里·加加林乘东方一号自拜科努尔发射，飞行108分钟绕地球一周，再入后在萨拉托夫附近弹射出舱以降落伞落地；5月5日美国以自由七号作15分钟亚轨道飞行回应。",impact:"载人航天成为冷战技术竞赛中最易向公众传播的指标，5月25日肯尼迪在国会提出十年内登月的目标；1961至1963年间两国共完成六人次轨道飞行，科学卫星与回收式卫星计划同时扩编。",figures:["尤里·加加林","谢尔盖·科罗廖夫"],place:"苏联拜科努尔与萨拉托夫附近",state:"苏联／美国",sources:["塔斯社1961年4月12日关于东方一号载人航行的公报","美国国家航空与航天局1961年5月5日自由七号飞行记录与1961年5月25日总统国会咨文"],tags:["载人航天","轨道","竞赛"]},related:["world--1957--s01", "world--1969--x01"]},
  {id:"world--1962--p01",track:"world",year:1962,yearApprox:false,dim:"politics",weight:5,title:"古巴导弹危机与十三日对峙",summary:"10月22日宣布海上隔离，28日苏联同意撤除导弹。",detail:{background:"猪湾事件后古巴倒向苏联，1962年7月起苏联以阿纳德尔行动向古巴运送中程与中远程弹道导弹、轰炸机与防空部队。",process:"10月14日高空侦察机摄影确认圣克里斯托尔附近的发射场，16至28日总统执行委员会在海空封锁与空袭间抉择；22日宣布隔离，27日一架侦察机在古巴上空被击落，28日赫鲁晓夫宣布拆除并运走导弹。",impact:"1963年6月开通华盛顿与莫斯科的热线，8月部分禁止核试验条约开放签署；美方以换文同意撤走部署在土耳其与意大利的导弹，双方此后把限制战略武器谈判列为常设议程。",figures:["约翰·肯尼迪","尼基塔·赫鲁晓夫","阿纳托利·多勃雷宁","罗伯特·麦克纳马拉"],place:"古巴与美国佛罗里达",state:"苏联／美国／古巴",sources:["1962年10月22日肯尼迪关于古巴海上隔离的电视演说与苏联政府1962年10月23日声明","美国国家安全档案馆公布的1962年导弹危机文件与白宫录音带文字记录"],tags:["海上隔离","核对抗","热线"]},related:["world--1961--p01", "world--1963--p01"]},
  {id:"world--1962--p02",track:"world",year:1962,yearApprox:false,dim:"politics",weight:3,title:"埃维昂停火与阿尔及利亚独立",summary:"3月停火、7月公投选择独立，欧洲裔人口大量离开。",detail:{background:"1961年埃维昂谈判两度中断，1月公民投票通过自决后，秘密军组织以暗杀与爆炸阻止独立，法国本土亦出现戒严与士兵拒命事件。",process:"1962年3月18日签署埃维昂停止射击宣言与框架协议，4月8日法国公民投票批准；7月1日阿尔及利亚公民投票赞成与法国合作实现独立，3日法国予以承认，5日定为独立日。",impact:"约百万欧洲裔居民在数周内离开阿尔及利亚，1962年秋民族解放阵线内部权力斗争决定新国家的动员体制，1965年布迈丁以兵变接管政权；撒哈拉油气与军事基地条款由协议另作过渡安排。",figures:["夏尔·戴高乐","艾哈迈德·本·贝拉"],place:"法国埃维昂与阿尔及尔",state:"法国／阿尔及利亚",sources:["《埃维昂停止射击宣言》与1962年3月18日框架协议文本","法国1962年4月8日与阿尔及利亚1962年7月1日公民投票官方计票公告"],tags:["停火","公投","独立"]},related:["world--1954--p03", "world--1960--i01"]},
  {id:"world--1962--s01",track:"world",year:1962,yearApprox:false,dim:"science",weight:3,title:"《寂静的春天》出版",summary:"把有机氯农药的食物链蓄积写成公开议题。",detail:{background:"二战后有机氯农药大量用于农业与公共卫生，1957年威斯康星与密歇根以药剂灭火蚁造成鱼类死亡并引发诉讼，1962年春报纸开始报道环保组织的反对。",process:"1962年6月起《纽约客》连载海洋生物学家蕾切尔·卡森的手稿，9月成书；书中指出有机氯沿食物链蓄积、使猛禽蛋壳变薄，并质疑以生态风险换取虫害控制的公共决策方式。",impact:"1963年总统科学咨询委员会报告确认其中部分论断并建议按毒性分类管理，各州在1970年代陆续禁用滴滴涕，1970年环境保护署成立后以该书面为主要请愿依据之一。",figures:["蕾切尔·卡森"],place:"美国纽约",state:"美国",sources:["Rachel Carson, Silent Spring (1962) 初版","美国总统科学咨询委员会关于农药使用的报告（1963年）"],tags:["农药","食物链","公众参与"]},related:["world--1956--i01", "world--1972--i01"]},
  {id:"world--1962--a01",track:"world",year:1962,yearApprox:false,dim:"art",weight:2,title:"首届弗鲁克图斯节在威斯巴登",summary:"行动、象棋与廉价印刷品在市立博物馆演八天。",detail:{background:"1961年立陶宛裔美国艺术家马修纳斯在纽约起草弗鲁克图斯纲领，把凯奇课堂与科隆电子音乐课堂的实验作品合为一股。",process:"1962年6月1日至8日首届弗鲁克图斯节在西德威斯巴登市立博物馆举行十四场演出，节目包括白南准为弦乐组准备的成套行动、希金斯的象棋作品与布雷赫的《滴水音乐》，最后一场以观众冲突收场。",impact:"弗鲁克图斯把行动、印刷品与廉价物件组成不依赖画廊与音乐厅的流通网络，1963年起以套件《弗鲁克图斯1》分发；其跨媒介做法为1960年代末行为艺术与艺术家书提供组织模板。",figures:["乔治·马修纳斯","白南准","迪克·希金斯"],place:"德国威斯巴登",state:"德意志联邦共和国／美国",sources:["马修纳斯编《弗鲁克图斯1》套件及1962年发行说明书","Hannah Higgins, Fluxus Experience (2002)"],tags:["跨媒介","行动","艺术家书"]},related:["world--1952--a01"]},
  {id:"world--1963--p01",track:"world",year:1963,yearApprox:false,dim:"politics",weight:5,title:"部分禁止核试验条约签署",summary:"美英苏在莫斯科签约，禁大气层、外层空间与水下核爆。",detail:{background:"1958年起美苏停止核试验谈判数度中断，1962年导弹危机后双方把军控列为常设议程。",process:"1963年7月15至25日美英苏代表在莫斯科拟出条约文本，8月5日三国外长签署《禁止在大气层、外层空间和水下进行核武器试验条约》，10月10日生效；条约未禁止地下核试验。",impact:"法国与中国拒绝加入并继续大气层试验；至1980年代缔约国逾百国，其以国家技术手段核查替代现场核查的做法与地下试验空白成为后来全面禁谈的争议点。",figures:["约翰·肯尼迪","亚历克·道格拉斯-霍姆","尼基塔·赫鲁晓夫"],place:"苏联莫斯科",state:"苏联／美国／英国",sources:["《禁止在大气层、外层空间和水下进行核武器试验条约》正文（1963年8月5日签署，1963年10月10日生效）","美国国务院《美国对外关系文件集》1961至1963年核裁军卷与三国批准书交存记录"],tags:["军控","核试验","冷战"]},related:["world--1962--p01", "world--1963--p02"]},
  {id:"world--1963--p02",track:"world",year:1963,yearApprox:false,dim:"politics",weight:4,title:"肯尼迪在达拉斯遇刺",summary:"11月22日车队驶过迪利广场时中弹，沃伦委员会指单独作案。",detail:{background:"肯尼迪自1960年当选后在民权、核试验禁与古巴问题上承受多方攻击，1963年11月赴得州为连任布局。",process:"1963年11月22日12时30分车队驶经达拉斯迪利广场时肯尼迪中弹，13时于帕克兰医院宣布死亡；11月24日嫌疑者奥斯瓦尔德在看守所被鲁比开枪打死；11月29日约翰逊设总统调查委员会。",impact:"沃伦委员会1964年9月24日报告认定奥斯瓦尔德单独作案、鲁比单独策划；该结论此后长期受质疑，1978年众议院暗杀案特别委员会同意有一场阴谋但无法指认范围。",figures:["约翰·肯尼迪","林登·约翰逊","李·哈维·奥斯瓦尔德","杰克·鲁比"],place:"美国得克萨斯州达拉斯",state:"美国",sources:["总统调查委员会《沃伦报告》（1964年9月24日）正文与证词卷宗","美国众议院暗杀案特别委员会最终报告（1979年）"],tags:["刺杀","总统","调查"]},related:["world--1963--p01", "world--1964--i01"]},
  {id:"world--1963--p03",track:"world",year:1963,yearApprox:false,dim:"politics",weight:3,title:"华盛顿进军与我有梦想演说",summary:"八二八二十余万人集会林肯纪念堂前，要求就业与自由。",detail:{background:"1963年肯尼迪提出民权法案但国会搁置，A. 菲利普·兰多夫与拉斯廷筹划以群众施压，工会与教会被纳入发起方。",process:"1963年8月28日「为就业与自由向华盛顿进军」在林肯纪念堂前举行，主办者与新闻机构估计到场约二十余万人；金在台阶上发表《我有一个梦想》演说，集会按预定程序于当日下午结束。",impact:"集会把民权议题推至联邦立法日程前列，1964年民权法与1965年选举权法相继通过；「我有梦想」一文的措辞成为后来各国平权游行反复援引的文本。",figures:["马丁·路德·金","贝亚德·拉斯廷"],place:"美国华盛顿林肯纪念堂",state:"美国",sources:["1963年8月29日《纽约时报》头版关于进军人数与演说的报道","《向华盛顿进军：为就业与自由》主办委员会1963年宣言与讲稿汇编"],tags:["民权","游行","演说"]},related:["world--1963--p02", "world--1964--i01"]},
  {id:"world--1963--d01",track:"world",year:1963,yearApprox:false,dim:"disaster",weight:2,title:"意大利瓦伊翁特坝涌浪",summary:"山体滑入水库，越浪摧毁隆加罗内等镇，死因归属成讼。",detail:{background:"瓦伊翁特双曲拱坝1960至1963年间出现山体位移，地质顾问早在1956至1959年即警告托克山坡体不稳，水库仍按指令蓄水。",process:"1963年10月9日22时39分约2.4亿至2.6亿立方米岩体自托克山滑入库区，涌浪越过坝顶下泄，摧毁隆加罗内与皮亚韦河谷数镇；坝体本身未溃。",impact:"意大利司法系统1968至1971年审判以过失与疏忽罪判处电力公司、政府官员等多人刑罚；死亡人数官方登记与后续统计差异较大，事件成为大型水坝风险评估的分界案例。",figures:["卡洛·塞门扎"],place:"意大利威尼托皮亚韦河谷与隆加罗内",state:"意大利",sources:["意大利贝卢诺法院1968至1971年关于瓦伊翁特事件的刑事审判记录","《纽约时报》1963年10月11至12日关于山崩、越浪与灾区的报道"],tags:["水坝","山崩","工业事故"]},related:["world--1962--s01"]},
  {id:"world--1964--p01",track:"world",year:1964,yearApprox:false,dim:"politics",weight:3,title:"赫鲁晓夫被解除一切职务",summary:"十月十四日中央全会以农业与领导方式理由撤销其职务。",detail:{background:"1962至1964年苏联农业歉收、工业改革受挫，导弹危机后的对美处理方式与干部任免争议使党内不满累积。",process:"1964年10月12日至14日苏共中央全会开会，10月14日解除赫鲁晓夫第一书记与部长会议主席职务，勃列日涅夫任第一书记、柯西金任部长会议主席；《真理报》10月15日刊载全会决议。",impact:"决议公布的理由集中于农业领导错误与「个人决定问题」，此后苏联官方停止对斯大林时期的重新清算；新领导层在1965年9月推出以利润指标为内容的柯西金改革。",figures:["尼基塔·赫鲁晓夫","列昂尼德·勃列日涅夫","阿列克谢·柯西金"],place:"苏联莫斯科",state:"苏联",sources:["《真理报》1964年10月15日关于中央全会决议与赫鲁晓夫免职的公报","苏联最高苏维埃1964年10月关于人事任命的会议记录"],tags:["权力更迭","苏共","农业"]},related:["world--1963--p01", "world--1968--p01"]},
  {id:"world--1964--i01",track:"world",year:1964,yearApprox:false,dim:"institution",weight:4,title:"美国1964年民权法生效",summary:"七月二日签署，禁公共场所种族隔离与就业歧视。",detail:{background:"1963年肯尼迪提交民权法案，参议院南方议员以冗长辩论阻挠；约翰逊以1963年11月后的立法程序与游说推进。",process:"众议院1964年2月10日通过，参议院6月19日以71票对29票终止冗长辩论并通过，7月2日约翰逊签署为《公共法律88-352》；第二章禁公共场所隔离，第七章设平等就业机会委员会。",impact:"联邦以切断资助与提起诉讼的方式推行废除隔离，1965年选举权法与1968年公平住房法沿其框架；南方各州以私人企业与选区重划作回应，相关争议进入联邦最高法院判例。",figures:["林登·约翰逊","休伯特·汉弗莱","埃弗里特·德克森"],place:"美国华盛顿",state:"美国",sources:["Civil Rights Act of 1964（Public Law 88-352）正文与立法说明","美国参议院1964年6月19日终止冗长辩论的唱名表决记录（《国会记录》）"],tags:["民权","立法","反歧视"]},related:["world--1963--p03", "world--1965--p01"]},
  {id:"world--1964--m01",track:"world",year:1964,yearApprox:false,dim:"military",weight:3,title:"法国在撒哈拉试爆首颗原子弹",summary:"二月十三日在雷加讷试爆成功，官方称当量高于广岛弹。",detail:{background:"1958年起戴高乐政府以独立核力量为大国防务支柱，1960年在撒哈拉建成雷加讷试验场并多次试爆装置。",process:"1964年2月13日协调世界时7时，法国在阿尔及利亚雷加讷附近「蓝色跳鼠」试验中以塔内起爆完成首次钚装药爆炸；法国政府当日声明爆炸成功并称当量高于投于广岛的弹。",impact:"法国此后延续独立核试验至1990年代，并于1966年退出北约军事一体化指挥体系；此次试验使部分禁止核试验条约的缺口公开化，法国到1992年才加入不扩散核武器条约。",figures:["夏尔·戴高乐","皮埃尔·玛丽·加卢瓦"],place:"阿尔及利亚撒哈拉雷加讷",state:"法国",sources:["法国政府1964年2月13日关于核爆炸的声明与《世界报》次日报道","《纽约时报》1964年2月14日关于法国首次原子弹试验的新闻报道"],tags:["核武器","法国","去殖民化"]},related:["world--1963--p01", "world--1966--p02"]},
  {id:"world--1964--p02",track:"world",year:1964,yearApprox:false,dim:"politics",weight:2,title:"坦噶尼喀与桑给巴尔合并",summary:"四月二十六日两主权实体合为联合共和国，十月改名坦桑尼亚。",detail:{background:"1963年12月桑给巴尔独立，1964年1月阿夫拉希姆领导的革命推翻苏丹统治，两国领导人自2月起谈判合并条款。",process:"1964年4月22日双方发表《达累斯萨拉姆宣言》，4月26日签署《联合条款》成立坦噶尼喀与桑给巴尔联合共和国，10月29日改名坦桑尼亚联合共和国；桑岛保留革命政府与副总统一职。",impact:"联盟以两党制与坦盟—非洲设拉子党的合并为基础，1977年改为单一党；1979年乌干达阿明政权被推翻时该联盟提供兵力，成为东非区域安全的常设变量。",figures:["朱利叶斯·尼雷尔","阿贝德·卡鲁姆"],place:"坦噶尼喀达累斯萨拉姆与桑给巴尔",state:"坦桑尼亚",sources:["《坦噶尼喀与桑给巴尔联合条款》（1964年4月26日）与1964年《临时宪法》正式文本","1964年4月22日《达累斯萨拉姆宣言》全文"],tags:["合并","非洲","联盟"]},related:["world--1960--i01", "world--1962--p02"]},
  {id:"world--1965--m01",track:"world",year:1965,yearApprox:false,dim:"military",weight:3,title:"第二次印巴战争",summary:"八月渗透行动后九月全面开战，次年一月在塔什干停火。",detail:{background:"1965年4月古吉拉特邦兰恩地区武装冲突使双方关系恶化，巴方8月起以「巴巴尔行动」向查谟与克什米尔渗透。",process:"1965年9月1日印军越过实际控制线进攻巴军据点，9月6日巴军反攻拉合尔与锡亚尔科特，13日至19日在锡亚尔科特与卡兰一带会战后双方于23日依安理会决议停火。",impact:"1966年1月10日签署《塔什干宣言》约定撤军与不干涉；战争使巴基斯坦在1971年东巴危机中军事资源受损，安理会第209至211号决议与印巴观察组成为停火监督的常例。",figures:["穆罕默德·阿尤布·汗","拉尔·巴哈杜尔·夏斯特里"],place:"印度与巴基斯坦的旁遮普与克什米尔",state:"印度／巴基斯坦",sources:["联合国安理会第209、210、211号决议（1965年9月）正文与印巴停火监督组织的报告","1966年1月10日《塔什干宣言》正式文本"],tags:["克什米尔","停火","战争"]},related:["world--1964--m01", "world--1971--p01"]},
  {id:"world--1965--p01",track:"world",year:1965,yearApprox:false,dim:"politics",weight:3,title:"洛杉矶瓦茨事件",summary:"八月十一日交通警执法引发六日冲突，州长设委员会调查。",detail:{background:"瓦茨区以黑人移民为主，就业、住房与警民冲突长期累积，1964年民权法未及解决经济不平等。",process:"1965年8月11日加州公路巡警在阿瓦隆大道拦检一名驾驶人，人群聚集并升级为冲突；州长派遣国民警卫队，至8月16日秩序恢复，洛杉矶县官方记录死亡34人。",impact:"州长顾问委员会1965年12月《瓦茨事件：起因与后果》把警民关系、就业与住房列为直接原因；此后十余年各城市类似事件频发，1968年4月金遇刺后骚乱波及一百余个城镇。",figures:["埃德蒙·布朗","约翰·麦科恩"],place:"美国加利福尼亚州洛杉矶瓦茨",state:"美国",sources:["加州州长顾问委员会《瓦茨事件：起因与后果》（1965年12月）正文与听证卷宗","洛杉矶县验尸官1965年8月死亡登记与市警总局事件报告"],tags:["骚乱","警民关系","城市"]},related:["world--1964--i01", "world--1968--f01"]},
  {id:"world--1965--p02",track:"world",year:1965,yearApprox:false,dim:"politics",weight:3,title:"新加坡脱离马来西亚",summary:"八月九日国会表决通过分离协定，李光耀公开宣布离开联邦。",detail:{background:"1963年马来西亚成立后，人民行动党与巫统在「马来西亚人的马来西亚」与族群配额问题上对立，1964至1965年新加坡两次种族骚乱。",process:"1965年8月9日马来西亚国会以无反对票通过修改宪法的分离法案，同日双方签署《新加坡独立协定》，李光耀在电视上宣布新加坡成为独立主权国家；9月21日新加坡加入联合国。",impact:"分离使新加坡失去腹地与水源协议保障，1965至1966年围绕驻军、货币与防务另订协定；马来西亚则以1971年《国家原则》与土著经济配额固化族群政治。",figures:["李光耀","东姑阿都拉曼"],place:"新加坡与马来西亚吉隆坡",state:"新加坡／马来西亚",sources:["《新加坡独立协定》（1965年8月9日签署、同日生效）正式文本","马来西亚国会1965年8月9日关于《马来西亚共和国宪法（修改）》法案的表决记录"],tags:["分离","建国","联合国"]},related:["world--1964--p02", "world--1965--p01"]},
  {id:"world--1965--c01",track:"world",year:1965,yearApprox:false,dim:"culture",weight:2,title:"第二届梵蒂冈大公会议闭会",summary:"十六份文件付表决，礼仪本地化与信仰自由条款落地。",detail:{background:"若望二十三世1962年10月11日召开大会以求「打开窗户」，保罗六世延续会期至第四会期，草案在保守与改革阵营间反复改写。",process:"1965年12月7日至8日大会最后一会期通过《信仰自由宣言》《论教会在现代世界牧职宪章》等共十六份文件，12月8日闭会；会议记录按会期公布各文件的表决数。",impact:"拉丁礼以外语言弥撒与本地主教团权限自此制度化，《论教会在现代世界》把贫穷与发展议题写进教会社会训导，1968年《人类生命》通谕与1983年新法典的争论皆以这批文本为据。",figures:["保禄六世","若望二十三世"],place:"梵蒂冈圣伯多禄大殿",state:"罗马教廷／世界各国教会",sources:["第二届梵蒂冈大公会议文献汇编十六份文件正文（1962至1965年，梵蒂冈出版社）","大公会议闭幕公告与《信仰自由宣言》表决记录（1965年12月7日至8日）"],tags:["大公会议","礼仪改革","教会法"]},related:["world--1963--p03", "world--1964--i01"]},
  {id:"world--1966--p01",track:"world",year:1966,yearApprox:false,dim:"politics",weight:4,title:"苏哈托获授权接管印尼治安",summary:"三月十一日总统命令授权其采取一切必要措施，印尼权力转移。",detail:{background:"1965年10月1日雅加达发生绑架杀害六名上将的事件后，陆军战略后备司令部苏哈托控制首都，反共清洗在爪哇与巴厘蔓延，死者数字各方统计差异较大。",process:"1966年3月11日苏加诺签署授权苏哈托「采取一切必要措施以保障安全、安定与政府威望」的三月十一日授权命令（通称 Supersemar）；次日苏哈托据以宣布印尼共产党为非法并逮捕包括外交部长苏班德里约在内的三名副总理，临时人民协商会议在1967年3月任命其代理总统。",impact:"命令文本的完整原件长期未公布，苏加诺被解除实权后于1970年6月去世；新秩序由人民协商会议制定的国家总纲领确立发展主义与反共意识形态，东帝汶与亚齐的军事处理方式亦承此体制。",figures:["苏哈托","苏加诺"],place:"印度尼西亚雅加达与茂物",state:"印度尼西亚",sources:["印度尼西亚1966年3月11日授权命令（Supersemar）文本与其后历次官方叙述版本","印度尼西亚政府《关于九·三〇事件的白色文件》（1968年）与临时人民协商会议相关决议"],tags:["权力更迭","反共","超级命令"]},related:["world--1965--p02", "world--1967--p02"]},
  {id:"world--1966--p02",track:"world",year:1966,yearApprox:false,dim:"politics",weight:3,title:"法国退出北约军事一体化机构",summary:"二月二十一日宣布，外国军队限期撤出法国本土。",detail:{background:"1958年9月戴高乐照会美英要求改组北约三人领导机制未果，此后法国坚持核力量独立与「从大西洋到乌拉尔」的欧洲构想。",process:"1966年2月21日戴高乐在记者会宣布法国将不再参与一体化军事组织，3月7日致美国总统约翰逊的照会明确撤出军事指挥体系并要求外国军队撤离法国；北约欧洲盟军最高司令部1967年迁至比利时蒙斯。",impact:"法国保留北约成员资格但长期不返军事机构，直至2009年才重新加入一体化指挥；此举同时推动法德合作与1960年代后期法国对东方的缓和接触。",figures:["夏尔·戴高乐","克里斯蒂安·富尔"],place:"法国巴黎与比利时蒙斯",state:"法国／北大西洋公约组织",sources:["戴高乐1966年2月21日记者会记录与1966年3月7日致约翰逊总统照会全文","《纽约时报》1966年2月22日关于法国退出北约军事机构的报道"],tags:["北约","自主防务","戴高乐"]},related:["world--1966--p01", "world--1964--m01"]},
  {id:"world--1966--x01",track:"world",year:1966,yearApprox:false,dim:"explore",weight:2,title:"月球九号实现月面软着陆",summary:"二月三日着陆风暴洋，传回首批月面全景照片。",detail:{background:"苏联自1958年起多次月面着陆尝试失败，后期改用气囊缓冲与弹射舱的着陆舱方案。",process:"1966年2月3日月球九号在风暴洋西侧软着陆，着陆后以伞状天线连续发回电视信号约七十余分钟，传回月面碎石与地平线的全景图像；英国约德雷尔银行望远镜截获信号并复原了其格式。",impact:"月面硬度与承载力的实测数据使后续载人着陆工程得以确定登月舱支腿与下降程序；美国1966至1967年以勘测者号回应，1969年阿波罗11号的着陆区选择沿用这批数据。",figures:["格奥尔基·巴巴金","谢尔盖·科罗廖夫"],place:"月球风暴洋与苏联拜科努尔",state:"苏联",sources:["塔斯社1966年2月3至5日关于月球九号软着陆与电视回传的公报","英国曼彻斯特大学约德雷尔银行射电望远镜1966年2月接收月面信号的观测记录（《自然》第189卷）"],tags:["月球探测","软着陆","照片回传"]},related:["world--1959--s01", "world--1969--x01"]},
  {id:"world--1966--c01",track:"world",year:1966,yearApprox:false,dim:"culture",weight:2,title:"阿多尔《否定辩证法》出版",summary:"法兰克福学派出版战后德国哲学的关键文本。",detail:{background:"阿多尔与霍克海默1940年代流亡期间写成《启蒙辩证法》，战后阿多尔恢复讲学并参与重建社会研究所。",process:"1966年苏尔坎普出版社出版阿多尔《否定辩证法》，书中以「在错误的生活里不存在正确的生活」为纲，拒绝把概念还原为封闭体系。",impact:"该书与同期《词与物》等文本共同构成1960年代末学生运动与批判理论的哲学语汇，并在1970年代后的德国大学与社会理论争论中被持续引用与反驳。",figures:["特奥多·阿多尔","马克斯·霍克海默"],place:"联邦德国法兰克福",state:"联邦德国",sources:["阿多尔《否定辩证法》初版（苏尔坎普出版社，1966年）版权页与序言","霍克海默与阿多尔《启蒙辩证法》1947年版战后重印本与两人书信"],tags:["批判理论","哲学","战后德国"]},related:["world--1947--c01", "world--1968--p02"]},
  {id:"world--1966--i01",track:"world",year:1966,yearApprox:false,dim:"institution",weight:3,title:"两个人权公约开放签署",summary:"联大通过两公约与任择议定书，把宣言条款变成条约义务。",detail:{background:"1948年《世界人权宣言》不具条约效力，1950年代起联大分两阶段起草公民政治权利与经济、社会及文化权利两份公约。",process:"1966年12月16日大会第2200A(XXI)号决议通过《公民权利和政治权利国际公约》《经济、社会及文化权利国际公约》及前者两项任择议定书，12月19日开放签署；公约在达到规定批准书数目后生效。",impact:"条约机构与个人申诉程序自此成为常设机制，1977年联合国人权委员会开始审议缔约国报告；各国批准、保留与不加入的情况差异明显，公约文本本身不规定强制执行手段。",figures:["勒内·卡桑","查尔斯·马利克"],place:"美国纽约联合国总部",state:"联合国",sources:["联合国大会第2200A(XXI)号决议与《公民权利和政治权利国际公约》《经济、社会及文化权利国际公约》正文（1966年12月16日通过）","《联合国人权条约汇编》所载两个人权公约的生效条件与批准国名单"],tags:["人权","公约","联合国"]},related:["world--1948--p05", "world--1966--c01"]},
  {id:"world--1967--m01",track:"world",year:1967,yearApprox:false,dim:"military",weight:4,title:"六日战争与三线停火",summary:"六月五日空袭埃及机场，十日后西奈、约旦河与戈兰易手。",detail:{background:"1967年5月埃及要求撤出联合国紧急部队、封锁蒂朗海峡并与约旦签共同防御条约，6月1日以色列改组内阁由达扬掌国防部。",process:"1967年6月5日以色列空军首波打击埃及机场，地面部队8日至9日经米特拉山口推进、10日抵苏伊士运河；7日至10日约旦战线作战，9日至10日夺取戈兰高地，11日前后三方先后停火。",impact:"以色列控制西奈半岛、加沙、约旦河西岸、东耶路撒冷与戈兰高地，安理会第233至237号决议要求停火并保护平民；双方公布的伤亡与被俘数字口径差异较大，难民与占领区治理成为长期议题。",figures:["列维·艾什科尔","贾迈勒·阿卜杜勒·纳赛尔","伊扎克·拉宾"],place:"西奈半岛、戈兰高地与约旦河西岸",state:"以色列／埃及／约旦／叙利亚",sources:["联合国安全理事会第233、234、235、236号决议（1967年6月）正文与停火监督报告","以色列国防军1967年6月11日公告与埃及、约旦官方同期公布的损失数字"],tags:["中东战争","空袭","停火"]},related:["world--1956--m01", "world--1967--p01"]},
  {id:"world--1967--p01",track:"world",year:1967,yearApprox:false,dim:"politics",weight:4,title:"安理会通过第二百四十二号决议",summary:"十一月二十二日不付表决通过，要求撤出占领区领土。",detail:{background:"六日战争停火后，阿拉伯方面提出多项草案，美苏在程序与措辞上磋商数月。",process:"1967年11月22日安理会于两项修正案未获通过后不付表决通过第242号决议，确认「以武力取得领土不可接受」，要求以色列军队撤出「本次冲突中占领的领土」，并终止交战状态、保障国际水道航行自由。",impact:"英文本「from territories」与法文本「sur des territoires」的措辞差异常被引为解释分歧的根源；该决议与1978年《戴维营协议》、1993年《奥斯陆协议》并列为此后历次中东和谈援引的文本基线。",figures:["吴丹","阿瑟·戈德堡"],place:"美国纽约联合国总部",state:"联合国",sources:["联合国安全理事会第242号决议正文（1967年11月22日通过）与英法两种语文本对照","《安全理事会正式记录》第22届会议关于1967年11月22日会议的记录"],tags:["联合国","占领","决议"]},related:["world--1967--m01", "world--1973--m01"]},
  {id:"world--1967--p02",track:"world",year:1967,yearApprox:false,dim:"politics",weight:3,title:"比亚夫拉宣布独立",summary:"五月三十日奥朱古在恩苏卡宣告东部脱离尼日利亚。",detail:{background:"1966年1月与7月两次兵变后，北方针对伊博人的暴力使大量东部侨民返回，1967年5月27日联邦把东部地区拆分为若干州。",process:"1967年5月30日东部军区长官奥朱古在恩苏卡宣布比亚夫拉共和国独立；联邦政府于6月关闭其海空通道并管制物资输入，7月6日起军事行动展开；国际红十字会与多国救济组织自1968年7月起以夜间空投向封锁区运粮。",impact:"1968年电视对饥饿影像的报道引发跨国救济运动，也使「人道干预」与主权界限成为公开争论；1970年1月军队投降，战后官方以「没有胜利者、没有被征服者」为口号，1967至1970年间死亡人数的各方估计差异较大。",figures:["奥杜梅格伍·奥朱古","雅库布·戈翁"],place:"尼日利亚恩苏卡与拉各斯",state:"尼日利亚／比亚夫拉",sources:["1967年5月30日《比亚夫拉独立宣言》文本与恩苏卡广播记录","尼日利亚联邦军政府1967年6月关于封锁东部海岸的公告与国际红十字会1968至1970年救济报告"],tags:["分离主义","封锁","救济"]},related:["world--1966--p01", "world--1970--m01"]},
  {id:"world--1967--i01",track:"world",year:1967,yearApprox:false,dim:"institution",weight:3,title:"外空条约开放签署并生效",summary:"禁止天体主权要求，把国家责任扩展到民间航天活动。",detail:{background:"1959年联大设立和平用途外层空间委员会，1966年12月大会通过条约草案，美苏先就一般原则达成一致再谈月球协定。",process:"1967年1月27日条约在莫斯科、伦敦、华盛顿同时开放签署，10月10日生效；条约禁止在轨道部署大规模杀伤性武器、禁止对天体提出主权要求，并规定国家对政府与民间航天活动承担国际责任与损害赔偿责任。",impact:"该条约与1959年南极条约、1967年《特拉特洛尔科条约》构成把新领域与新区域排除于主权和军备竞争之外的三件文本；1968年营救协定、1972年责任公约与1979年月球协定沿其责任条款展开，商业航天与月球资源开发在2010年代再度触发解释争论。",figures:["亚历克·道格拉斯-霍姆","吴丹"],place:"莫斯科、伦敦、华盛顿",state:"苏联／美国／英国",sources:["《关于各国探索与利用包括月球与其他天体外层空间活动所应遵守原则的条约》正文（1967年1月27日开放签署，10月10日生效）","联合国大会第2222(XXI)号决议（1966年12月核准条约草案）与三国交存批准书记录"],tags:["外层空间","非军事化","条约"]},related:["world--1959--s01", "world--1967--p01"]},
  {id:"world--1968--p01",track:"world",year:1968,yearApprox:false,dim:"politics",weight:4,title:"布拉格之春与华约军队入境",summary:"四月行动纲领后八月二十一日五国部队进入捷克斯洛伐克。",detail:{background:"1968年1月5日杜布切克出任捷共中央第一书记，4月《行动纲领》提出「带人性面孔的社会主义」并放开新闻检查，6月《两千字》宣言把公开争论推向顶点。",process:"1968年8月20日夜至21日苏联、波兰、民主德国、匈牙利与保加利亚部队进入捷克斯洛伐克并占领布拉格主要建筑，捷共领导人被带往莫斯科；8月26日公布莫斯科会谈纪要，1969年4月胡萨克接替杜布切克。",impact:"1969年至1970年间的正常化过程改组党组织与新闻界；联合国大会1968年12月第2419(XXIII)号决议呼吁撤军与恢复权利，「有限主权论」成为此后东欧异议文献反复引用的表述。",figures:["亚历山大·杜布切克","列昂尼德·勃列日涅夫","路德维克·斯沃博达"],place:"捷克斯洛伐克布拉格与苏联莫斯科",state:"捷克斯洛伐克／苏联／华沙条约组织",sources:["捷克斯洛伐克共产党1968年4月《行动纲领》文本与8月21日至26日捷共主席团历次声明","联合国大会第2419(XXIII)号决议（1968年12月）正文与《联合国大会正式记录》"],tags:["布拉格之春","华约","正常化"]},related:["world--1956--p02", "world--1968--p02"]},
  {id:"world--1968--p02",track:"world",year:1968,yearApprox:false,dim:"politics",weight:4,title:"法国五月风暴与总罢工",summary:"学生与工人连续数周对抗，格勒纳勒协议后解散议会。",detail:{background:"1968年3月楠泰尔学潮与左岸抗议遭警方驱散，4至5月索邦被封锁、学生被捕，工会与学生的示威合流。",process:"1968年5月3日起巴黎左岸冲突升级，13日起全国总罢工并出现工厂占领；5月27日政府、雇主与工会在格勒纳勒签署提高最低工资与承认企业内工会权利的协议；5月30日戴高乐发表广播讲话并解散国民议会。",impact:"6月23日与30日立法选举中执政派取得绝对多数，工会宣布的罢工人数与内政部统计口径差异较大；运动把工厂民主、教育机会平等与妇女权利议题推入1970年代法国与各欧洲国家的立法议程。",figures:["夏尔·戴高乐","乔治·塞吉","雅克·杜克洛"],place:"法国巴黎与格勒纳勒",state:"法国",sources:["1968年5月27日《格勒纳勒协议》文本与政府、工会双方公告","法国内政部1968年5至6月罢工与复工统计公报及6月23日、30日立法选举官方计票公告"],tags:["学潮","总罢工","选举"]},related:["world--1968--p01", "world--1968--p03"]},
  {id:"world--1968--p03",track:"world",year:1968,yearApprox:false,dim:"politics",weight:5,title:"不扩散核武器条约开放签署",summary:"七月一日在莫斯科、华盛顿与伦敦开放签字，无核国承诺不获取核弹。",detail:{background:"1965至1968年日内瓦十八国裁军委员会谈成条约文本，肯尼迪1963年曾警告按既有趋势十年内核国家可能超过二十个。",process:"1968年6月12日联大第2373(XXII)号决议核准条约文本，7月1日起在莫斯科、华盛顿、伦敦开放签署；条约规定无核国家不得获取核武器、核武器国不得转让，同时共享和平利用核能的权利，1970年3月5日生效。",impact:"印度与巴基斯坦未加入，朝鲜1993年起宣布退出，法国与中国于1992年加入；条约把1967年1月1日前已试爆的国家定为核武器国，原子能机构保障监督与1993年《附加议定书》范本构成此后核查争议的核心。",figures:["约翰·肯尼迪","吴丹"],place:"莫斯科、华盛顿、伦敦",state:"苏联／美国／英国",sources:["《不扩散核武器条约》正文与联合国大会第2373(XXII)号决议（1968年6月12日）","1968年7月1日莫斯科、华盛顿、伦敦三地的签署记录与各国批准书交存清单"],tags:["核不扩散","原子能机构","军控"]},related:["world--1963--p01", "world--1968--p02", "world--1970--i01"]},
  {id:"world--1968--p04",track:"world",year:1968,yearApprox:false,dim:"politics",weight:3,title:"特拉特洛尔科广场枪击",summary:"奥运会前十日，军警在广场向学生示威者开枪。",detail:{background:"1968年夏墨西哥国立自治大学等校罢课，要求释放政治犯与取消威权限制；当局把抗议与即将召开的奥运会并列为国格问题。",process:"1968年10月2日傍晚，特拉特洛尔科文化广场的集会遭军警包围并开枪，次日当局公布死伤数字；报刊随后自行刊登死者名单，与官方当日通报的数目差异较大。",impact:"事件此后数十年未在官方记录中定案，2000年代以后特别检察与档案公布使当时指挥链条部分可见；奥运会于10月12日照常开幕，事件成为研究国家暴力与记忆政治的常引案例。",figures:["古斯塔沃·迪亚斯·奥尔达斯"],place:"墨西哥城特拉特洛尔科",state:"墨西哥",sources:["墨西哥内政部1968年10月2日至5日公告与官方公布的死伤登记","墨西哥刊物1969年1月刊载的死者名单与2000年代总检察院特别调查卷宗"],tags:["学生运动","国家暴力","档案"]},related:["world--1968--p02", "world--1968--p03"]},
  {id:"world--1968--x01",track:"world",year:1968,yearApprox:false,dim:"explore",weight:3,title:"阿波罗八号完成绕月飞行",summary:"三名宇航员绕月十日，圣诞夜自月球轨道朗读经文。",detail:{background:"原计划先试运货舱，因登月舱延误而改为直接送载人飞船入月球轨道；苏联在1968年也有无人绕月飞行。",process:"1968年12月21日土星五号发射阿波罗八号，12月24日进入月球轨道共绕十圈，24日夜乘员在电视直播中朗读《创世记》并展示地球升起画面，12月27日溅落于太平洋。",impact:"任务把1961年登月目标推进到可执行阶段，也为1969年着陆验证了通信、导航与再入程序；直播画面与地出照片成为环境运动与宗教话语同时引用的图像。",figures:["弗兰克·博尔曼","詹姆斯·洛弗尔","威廉·安德斯"],place:"美国佛罗里达与月球轨道",state:"美国",sources:["美国国家航空与航天局《阿波罗八号任务报告》（1969年2月）与1968年12月21至27日飞行记录","1968年12月24日舱内电视广播的文字记录与 NASA 图像档案"],tags:["载人航天","绕月","直播"]},related:["world--1961--x01", "world--1969--x01"]},
  {id:"world--1968--f01",track:"world",year:1968,yearApprox:false,dim:"figure",weight:3,title:"马丁·路德·金在孟菲斯遇刺",summary:"四月四日在洛林汽车旅馆阳台中弹，百余城出现骚乱。",detail:{background:"金1968年初把注意力转向贫困与越战，4月赴孟菲斯声援罢工的黑人清洁工。",process:"1968年4月4日金在洛林汽车旅馆二楼阳台中枪身亡，当晚起全国百余城镇出现骚乱；4月11日约翰逊签署含公平住房条款的《1968年民权法》；1969年3月10日雷在伯明翰出庭认罪，被判九十九年监禁。",impact:"1968年2月的凯纳委员会报告已把美国描述为「两个社会、不平等且彼此分离」，金的死使该表述与公平住房法的执行成为此后政策争论的参照；1979年众议院暗杀案特别委员会重查后仍指雷为开枪者。",figures:["马丁·路德·金","詹姆斯·厄尔·雷","林登·约翰逊"],place:"美国田纳西州孟菲斯",state:"美国",sources:["孟菲斯县验尸官1968年4月4日死亡记录与阿拉巴马州北区联邦法院1969年判决","凯纳委员会《公众骚乱报告》（1968年2月29日）与美国众议院暗杀案特别委员会1979年金案报告"],tags:["民权","遇刺","骚乱"]},related:["world--1963--p03", "world--1965--p01", "world--1964--f01"]},
  {id:"world--1969--x01",track:"world",year:1969,yearApprox:false,dim:"explore",weight:5,title:"阿波罗十一号首次载人登月",summary:"七月二十日鹰号降于静海，两人在月面停留约二十一小时。",detail:{background:"1961年国会设定十年内登月目标，1968年阿波罗七号完成首次载人地球轨道试验，八号与1969年十号完成绕月与着陆演练。",process:"1969年7月16日土星五号发射，7月20日鹰号在静海西侧手动着陆，乘员在月面累计活动约二十一小时并采集岩石样本返回，7月24日溅落于太平洋；返回后乘员与样本接受隔离。",impact:"任务在十年期限内完成，此后美苏在1975年实现舱段对接并把竞争转向仪器与生物实验；各国公布的月岩年龄与成分数据成为月球演化模型的基准，工程管理模式亦被后续大科学项目反复引用。",figures:["尼尔·奥尔登·阿姆斯特朗","巴兹·奥尔德林","迈克尔·柯林斯"],place:"美国佛罗里达与月球静海",state:"美国",sources:["美国国家航空与航天局《阿波罗十一号任务报告》（NASA SP-214，1969年9月）与飞行记录","1969年7月20日休斯顿飞行管制中心的舱内通话与遥测记录"],tags:["登月","土星五号","样本"]},related:["world--1968--x01", "world--1969--s01"]},
  {id:"world--1969--s01",track:"world",year:1969,yearApprox:false,dim:"science",weight:5,title:"阿帕网完成首次主机间通信",summary:"九月首台接口机入网，十月末两端的远程登录测试中断于第三个字符。",detail:{background:"1966至1968年高级研究计划局以报文交换与接口消息处理器方案取代直接连线，1968年12月由BBN公司中标承建。",process:"1969年9月加州大学洛杉矶分校安装首台接口消息处理器，10月29日该主机与斯坦福研究所主机间进行远程登录测试，系统在传输第三个字符前中断；关于报文内容的当事人记述存在出入。",impact:"四节点网络在1969至1971年扩展到十余所大学与研究机构的接口机；1973年卡恩与瑟夫提出以传输控制协议连接异构网络，1983年1月1日全部主机切换协议，构成后来互联网的协议基线。",figures:["劳伦斯·罗伯茨","伦纳德·克莱因洛克"],place:"美国洛杉矶与门洛帕克",state:"美国",sources:["美国国防部高级研究计划局信息网络1969至1971年技术报告与接口消息处理器规格文件","加州大学洛杉矶分校与BBN公司关于1969年首次主机连接的工作记录"],tags:["报文交换","网络","计算"]},related:["world--1958--s01", "world--1971--s01"]},
  {id:"world--1969--p01",track:"world",year:1969,yearApprox:false,dim:"politics",weight:3,title:"卡扎菲发动利比亚政变",summary:"九月一日自由军官组织控制的黎波里与班加西，废王制。",detail:{background:"1967年后泛阿拉伯路线在利比亚军中失去号召力，油价分配、驻外基地与军政人事争议叠加。",process:"1969年9月1日凌晨以卡扎菲上尉为首的自由军官运动委员会占领的黎波里与班加西，宣布废黜正在土耳其的伊德里斯国王；9月7日成立革命指挥委员会并由卡扎菲任主席，同时着手终止与英国的基地安排。",impact:"1970年的石油国有化步骤与1970年代以「人民大会」为名的行政改组把军政委员会与群众组织并置；利比亚在1970至1980年代对萨赫勒与乍得的军事介入亦源于这一体制。",figures:["穆阿迈尔·卡扎菲","伊德里斯一世"],place:"利比亚的黎波里与班加西",state:"利比亚",sources:["利比亚革命指挥委员会1969年9月1日至7日公告与1970年代历次政治文书","《纽约时报》1969年9月2日至8日关于利比亚政变与新政权措施的报道"],tags:["政变","军官团体","石油"]},related:["world--1967--m01", "world--1969--x01"]},
  {id:"world--1970--i01",track:"world",year:1970,yearApprox:false,dim:"institution",weight:3,title:"不扩散核武器条约生效",summary:"三月五日达到规定批准书数目后条约生效，设审议会机制。",detail:{background:"条约1968年开放签署后，美国、苏联、英国三国与四十余国先后交存批准书。",process:"1970年3月5日条约依第九条规定的批准书数目生效，同年5月12日在日内瓦召开第一次审议会议，决定此后每五年召开审议大会；印度与法国当时以条款歧视为由拒绝加入。",impact:"生效时缔约国已逾六十个，国际原子能机构据第十一条与第三条展开保障监督；无核武器国的核查义务与核武器国的裁军承诺之间的不对称，成为历次审议会的主要争议。",figures:["吴丹"],place:"美国华盛顿与瑞士日内瓦",state:"联合国／缔约国",sources:["《不扩散核武器条约》第九条生效条款与1970年3月5日生效公告","第一次审议大会1970年5月12日最后文件与缔约国名单"],tags:["核不扩散","条约生效","审议会"]},related:["world--1968--p03"]},
  {id:"world--1970--p01",track:"world",year:1970,yearApprox:false,dim:"politics",weight:3,title:"波兰十二月抗议与开枪",summary:"十二日提价宣布后三日三市罢工，格丁尼亚港开枪。",detail:{background:"1970年12月党的四大提出以食品提价与工资调整重组分配，12月11日宣布零售食品提价。",process:"1970年12月14日起格但斯克、格丁尼亚、什切青等地工人罢工并冲击党委大楼，12月17日格丁尼亚列宁造船厂工人出厂时遭射击；12月20日中央全会撤销哥穆尔卡职务，由盖莱克接任。",impact:"官方与后来司法程序认定的死亡与受伤人数差异较大；新领导层以借款引进西方设备、1971年调整工资与补贴政策回应，1976年再次提价引发的抗议成为团结工会兴起的前因。",figures:["瓦迪斯瓦夫·哥穆尔卡","爱德华·盖莱克"],place:"波兰格但斯克、格丁尼亚与什切青",state:"波兰",sources:["波兰统一工人党1970年12月中央全会公报与政府1970年12月11日关于零售价格调整的通告","诺曼·戴维斯《波兰史》第二卷（1981年）与1970年12月波兰通讯社的现场报道"],tags:["罢工","提价","党权更迭"]},related:["world--1968--p01"]},
  {id:"world--1970--p02",track:"world",year:1970,yearApprox:false,dim:"politics",weight:3,title:"柬埔寨朗诺政变废西哈努克",summary:"三月十八日议会表决废王，十月九日成立高棉共和国。",detail:{background:"1969至1970年越共据点与美军秘密轰炸使柬埔寨政局分裂，西哈努克出国期间金边亲美军官与议会派系酝酿更替。",process:"1970年3月18日特别议会表决中止国家元首职权，3月21日朗诺任首相；10月9日废除君主立宪成立高棉共和国；西哈努克自北京宣布不承认，并于5月与红色高棉等组成柬埔寨王国民族团结政府。",impact:"内战与美方轰炸升级，1973年巴黎协定与1975年4月金边陷落相继发生；据联合国与各方统计，1970至1975年柬埔寨的死亡人数差异较大，缺乏一致口径。",figures:["朗诺","诺罗敦·西哈努克"],place:"柬埔寨金边与中国北京",state:"柬埔寨",sources:["柬埔寨全国革命委员会1970年3月18日决议与1970年10月9日高棉共和国公告","1970年5月在北京成立的柬埔寨王国民族团结政府宣言与美方1970年4月关于军事行动的公开声明"],tags:["政变","共和","内战"]},related:["world--1975--m01"]},
  {id:"world--1970--p03",track:"world",year:1970,yearApprox:false,dim:"politics",weight:3,title:"阿连德当选智利总统",summary:"九月四日得票居首而未过半，国会十月确认其当选。",detail:{background:"1964年阿连德三度参选失利后，人民联盟以土地、铜矿与住房议题结社，1970年以四党联盟名义推其为共同候选人。",process:"1970年9月4日阿连德得票居首但无人过半，按宪法由国会复选；10月24日国会确认其当选，11月3日就职，政府随即推进美资铜矿国有化与银行、企业接管。",impact:"铜矿国有化与价格管制引发资本外流与国际信贷收紧，1973年9月军人政变终止其政府；美国1970至1973年对智政策文件与国会调查记录构成此后长期争论的档案基础。",figures:["萨尔瓦多·阿连德","里卡多·拉戈斯"],place:"智利圣地亚哥与瓦尔帕莱索",state:"智利",sources:["智利官方1970年9月4日总统选举计票公告与国会1970年10月24日确认选举结果的决议","美国国务院《美国对外关系文件集》1969至1976年拉丁美洲卷与美国国家安全档案馆公布的1970年对智政策文件"],tags:["选举","国有化","铜矿"]},related:["world--1973--m02"]},
  {id:"world--1970--m01",track:"world",year:1970,yearApprox:false,dim:"military",weight:3,title:"比亚夫拉投降与内战结束",summary:"一九七〇年一月上旬奥朱古出走，剩余军民放下武器。",detail:{background:"1969年联邦军队攻占原油产区并封锁海岸，比亚夫拉控制区缩小，救济空投与粮道中断。",process:"1970年1月上旬奥朱古离开尼日利亚，随后比军政人员宣布停止抵抗，联邦政府宣布军事行动结束；战后军政府以赦免与再整合方式处理东部。",impact:"国际红十字会与各国学者对1967至1970年平民死亡人数的估计差异较大；该战与封锁成为1970年代后「人道援助与主权」争论与日内瓦四议定书谈判中的常引案例。",figures:["雅库布·戈翁","奥杜梅格伍·奥朱古"],place:"尼日利亚东部与拉各斯",state:"尼日利亚",sources:["尼日利亚联邦政府1970年1月关于战争结束的公告与《纽约时报》1970年1月的报道","国际红十字会1970年关于比亚夫拉地区营养与医疗状况的报告"],tags:["内战","投降","人道"]},related:["world--1967--p02", "world--1969--p01"]},
  {id:"world--1970--f01",track:"world",year:1970,yearApprox:false,dim:"figure",weight:2,title:"索尔仁尼琴获诺贝尔文学奖",summary:"十月八日授奖，作者因惧不得入境而未赴斯德哥尔摩。",detail:{background:"1962年《伊凡·杰尼索维奇的一天》刊于《新世界》后，作者的稿外流传作品与公开信使其与国内出版体制冲突加深。",process:"1970年10月8日瑞典学院以道德力量与俄国文学传统为由授奖给索尔仁尼琴；12月10日授奖仪式他未出席，称担心出境后不能返回；奖项后于1974年在巴黎补领。",impact:"1973年《古拉格群岛》在巴黎刊出俄文初版，1974年作者被驱逐出境；该奖与《日瓦戈医生》案一样，使诺贝尔文学奖成为冷战双方公开援引的符号。",figures:["亚历山大·索尔仁尼琴"],place:"苏联莫斯科与瑞典斯德哥尔摩",state:"苏联",sources:["瑞典学院1970年诺贝尔文学奖颁奖词与索尔仁尼琴致瑞典学院信函（1970年12月）","《古拉格群岛》第一卷（巴黎，1973年）俄文初版本版权页"],tags:["文学","流亡","冷战文化"]},related:["world--1958--c01"]},
  {id:"world--1970--s01",track:"world",year:1970,yearApprox:false,dim:"science",weight:3,title:"低损耗石英光导纤维制成",summary:"康宁实验室拉制出损耗大降的石英纤维，长距光通信成为工程问题。",detail:{background:"1966年高锟与霍克姆指出玻璃杂质吸收是光纤损耗的主因，提出把损耗降到工程可用量级的路径。",process:"1970年美国康宁公司玻璃研究实验室以掺钛石英芯与纯石英包层拉制出损耗较此前实验纤维大幅下降的光导纤维，同年提交专利申请；该结果使长距离光通信从设想转为工程问题。",impact:"激光器与光纤两项条件在1970年代合流，其后各国陆续开通商用光通信线路，1980年代低损耗单模纤维与掺铒放大器支撑起跨洋海缆；光通信的带宽成本曲线自此改变。",figures:["罗伯特·莫勒","高锟"],place:"美国纽约州沃尔德姆斯",state:"美国",sources:["美国康宁公司玻璃研究实验室1970年关于低损耗光导纤维的实验记录与同年提交的专利申请","高锟与霍克姆1966年关于介质纤维光频波导的论文（英国标准电信实验室报告）"],tags:["光纤","通信","低损耗"]},related:["world--1960--s01", "world--1971--s01"]},
  {id:"world--1971--p01",track:"world",year:1971,yearApprox:false,dim:"politics",weight:4,title:"孟加拉国独立",summary:"三月二十六日宣布独立，十二月十六日达卡守军投降。",detail:{background:"1970年12月巴基斯坦大选中，东巴的人民联盟赢得国民议会多数席位，军方与其权力移交谈判破裂。",process:"1971年3月25日夜军方发动「探照灯行动」，3月26日宣布独立并以4月17日穆吉布纳加尔成立临时政府；12月3日西部战线开战，12月16日达卡守军向印孟联军投降。",impact:"新生国家面对洪灾、粮食与工业断链，1973年后军政体制更替频繁；据巴基斯坦调查委员会、印度方面与学术研究的估计，1971年死亡人数各方统计差异较大。",figures:["谢赫·穆吉布·拉赫曼","叶海亚·汗"],place:"达卡与印度西孟加拉",state:"孟加拉国／巴基斯坦／印度",sources:["1971年12月16日达卡《投降文件》文本与交战双方公布的被俘人员数字","巴基斯坦1972年《哈穆德-ur-拉赫曼调查委员会报告》关于东巴事件的结论与联合国机构1971年的灾情通报"],tags:["独立","战争","难民"]},related:["world--1965--m01", "world--1971--p02"]},
  {id:"world--1971--s01",track:"world",year:1971,yearApprox:false,dim:"science",weight:5,title:"四比特微处理器4004问世",summary:"十一月十五日公告，两千三百只晶体管集成于一片硅上。",detail:{background:"1969年起英特尔与日本计算器厂商比吉康合作设计芯片组，霍夫与梅泽提出以通用芯片替代分立逻辑的方案。",process:"1971年11月15日4004型芯片经《电子新闻》公告上市，手册公布的晶体管数约两千三百只，算术、寄存器与指令解码单元做于一片硅上；法金与岛正利完成芯片设计与布线。",impact:"1972至1974年8008、8080相继出现，1975年1月《大众电子》封面报道一台套件式微型计算机，1977年苹果II型与1981年IBM个人计算机沿用单芯片路线。",figures:["特德·霍夫","费德里科·法金"],place:"美国加利福尼亚圣克拉拉",state:"美国",sources:["英特尔1971年11月15日《电子新闻》广告与《4004用户手册》公布的芯片规格","美国专利关于集成半导体器件的记录与1971年11月的产品公告"],tags:["微处理器","集成电路","计算器"]},related:["world--1958--s01", "world--1969--s01"]},
  {id:"world--1971--p02",track:"world",year:1971,yearApprox:false,dim:"politics",weight:4,title:"乒乓外交与基辛格密访北京",summary:"四月美国乒乓球队访华，七月十五日公告总统将访问北京。",detail:{background:"1969年中苏边界冲突后华盛顿与北京互有试探，1970年12月通过巴基斯坦与罗马尼亚渠道传递信息。",process:"1971年4月名古屋世乒赛期间美国队受邀访华，4月10至17日到北京、上海参观；7月9至11日基辛格自伊斯兰堡秘密飞赴北京与周恩来会谈，7月15日双方同时公告尼克松将于1972年5月前的适当时候访华。",impact:"公告震动东京、台北与莫斯科，1971年10月联大表决改变中国代表权，1972年2月《上海公报》把两个中国问题以「认知」措辞暂置；中美军事与经贸接触在1978年建交公报后展开。",figures:["亨利·基辛格","周恩来","理查德·尼克松"],place:"日本名古屋、北京与巴基斯坦伊斯兰堡",state:"美国／中华人民共和国／巴基斯坦",sources:["尼克松1971年7月15日关于即将访问北京的广播演说全文与中华人民共和国同日发表的公告","《美国对外关系文件集》1969至1976年中国卷与巴基斯坦方面关于1971年7月安排的往来文电"],tags:["接触","秘密外交","乒乓球"]},related:["world--1971--p01", "world--1972--p01", "cn--1971--p02"]},
  {id:"world--1971--p03",track:"world",year:1971,yearApprox:false,dim:"politics",weight:2,title:"冲绳返还协定签署",summary:"六月十七日美日签约，次年五月十五日行政权移交。",detail:{background:"1952年《旧金山和约》把冲绳置于美国施政权之下，1960年代末日本以「无核、返还、顺应国际局势」为谈判三原则。",process:"1971年6月17日大平正芳与罗杰斯在华盛顿签署《关于冲绳群岛及大东群岛的协定》，1972年5月15日生效，美国终止施政权，协定就基地使用、核武器条款与土地复垦费另作换文。",impact:"返还后美军基地集中于冲绳，1990年代起的基地搬迁与1996年「特别行动计划」延续同一争议；协定同时把钓鱼岛（日本称尖阁诸岛）的施政权一并移交，成为此后中日海上争端的直接源头。",figures:["佐藤荣作","理查德·尼克松"],place:"美国华盛顿与日本东京",state:"美国／日本",sources:["《关于冲绳群岛及大东群岛的协定》正文与1971年6月17日美日联合公报","1972年5月15日协定生效的换文与日本国会批准记录"],tags:["返还","基地","美日同盟"]},related:["world--1971--p02", "world--1972--p01"]},
  {id:"world--1971--e01",track:"world",year:1971,yearApprox:false,dim:"economy",weight:4,title:"美国停止美元兑换黄金",summary:"八月十五日暂停自由兑换，并加征进口附加税与冻结工资物价。",detail:{background:"1960年代美元危机与黄金总库的维持已现困难，越南战争开支与贸易逆差使美国黄金储备持续下降。",process:"1971年8月15日尼克松以电视讲话宣布「新经济政策」：暂停美元与黄金的自由兑换、对进口加征百分之十附加税、实行为期九十年的工资与物价冻结；同年12月18日十国集团达成《史密森学会协议》重新定值。",impact:"以美元—黄金为锚的布雷顿森林安排实际终止，1973年后主要货币转向浮动汇率；国际货币基金组织1976年《牙买加协定》承认浮动安排并推进份额与借款机制改革，1970年代的债务与通胀问题由此展开。",figures:["理查德·尼克松","约翰·康纳利"],place:"美国华盛顿戴维营",state:"美国",sources:["尼克松1971年8月15日关于就业与价格的电视讲话全文与白宫同日公告","十国集团1971年12月18日《史密森学会联合公报》与国际货币基金组织1972年年报"],tags:["布雷顿森林","汇率","物价管制"]},related:["world--1946--e01", "world--1973--e01"]},
  {id:"world--1972--i01",track:"world",year:1972,yearApprox:false,dim:"institution",weight:3,title:"联合国人类环境会议召开",summary:"六月五日斯德哥尔摩开会，通过宣言与行动计划并设环境署。",detail:{background:"1968年联大决定召开人类环境会议，1970至1971年间各国预备报告与讨论草案陆续提交。",process:"1972年6月5至16日会议在斯德哥尔摩举行，通过《联合国人类环境会议宣言》的二十六项原则与一项行动计划，设109项建议；同年12月联大决议设立环境规划署，内罗毕为所在地。",impact:"「可持续发展」之前的这一版共识把污染、发展援助与人口问题并置讨论；1992年里约会议与2012年里约加二十会议均以本次会议的机构与措辞为起点。",figures:["莫里斯·斯特朗"],place:"瑞典斯德哥尔摩",state:"联合国",sources:["《联合国人类环境会议宣言》与行动计划（1972年6月16日通过）正式文本","联合国大会第2997(XXVII)号决议设立环境规划署（1972年12月）"],tags:["环境","宣言","国际组织"]},related:["world--1962--s01", "world--1972--s01"]},
  {id:"world--1972--i02",track:"world",year:1972,yearApprox:false,dim:"institution",weight:4,title:"第一阶段限制战略武器条约签署",summary:"五月二十六日签反导条约与进攻性武器临时协定。",detail:{background:"1969年11月起两国在赫尔辛基与维也纳谈判，1971年9月先就潜射弹道导弹限制与减少意外战争风险措施达成协议，1972年5月首脑会完成剩余条款。",process:"1972年5月26日勃列日涅夫与尼克松在莫斯科签署《限制反弹道导弹系统条约》与《关于限制战略进攻武器的临时协定》，前者限定两地反导发射场，后者冻结洲际与潜射导弹数量；核查以「国家技术手段」为据而不设现场视察。",impact:"这是两国首次以条约形式限制核防御与进攻性武器，1974年《议定书》把反导场地减至一处；临时协定不含子母弹头与技术升级限制，1980年代后续的削减谈判以本约为基线。",figures:["列昂尼德·勃列日涅夫","理查德·尼克松","杰拉德·史密斯"],place:"苏联莫斯科",state:"苏联／美国",sources:["《限制反弹道导弹系统条约》与《关于限制战略进攻武器的临时协定》正文（1972年5月26日莫斯科签署）","美国参议院1972年8月关于两项条约的批准记录与听证文件"],tags:["军控","反导","缓和"]},related:["world--1968--p03", "world--1979--m01"]},
  {id:"world--1972--p01",track:"world",year:1972,yearApprox:false,dim:"politics",weight:5,title:"尼克松访华与上海公报",summary:"二月二十一日至二十八日访华，二十八日在上海发表联合公报。",detail:{background:"1971年7月基辛格密访后双方商定首脑会晤，1971年10月联大表决改变中国代表权，访华与印度支那、朝鲜半岛议题同时摆上台面。",process:"1972年2月21日尼克松抵北京与毛泽东会谈，2月28日在上海发表《联合公报》；美方「认知」而非「承认」中国关于台湾的立场，双方写入反对任何国家在亚太谋求霸权、以和平方式解决台湾问题等条款。",impact:"公报以措辞分歧的处理方式打开中美关系正常化进程，1978年12月中美建交公报与1982年8月17日公报沿其结构；日本1972年9月田中角荣访华，台湾当局与国际格局同步受冲击。",figures:["理查德·尼克松","周恩来","亨利·基辛格","毛泽东"],place:"中国北京、杭州与上海",state:"美国／中华人民共和国",sources:["《联合公报》（1972年2月28日上海发表）中英文全文与尼克松1972年2月21日至28日行程记录","《美国对外关系文件集》1969至1976年中国卷与白宫录音带文字记录"],tags:["正常化","台湾","公报"]},related:["world--1971--p02", "world--1972--i02", "cn--1972--p01"]},
  {id:"world--1972--p02",track:"world",year:1972,yearApprox:false,dim:"politics",weight:3,title:"慕尼黑奥运村人质事件",summary:"九月五日八人劫持以色列队员，机场救援失败共十七人死亡。",detail:{background:"1972年西德奥运会是战后德国首次主办夏季奥运，安保由地方警察负责并规定不得携带武器入村。",process:"1972年9月5日「黑色九月」成员潜入奥运村，当场杀死两名以色列运动员并带走九人；9月6日凌晨在菲尔斯滕费尔德布鲁克机场的救援行动中，九名人质与一名德国警察死亡，五名劫机者被击毙、三人被俘；此后西德设立边境防卫大队。",impact:"以色列随后以「上帝之怒」行动追查涉事者，1973年多起劫机与袭击事件延续同一模式；各方对安保决策链条的调查结论长期存在争议，慕尼黑模式成为此后劫机与国家回应的对照样本。",figures:["维尔纳·多尔纳"],place:"西德慕尼黑与菲尔斯滕费尔德布鲁克",state:"德意志联邦共和国／以色列",sources:["1972年9月5至6日巴伐利亚内政部与慕尼黑警方的历次公告和记者会记录","《纽约时报》1972年9月6至8日关于机场救援行动的现场报道"],tags:["劫持","奥运","安保"]},related:["world--1972--p01", "world--1973--m01"]},
  {id:"world--1972--s01",track:"world",year:1972,yearApprox:false,dim:"science",weight:3,title:"重组脱氧核糖核酸分子在体外构成",summary:"伯格实验室把猿猴病毒四〇与噬菌体脱氧核糖核酸连接。",detail:{background:"1970至1971年限制性内切酶与连接酶使脱氧核糖核酸可在体外剪切拼接，伯格据此提出跨物种拼接方案。",process:"1972年伯格等在实验室把猿猴病毒四〇的脱氧核糖核酸片段与噬菌体脱氧核糖核酸连接成重组分子；因担心含致癌病毒载体的实验风险，涉及感染性猿猴病毒四〇的后续实验被主动推迟。",impact:"1973年科恩与博耶在大肠杆菌中表达抗性重组质粒，1974至1975年关于重组脱氧核糖核酸的公开争论促成1975年阿西洛马会议的自愿准则；1976年起基因工程技术公司与1982年人胰岛素产品相继出现。",figures:["保罗·伯格","赫伯特·博耶"],place:"美国加利福尼亚拉霍亚",state:"美国",sources:["杰克逊、西蒙斯与伯格关于限制性内切酶切割猿猴病毒四〇脱氧核糖核酸的论文（《美国国家科学院院报》第68卷，1971年）","科恩与博耶等关于在大肠杆菌中构建重组质粒的论文（《美国国家科学院院报》第70卷，1973年）"],tags:["基因工程","限制酶","生物安全"]},related:["world--1961--s01", "world--1981--s01"]},
  {id:"world--1973--m01",track:"world",year:1973,yearApprox:false,dim:"military",weight:3,title:"十月战争与两条战线",summary:"十月六日埃叙两军渡河进攻，二十二日安理会决议要求停火。",detail:{background:"1967年后埃以沿运河低烈度交火，1973年9月双方军事协调完成，情报欺骗使以军未提前动员。",process:"1973年10月6日下午埃及工兵突破巴列夫防线并渡运河，叙利亚部队同日进攻戈兰高地；10月14至20日战局反转，10月22日安理会第338号决议要求停火，25日在第339号决议后停火生效。",impact:"以色列方面公布与埃叙公布的伤亡、被俘与装备损失数字差异较大；1974年1月埃以第一次脱离接触、5月埃叙脱离接触与1975年9月埃以第二次协议接管停火后的部署，1979年埃以和约把西奈归还条款写入正文。",figures:["穆罕默德·安瓦尔·萨达特","哈菲兹·阿萨德","果尔达·梅厄","亨利·基辛格"],place:"苏伊士运河东岸与戈兰高地",state:"埃及／叙利亚／以色列",sources:["联合国安全理事会第338、339、340号决议（1973年10月）正文与第二次紧急部队部署记录","埃及、叙利亚与以色列三方1973年10月各自公布的战况公告与损失数字"],tags:["中东战争","停火","脱离接触"]},related:["world--1967--p01", "world--1973--e01"]},
  {id:"world--1973--e01",track:"world",year:1973,yearApprox:false,dim:"economy",weight:5,title:"阿拉伯石油禁运与油价上涨",summary:"十月十七日减产禁运，次年一月牌价与油价成倍上抬。",detail:{background:"1973年10月十月战争爆发后，阿拉伯产油国把原油政策与政治要求挂钩，1970年《的黎波里协议》已部分提高牌价。",process:"1973年10月16日海湾五国宣布把基准价上浮百分之七十，17日阿拉伯石油输出国组织决定逐月减产并对特定国家禁运；1974年1月油价再度大幅上调，各国公布的产量与价格数据口径不一。",impact:"工业国出现燃料配给与假日限行，1974年经济合作与发展组织内设立国际能源机构并建立应急石油储备机制；石油输出国组织收入激增，1970年代后期欧洲美元循环与拉美、非洲的债务累积由此加速。",figures:["艾哈迈德·扎基·亚曼尼","亨利·基辛格"],place:"科威特与德黑兰",state:"石油输出国组织／阿拉伯石油输出国组织",sources:["石油输出国组织1973年10月16日德黑兰会议涨价公告与阿拉伯石油输出国组织1973年10月17日减产声明","经济合作与发展组织1974至1976年关于石油进口与价格的统计刊物及各国公布的产量数据"],tags:["石油","禁运","通胀"]},related:["world--1973--m01", "world--1974--e01"]},
  {id:"world--1973--i01",track:"world",year:1973,yearApprox:false,dim:"institution",weight:3,title:"水门事件参议院听证",summary:"五月十七日起电视直播听证，十月曝出十八分半空档录音。",detail:{background:"1972年6月17日水门大厦潜入者被捕后，联邦调查局与特别检察官追查筹款与掩盖线索。",process:"1973年5月17日起参议院水门特别委员会举行电视听证，考克斯任特别检察官；10月20日司法部执行免职令致司法部长与副部长先后辞职，同日公布录音带存在十八分半钟空档；10月21日众议院司法委员会启动弹劾调查。",impact:"1974年7月24日联邦最高法院一致判决要求交出录音带，众议院随后通过弹劾条款并推动尼克松辞职；听证后1974至1975年陆续通过竞选财政、自由信息与特别检察官条例等制度调整。",figures:["阿奇博尔德·考克斯","萨姆·欧文","小约翰·米切尔"],place:"美国华盛顿国会山",state:"美国",sources:["美国参议院水门特别委员会1973年听证记录与1973年11月28日最终报告","白宫1973年10月20日关于免职特别检察官的声明与联邦最高法院《美国诉尼克松案》判决（1974年7月24日）"],tags:["听证","弹劾","录音带"]},related:["world--1972--p01", "world--1974--p02"]},
  {id:"world--1973--m02",track:"world",year:1973,yearApprox:false,dim:"military",weight:3,title:"智利九月十一日政变",summary:"军队包围总统府并空袭，阿连德死于是日，军政府接管。",detail:{background:"1972至1973年智利出现物资短缺、罢工与议会对抗，1973年6月发生未遂的「坦卡索」兵变，8月众议院呼吁军队恢复秩序。",process:"1973年9月11日陆军包围总统府并空袭，皮诺切特、莱里、梅里诺与门多萨组成军政府；阿连德当日死亡，2011年智利法院开棺鉴定后公布死因为自杀；军政府随后关闭国会、取缔政党与工会并实施宵禁。",impact:"智利全国真相与和解委员会1991年报告与国家政治拘留与酷刑委员会2004年及2011年修订报告分别登记死亡失踪与被酷刑者人数，各方统计与认定口径差异较大；1980年宪法与1988年公投构成此后过渡的制度框架。",figures:["奥古斯托·皮诺切特","萨尔瓦多·阿连德"],place:"智利圣地亚哥总统府",state:"智利",sources:["智利军政府1973年9月11日至13日的历次公告与《向智利人民与全世界公告》文本","智利全国真相与和解委员会报告（1991年2月）与国家政治拘留与酷刑委员会报告（2004年、2011年修订）"],tags:["政变","军政府","真相委员会"]},related:["world--1970--p03"]},
  {id:"world--1974--p01",track:"world",year:1974,yearApprox:false,dim:"politics",weight:3,title:"葡萄牙康乃馨革命",summary:"四月二十五日武装部队运动兵变，独裁体制五日内易手。",detail:{background:"1961年起葡萄牙在安哥拉、莫桑比克与几内亚的殖民战争消耗财政，1973年斯皮诺拉被免职后下级军官不满累积。",process:"1974年4月25日夜至26日凌晨，武装部队运动以电台歌曲为信号发难，卡埃塔诺在数小时内辞职并流亡巴西，七月成立救国军委员会与临时政府，斯皮诺拉任总统；1975年11月右翼与左翼对峙后，1976年4月制宪议会选举由社会党胜出。",impact:"1974年9月承认几内亚比绍独立，1975年莫桑比克、佛得角、圣多美和普林西比与安哥拉相继独立，百万葡萄牙人自非洲返回；1976年4月宪法确立共和体制并保留革命性质的条款。",figures:["安东尼奥·德·斯皮诺拉","马里奥·苏亚雷斯"],place:"葡萄牙里斯本",state:"葡萄牙",sources:["葡萄牙武装力量运动1974年4月25日与26日的历号通告（电台广播文本）","1976年4月25日制宪议会选举官方计票公告与1976年4月2日《葡萄牙共和国宪法》文本"],tags:["兵变","去殖民化","民主化"]},related:["world--1974--p03", "world--1974--m01"]},
  {id:"world--1974--m01",track:"world",year:1974,yearApprox:false,dim:"military",weight:3,title:"塞浦路斯政变与土耳其出兵",summary:"七月十五日希腊军政府策动政变，二十日土耳其军事干预。",detail:{background:"1960年苏黎世—伦敦协定确立两族分享权力的共和国，1974年初希族国民近卫军与马卡里奥斯大主教关系恶化。",process:"1974年7月15日希腊军政府支持的武装人员占领总统府，马卡里奥斯大主教出逃，桑森任临时总统；7月20日土耳其以保障国身份在北部登陆，8月14日再度进兵，16日停火线划定，覆盖北部约三分之一土地。",impact:"1974年12月至1975年2月土族区自行宣布成立联邦实体，1983年11月15日宣布北塞浦路斯土耳其共和国独立，联合国安理会第541号决议认定其非法；各方公布的死亡、失踪与流离人数差异较大。",figures:["马卡里奥斯三世","尼科斯·桑森"],place:"塞浦路斯尼科西亚与凯里尼亚",state:"塞浦路斯／土耳其／希腊",sources:["联合国安全理事会第353号决议（1974年7月20日）与第360、361号决议（1974年8月）正文","1974年7月与8月希腊、土耳其、塞浦路斯三方各自公布的军事行动公告与伤亡数字"],tags:["政变","出兵","分裂"]},related:["world--1974--p01", "world--1983--p02", "world--1974--f01"]},
  {id:"world--1974--p02",track:"world",year:1974,yearApprox:false,dim:"politics",weight:4,title:"尼克松辞职",summary:"八月九日成为唯一辞职的总统，福特继任并于九月赦免之。",detail:{background:"1974年7月24日联邦最高法院一致判决要求交出白宫录音带，7月27日众议院司法委员会通过第一项弹劾条款。",process:"8月5日公布的1973年3月22日录音带显示白宫曾介入掩盖，8月7日至9日司法委员会陆续通过三项条款；8月8日尼克松宣布辞职，9日中午离职并在安德鲁斯基地发表离任演说，福特依第二十五修正案就职，9月8日宣布无条件赦免。",impact:"辞职后副总统任命程序与特别检察官条例、竞选财政法于1974至1975年修订；福特赦免使其在1976年预选与大选中承受持续批评，也确立了总统刑事责任的制度先例。",figures:["理查德·尼克松","杰拉尔德·福特"],place:"美国华盛顿白宫",state:"美国",sources:["尼克松1974年8月8日辞职信与8月9日离任演说全文、8月5日关于录音带的声明","众议院司法委员会1974年7月27日至8月9日弹劾条款表决记录与福特1974年9月8日赦免公告"],tags:["弹劾","辞职","赦免"]},related:["world--1973--i01", "world--1975--i01"]},
  {id:"world--1974--p03",track:"world",year:1974,yearApprox:false,dim:"politics",weight:2,title:"希腊军政府倒台",summary:"塞浦路斯兵败后三日军政府辞职，卡拉曼利斯自巴黎回国组阁。",detail:{background:"1967年4月21日军官团政变后希腊废除君主立宪，1973年11月雅典理工大学学生占领校园遭坦克冲入，1974年初内部派系斗争公开化。",process:"1974年7月20日土耳其在塞浦路斯登陆，23日军政府领导层与总统帕帕多普洛斯决裂；23日至24日帕帕多普洛斯辞去总统职务，康斯坦丁诺斯·卡拉曼利斯自巴黎回国，24日任总理并宣布实行文官政府与军队非政治化。",impact:"1974年12月公民投票决定废除君主制，1975年6月11日新宪法公布，1981年希腊加入欧洲共同体；军政府成员1975年被起诉并判刑，1990年代起相关案件的重审与赔偿持续引发争论。",figures:["康斯坦丁诺斯·卡拉曼利斯","约尔耶奥斯·帕帕多普洛斯"],place:"希腊雅典",state:"希腊",sources:["希腊1974年7月23日至24日军政府辞职与卡拉曼利斯组阁的官方公告","希腊1974年12月政体公民投票官方计票公告与1975年6月11日《希腊宪法》文本"],tags:["独裁终结","公投","宪法"]},related:["world--1974--m01", "world--1975--p01"]},
  {id:"world--1974--e01",track:"world",year:1974,yearApprox:false,dim:"economy",weight:2,title:"英国实行三日工作周",summary:"矿工罢工后政府限电，一月四日至二月九日工商业限时供电。",detail:{background:"1973年底矿工与电力工人争议使燃煤库存下降，希思政府在1972年已因劳资法在1974年初面临选举压力。",process:"1974年1月1日希思宣布三日工作周，限制工商业每周用电不超过连续三天；2月7日提前大选后悬浮议会，1974年3月矿工与雇主达成新工资协议，3月7日威尔逊组建少数派政府，限制措施随之解除。",impact:"三日工作制与两次大选促使工党把对煤炭与钢铁的国有化和《工业法》纳入议程，1975年6月英国以全民投票确认留在欧洲共同体，1970年代后期的通胀与工资协议成为1980年代劳资立法的背景。",figures:["爱德华·希思","哈罗德·威尔逊"],place:"英国伦敦",state:"英国",sources:["英国政府1974年1月关于限制工商业用电的管制令与希思同日声明","1974年2月7日与10月10日英国大选官方计票结果与中央电力局1974年供电限制记录"],tags:["罢工","能源管制","选举"]},related:["world--1973--e01", "world--1984--m01"]},
  {id:"world--1975--m01",track:"world",year:1975,yearApprox:false,dim:"military",weight:4,title:"西贡陷落与战争结束",summary:"四月三十日坦克冲入总统府，越共部队两小时后宣布接管。",detail:{background:"1973年巴黎协定后美军撤离，1975年3月北越军在中部高原发动攻势并攻占邦美蜀，中段领土数周内易手，阮文绍辞职。",process:"1975年4月26日至30日北越军总攻西贡周边，4月30日上午总统杨文明宣布无条件投降，坦克于11时进入独立宫；美国的「常风行动」在4月29至30日以航母撤离使馆人员与越南申请者，双方公布的撤离人数存在差异。",impact:"1976年4月全国选举与7月2日越南社会主义共和国成立完成南北建制合并；柬埔寨于4月17日、老挝于12月相继易帜，印度支那与东盟的安全议程同步改写，船民与再教育营问题成为此后十年的人道议题。",figures:["杨文明","文进勇","阮文绍"],place:"越南西贡与越南中部高地",state:"越南南方共和国／越南民主共和国",sources:["越南南方共和临时革命政府1975年4月30日公告与当日西贡广播记录","美国国防部1975年5月关于「常风行动」撤离人员的官方通报与国务院撤侨档案"],tags:["统一","撤侨","停战"]},related:["world--1972--p01", "world--1979--m02"]},
  {id:"world--1975--i01",track:"world",year:1975,yearApprox:false,dim:"institution",weight:3,title:"欧安会赫尔辛基最后文件",summary:"八月一日三十五国签署十项原则与人道接触条款。",detail:{background:"1969年北约提出中欧裁军与「第三篮子」合作议题，1972至1973年日内瓦预备会商定议程，1973年7月外长会在赫尔辛基开幕。",process:"1975年7月29日至8月1日第二阶段会议在赫尔辛基闭会，三十五国签署《最后文件》，写入主权平等、不使用武力、边界不可侵犯、人权与人员交流等十条原则与四个领域的合作条款；1977至1978年贝尔格莱德复审会检验执行情况。",impact:"文件不设强制机制但被东欧异议团体用作文本依据，莫斯科、基辅、捷克斯洛伐克与波兰相继成立赫尔辛基小组，《七七宪章》亦援引其中条款；1995年欧安会成为常设组织。",figures:["杰拉尔德·福特","列昂尼德·勃列日涅夫","瓦莱里·吉斯卡尔·德斯坦"],place:"芬兰赫尔辛基",state:"欧洲安全与合作会议与会国",sources:["《欧洲安全与合作会议最后文件》正文（1975年8月1日赫尔辛基通过）十项原则与合作条款","欧安会1973年7月3日至8月8日外长会记录与1977年10月至1978年5月贝尔格莱德后续会议记录"],tags:["缓和","人权条款","复审会"]},related:["world--1968--p01", "world--1977--p02"]},
  {id:"world--1975--p01",track:"world",year:1975,yearApprox:false,dim:"politics",weight:3,title:"佛朗哥去世与胡安·卡洛斯继位",summary:"十一月二十日独裁者逝世，二十二日新国王宣誓并沿用现政府。",detail:{background:"1947年《国家元首继承法》与1969年胡安·卡洛斯被指定为继承人，使王位继承制度化，佛朗哥1975年秋病重期间仍拒绝对话式改革方案。",process:"1975年11月20日佛朗哥在马德里逝世，11月22日胡安·卡洛斯一世在国会宣誓为王，阿里亚斯·纳瓦罗留任总理；1976年7月苏亚雷斯接任总理，12月15日公投通过《政治改革法》。",impact:"1977年6月15日首次民主大选、1978年12月新宪法与1981年2月未遂兵变相继发生，1982年工人社会党上台完成第一次政党轮替；佛朗哥遗体的迁葬与历史记忆法在2007与2018年引发新的争议。",figures:["胡安·卡洛斯一世","卡洛斯·阿里亚斯·纳瓦罗","阿道尔弗·苏亚雷斯"],place:"西班牙马德里",state:"西班牙",sources:["西班牙总统府1975年11月20日公告与11月22日胡安·卡洛斯一世宣誓就职记录","1976年12月15日《政治改革法》公民投票与1978年12月6日宪法公投的官方计票公告"],tags:["继承","转型","公投"]},related:["world--1974--p03", "world--1981--p01"]},
  {id:"world--1975--s01",track:"world",year:1975,yearApprox:false,dim:"science",weight:2,title:"商用可搬运计算机投放市场",summary:"九月十二日公司发布整合屏幕、键盘与驱动器的机型。",detail:{background:"1971年微处理器问世后，商用厂商尝试把小型机做进一个箱体，用户以机器语言编程的成本仍高。",process:"1975年9月12日国际商用机器公司发布5100型可编程计算机，把显示、键盘、磁带驱动与处理器集成于一个可搬运箱体，机内以只读存储方式预置两种高级语言解释器。",impact:"它使企业实验室与工程用户可直接在单一机型上编程，与1975年1月的套件机、1977年的三种个人计算机共同推动软件与外设市场分化；1981年该公司以开放架构推出个人计算机。",figures:["弗兰克·凯里"],place:"美国纽约阿蒙克与博卡拉顿",state:"美国",sources:["国际商用机器公司1975年9月关于5100型可编程计算机的产品公告与《IBM 5100操作手册》","《大众电子》1975与1977年关于可搬运微型计算机的报道与评测"],tags:["小型机","编程语言","商用"]},related:["world--1971--s01", "world--1976--e01"]},
  {id:"world--1976--m01",track:"world",year:1976,yearApprox:false,dim:"military",weight:3,title:"恩德培机场营救行动",summary:"七月四日夜以色列部队突袭乌干达机场，人质多数获释。",detail:{background:"1976年6月27日一架法航客机自雅典起飞后被劫持至恩德培机场，劫机者要求释放多地在押人员并扣押人质。",process:"1976年7月3日至4日夜，以色列运输机自内图沃起飞，突袭恩德培旧航站楼并护送人质撤离；行动中有以色列士兵阵亡，人质中有三人在行动前被射杀、一名伤者在坎帕拉医院遇害，乌干达守军伤亡数字各方公布不一。",impact:"行动使以色列把远程突击作为可复制的选项，劫机与反劫机成为1970年代末国际议程的常设条目；联合国大会在1976至1978年连续辩论国际恐怖主义问题并推动秘书长设立调查机制，1979年起相关议题进入审议程序。",figures:["伊扎克·拉宾","约纳坦·内塔尼亚胡"],place:"乌干达恩德培与以色列内图沃",state:"以色列／乌干达",sources:["1976年7月4日至5日以色列国防军与政府关于恩德培行动的公报","《纽约时报》与《卫报》1976年7月5至6日的现场报道及乌干达方面同期公布的伤亡数字"],tags:["劫机","突击","营救"]},related:["world--1972--p02", "world--1976--e01"]},
  {id:"world--1976--e01",track:"world",year:1976,yearApprox:false,dim:"economy",weight:3,title:"苹果电脑公司成立",summary:"四月初三人合伙在加州注册，同年推出主板式个人机。",detail:{background:"1975年家酿计算机俱乐部把套件机与主板设计公开化，两名硅谷工程师以自绘主板开始小批量销售。",process:"1976年4月1日乔布斯、沃兹尼亚克与韦恩在加利福尼亚以合伙形式注册苹果电脑公司，同年按订单组装首批主板式个人计算机；1977年1月3日公司改组为法人，同年4月推出整机机型。",impact:"以整机与主板销售结合零售与经销商的网络，使个人计算机在1977至1981年间从爱好者市场转向企业与家庭市场；1977年三种机型并行，1981年开放架构机型成为行业事实标准。",figures:["史蒂夫·乔布斯","史蒂夫·沃兹尼亚克"],place:"美国加利福尼亚洛斯阿尔托斯",state:"美国",sources:["1976年4月1日苹果电脑公司合伙登记文件与1977年1月3日加利福尼亚州公司注册证书","《家酿计算机俱乐部通讯》1975至1977年关于本机与主板的报道"],tags:["个人计算机","创业","主板"]},related:["world--1975--s01", "world--1979--e01"]},
  {id:"world--1977--p01",track:"world",year:1977,yearApprox:false,dim:"politics",weight:3,title:"萨达特访问耶路撒冷",summary:"十一月十九日飞抵，二十日在议会演说，阿以谈判转入直接对话。",detail:{background:"1973年后埃及转向以美国为调解方，1977年与利比亚爆发边境冲突、与苏联关系恶化，萨达特决定单方面采取外交主动。",process:"1977年11月19日萨达特率团飞抵卢德机场，11月20日在以色列议会演说，承认以色列存在并要求归还1967年占领的领土与巴勒斯坦人自决权；贝京在议会回应，以方同意设立联合委员会继续谈判，该委员会至1978年1月陷入僵局。",impact:"访问打破阿拉伯方面不直接与以色列谈判的惯例；1977年11月与1978年11月的两次巴格达首脑会议拒绝埃及路线并使阿盟总部迁至突尼斯，1978年9月戴维营两份纲要与1979年3月埃以和约由此展开。",figures:["穆罕默德·安瓦尔·萨达特","梅纳赫姆·贝京"],place:"以色列耶路撒冷",state:"埃及／以色列",sources:["萨达特1977年11月20日在以色列议会的演说全文（埃及《金字塔报》同日刊载）","以色列议会1977年11月20日会议记录与贝京同日声明"],tags:["访问","和平谈判","阿拉伯世界"]},related:["world--1973--m01", "world--1978--p01"]},
  {id:"world--1977--x01",track:"world",year:1977,yearApprox:false,dim:"explore",weight:3,title:"旅行者号探测器发射",summary:"八月与九月先后发射两架外行星探测器，借助行星连珠。",detail:{background:"1960年代末提出的「大游行」方案借一百七十六年一遇的行星几何排列一次飞越外行星，1972至1977年间经费几经削减。",process:"1977年8月20日与9月5日两枚泰坦三号E型火箭先后把旅行者二号与一号送离地球，探测器携放射性同位素电源、金唱片与相机系统，1979年3月起飞掠木星。",impact:"两架探测器在1979至1989年依次考察木星、土星、天王星与海王星，公布木卫火山、海王星大暗区与环系结构等结果；1989年后转向日球层与星际边界观测，其数据格式成为外行星研究的基准。",figures:["爱德华·斯通","卡尔·萨根"],place:"美国佛罗里达卡纳维拉尔角",state:"美国",sources:["美国国家航空与航天局1977年8月20日与9月5日发射记录与旅行者号任务说明书","1979至1989年喷气推进实验室历次飞掠期间公布的数据通报"],tags:["外行星","探测器","金唱片"]},related:["world--1975--m01", "world--1989--x01"]},
  {id:"world--1977--p02",track:"world",year:1977,yearApprox:false,dim:"politics",weight:2,title:"苏联通过一九七七年宪法",summary:"十月七日非常代表大会通过新宪法，第六条载党的领导地位。",detail:{background:"1936年宪法已行用四十年，1977年7月起按勃列日涅夫主持的委员会草案开展全民讨论，讨论记录与修改意见经《真理报》刊载。",process:"1977年10月7日苏维埃社会主义共和国联盟非常代表大会通过新宪法，序言写有「发达社会主义」，第六条规定共产党为「苏联社会的领导和指导力量」，第三十四至五十九条列举公民权利并规定相应义务。",impact:"1986至1990年间的公开化与民主化改革陆续修订其中条款，1990年3月撤销第六条；宪法中的加盟共和国自由退出条款在1990至1991年被立陶宛等共和国援引，成为解体程序的法律争点。",figures:["列昂尼德·勃列日涅夫"],place:"苏联莫斯科",state:"苏联",sources:["《苏维埃社会主义共和国联盟宪法（根本法）》正文（1977年10月7日非常苏维埃代表大会通过）","1977年6月公布的宪法草案与全苏讨论材料汇编及《真理报》相关报道"],tags:["宪法","苏共","发达社会主义"]},related:["world--1975--i01", "world--1991--p02"]},
  {id:"world--1977--p03",track:"world",year:1977,yearApprox:false,dim:"politics",weight:2,title:"西班牙首次民主大选",summary:"六月十五日选出制宪议会，过渡期政党格局经选票确认。",detail:{background:"1976年12月《政治改革法》公投通过后，各政党在一年内完成登记与结社，1977年4月大赦法释放政治犯，工人委员会亦获准活动。",process:"1977年6月15日西班牙举行议会选举，内政部公布的计票结果显示苏亚雷斯领导的民主中心联盟获众议院最多席位，工人社会党为最大反对党；7月5日苏亚雷斯续任首相，随后着手起草宪法。",impact:"1977年10月各党与政府签署《蒙克洛亚协议》，就抑制通胀、工资与税制、金融监管与教育改革达成共同纲领；1978年12月6日新宪法以公投通过并于同月29日生效，1982年工人社会党上台完成首次政党轮替。",figures:["阿道尔弗·苏亚雷斯","费利佩·冈萨雷斯"],place:"西班牙马德里与各自治区选区",state:"西班牙",sources:["西班牙内政部1977年6月16日公布的大选计票结果与《国家官方公报》同年公告","1978年12月6日宪法公民投票官方计票结果与同年12月29日宪法生效公告"],tags:["选举","过渡","制宪"]},related:["world--1975--p01", "world--1981--p01"]},
  {id:"world--1978--p01",track:"world",year:1978,yearApprox:false,dim:"politics",weight:3,title:"戴维营两份纲要签署",summary:"九月十七日签署和平纲要与埃以条约纲要，和谈进入双边阶段。",detail:{background:"1977年11月萨达特访耶路撒冷后，1978年3月华盛顿三方会谈因原则与自决条款争执停滞，7月美国以电话与书信斡旋重启接触。",process:"1978年9月5至17日萨达特与贝京在戴维营会谈，卡特以逐项书面方案推动双方让步；9月17日在华盛顿签署《实现中东和平纲要》与《签订埃以和平条约的纲要》两份文件。",impact:"1979年3月26日埃以和约按纲要签订，规定三年过渡、自治谈判与美军观察与早期预警站部署；纲要的第二部分因涉及约旦河西岸与加沙的自治谈判，此后长期未获执行。",figures:["穆罕默德·安瓦尔·萨达特","梅纳赫姆·贝京","吉米·卡特"],place:"美国马里兰戴维营与华盛顿",state:"埃及／以色列／美国",sources:["1978年9月17日华盛顿签署的《实现中东和平纲要》与《签订埃以和平条约的纲要》正文","卡特1978年9月18日关于戴维营协议的全国讲话与埃及、以色列双方同日声明"],tags:["和谈","纲要","美国斡旋"]},related:["world--1977--p01", "world--1979--p02"]},
  {id:"world--1978--p02",track:"world",year:1978,yearApprox:false,dim:"politics",weight:3,title:"巴拿马运河条约生效",summary:"十月一日新约生效，运河管辖权定于千九百九十九年底移交。",detail:{background:"1903年条约所设运河区长期由美国管辖，1964年反美暴动与1973年安理会议程使重谈成为双边议题，1974年两国发表联合声明。",process:"1977年9月7日卡特与托里霍斯在巴拿马城签署《巴拿马运河条约》与《关于运河永久中立与运营之条约》，1978年4月美国参议院达到批准所需的三分之二多数，6月16日互换批准书，10月1日新约生效并废除1903年条约。",impact:"新约把运河区行政与海关管辖权逐步移交巴拿马，并规定1999年12月31日后由巴拿马承担运营与防务、开放中立航行；1989年12月美国出兵后，两国就条约与中立方程式的解释再起争执。",figures:["吉米·卡特","奥马尔·托里霍斯"],place:"巴拿马城与美国华盛顿",state:"美国／巴拿马",sources:["《巴拿马运河条约》与《关于运河永久中立与运营之条约》正文（1977年9月7日签署，1978年10月1日生效）","美国参议院1978年4月关于两项条约的批准记录与两国1978年6月16日互换批准书的公告"],tags:["运河","条约","移交"]},related:["world--1973--i01"]},
  {id:"world--1978--s01",track:"world",year:1978,yearApprox:false,dim:"science",weight:3,title:"首例体外受精婴儿出生",summary:"七月二十五日奥尔德姆，腹腔镜取卵与胚胎移植成功分娩。",detail:{background:"1950至1960年代体外受精在家兔、牛与人类卵子相继实现，1969年人体卵子受精报告后，临床妊娠与分娩仍属未破之题。",process:"1977年11月其母以腹腔镜取出卵子并在体外受精，随后移植入子宫；1978年7月25日莱斯利·布朗在英格兰奥尔德姆综合医院以剖腹产出生，病例由斯特普托与爱德华兹报告于《柳叶刀》。",impact:"该病例确立了以排卵监测、腹腔镜取卵、体外培养与移植为流程的辅助生殖路径，1980年代各国陆续设立生殖医学中心并引发关于多胎、剩余胚胎与冷冻技术的立法争论。",figures:["帕特里克·斯特普托","罗伯特·爱德华兹"],place:"英国英格兰奥尔德姆",state:"英国",sources:["斯特普托与爱德华兹关于人类胚胎移植后分娩的病例报告（英国《柳叶刀》1978年8月5日）","1978年7月25日奥尔德姆综合医院的出生登记与同期英国媒体报道"],tags:["辅助生殖","胚胎","医学史"]},related:["world--1972--s01", "world--1963--d01"]},
  {id:"world--1979--p01",track:"world",year:1979,yearApprox:false,dim:"politics",weight:5,title:"伊朗革命与王朝终结",summary:"一月十六日巴列维离国，二月一日霍梅尼返德黑兰，四月建共和。",detail:{background:"1977年起德黑兰巴扎与宗教网络、学生与左翼组织相继上街，1978年8月阿巴丹影院火灾与9月8日德黑兰黑色星期五枪击使罢工扩大，石油工人11月加入。",process:"1979年1月16日巴列维离国，2月1日霍梅尼自巴黎返抵德黑兰，11日军方宣布中立、巴克提亚尔政府倒台；4月1日公民投票按官方公布结果建立伊斯兰共和国，12月经公民投票通过以法基赫监护为核心的宪法。",impact:"新体制以革命卫队、基金会与专家会议等机构并行于常规政府，1979至1981年与美国断交并发生人质危机；两伊战争、黎巴嫩与海湾的代理人格局以及各国的伊斯兰政治运动皆以此为分水岭。",figures:["鲁霍拉·霍梅尼","穆罕默德·礼萨·巴列维","沙普尔·巴克提亚尔"],place:"伊朗德黑兰与库姆",state:"伊朗",sources:["伊朗临时政府1979年2月11日公告与1979年4月3日关于伊斯兰共和国公民投票结果的官方宣布","霍梅尼1979年2月1日在德黑兰机场的演说记录与1979年12月《伊朗伊斯兰共和国宪法》文本"],tags:["革命","公民投票","政体更替"]},related:["world--1979--p02", "world--1978--p01"]},
  {id:"world--1979--p02",track:"world",year:1979,yearApprox:false,dim:"politics",weight:4,title:"美国驻德黑兰使馆被占",summary:"十一月四日学生占领使馆，五十二人质至次年一月获释。",detail:{background:"美国1953年参与伊朗政变、1979年10月接纳巴列维赴美治疗，使革命阵营与教士集团的动员焦点转向华盛顿。",process:"1979年11月4日学生占领美国驻德黑兰大使馆，扣押馆内人员；1979年11月至1980年先后有妇女与非美国人获释；1980年4月美军「鹰爪行动」在沙漠坠机致八人丧生，1981年1月19日《阿尔及尔声明》后52人获释，共被扣四百四十四天。",impact:"国际法院1980年5月24日判决认定伊朗违反外交关系与领事关系义务；事件促成美国与伊朗断交、1984年起伊朗被列入支持恐怖主义名单，并使卡特在1980年大选中承压，人质谈判成为此后美国与多国接触的固定议题。",figures:["吉米·卡特","鲁霍拉·霍梅尼"],place:"伊朗德黑兰与美国驻伊朗使馆",state:"美国／伊朗",sources:["联合国安全理事会第457号决议（1979年12月4日）正文与国际法院1980年5月24日关于美国驻德黑兰外交与领事人员案的判决","1981年1月19日《阿尔及尔声明》文本与美国国务院关于人质获释的公布记录"],tags:["人质","断交","国际法院"]},related:["world--1979--p01", "world--1980--p01"]},
  {id:"world--1979--m01",track:"world",year:1979,yearApprox:false,dim:"military",weight:5,title:"苏联军队进入阿富汗",summary:"十二月二十七日军方攻占总统府，卡尔迈勒在苏军支持下执政。",detail:{background:"1978年四月政变后塔拉基与阿明相继掌权，人民派与旗帜派内斗、农村反抗与逃亡使苏方多次要求稳定局势，1979年11月苏共高层决定替换阿明。",process:"1979年12月24日至27日苏联空中与地面部队进入阿富汗，27日凌晨突击卡布尔南郊的泰杰贝格宫（达乌德旧官邸），阿明被杀，卡尔迈勒同日以革命委员会主席名义公布「兄弟援助」请求与邀请入境的说明。",impact:"1980至1988年美国、巴基斯坦、沙特与多国经由渠道向圣战者提供资金与武器，联合国大会连续数年呼吁撤军；1989年2月15日撤军完成，阿富汗内战延续至1992年；苏军人员损失的俄方统计与阿方公布的平民死亡估计差异较大。",figures:["列昂尼德·勃列日涅夫","哈菲佐拉·阿明","巴布拉克·卡尔迈勒"],place:"阿富汗喀布尔与苏阿边境",state:"苏联／阿富汗",sources:["阿富汗革命委员会1979年12月27日公告与塔斯社关于苏军应请求入境的历次通报","苏联1990年3月15日塔斯社关于当年派兵决定的声明与俄罗斯官方公布的苏军人员伤亡统计"],tags:["入侵","圣战者","撤军"]},related:["world--1978--p01", "world--1989--p02"]},
  {id:"world--1979--p03",track:"world",year:1979,yearApprox:false,dim:"politics",weight:3,title:"撒切尔出任英国首相",summary:"五月三日大选后保守党获多数，工党政府因一分之差倒台。",detail:{background:"1978至1979年工资协议争议引发冬季不满与多部门罢工，1979年3月28日不信任案以一票多数通过。",process:"1979年5月3日英国大选，官方计票显示保守党取得下议院多数，玛格丽特·撒切尔于5月4日受命组阁，成为英国历史上首位女性首相；新内阁以货币供应、国有企业在售与地方税制为优先议程。",impact:"1979至1982年的高利率、1981年《英国国籍法》与1981年预算调整引发1981年多个城市骚乱与1984至1985年矿工罢工；外交上支持北约在欧部署巡航导弹与潘兴二型，1982年马岛战争与1984年矿工对峙均在此届任内。",figures:["玛格丽特·撒切尔","詹姆斯·卡拉汉"],place:"英国伦敦威斯敏斯特",state:"英国",sources:["英国1979年5月3日大选官方计票结果与白金汉宫5月4日任命公告","议会1979年3月28日对政府不信任案的表决记录（《议会辩论记录》下议院）"],tags:["大选","保守党","货币主义"]},related:["world--1974--e01", "world--1984--m01"]},
  {id:"world--1979--d01",track:"world",year:1979,yearApprox:false,dim:"disaster",weight:3,title:"三哩岛核电站事故",summary:"三月二十八日二号堆部分熔毁，控制室与阀门处置失当为主因。",detail:{background:"宾夕法尼亚州三哩岛压水堆1974至1978年先后投运，1978至1979年间该站已多次发生主泵与仪表故障。",process:"1979年3月28日凌晨二号堆主泵停转后卸压阀保持开启，堆芯部分裸露并熔化；控制室指示灯与实际阀位不一致延误处置，29至31日监测到放射性气体外排，营地与厂区人员受照剂量以官方公布数据为基线。",impact:"凯梅尼委员会1979年报告把事故归因于人机界面、培训与监管缺陷，美国新建核电订单在此后数十年停滞；国际原子能机构后来按核事件分级表把该事故列为五级，各国监管与操纵员执照制度据此改写。",figures:["亨利·凯梅尼"],place:"美国宾夕法尼亚州三哩岛",state:"美国",sources:["美国总统三里岛事故调查委员会报告《变革的必要，三哩岛的遗产》（1979年）","美国核管理委员会1979年关于辐射释放量与公众剂量的评估与国际原子能机构核事件分级表说明"],tags:["核电","熔毁","监管"]},related:["world--1954--p01", "world--1986--d01"]},
  {id:"world--1979--m02",track:"world",year:1979,yearApprox:false,dim:"military",weight:3,title:"越军进入金边与民柬政权终结",summary:"一月七日越南军队占领金边，一月八日柬埔寨人民共和国成立。",detail:{background:"1977至1978年柬越边境冲突与东部军区叛离使关系彻底破裂，1978年12月22日越南发动全面进攻。",process:"1979年1月7日越南军队与柬埔寨救国民族团结阵线进入金边，8日成立以韩桑林为主席的柬埔寨人民共和国；红色高棉退入泰国边境山区继续武装对抗，1982年7月西哈努克、宋双与乔森潘三方组成联合政府。",impact:"越南在柬驻军延续至1989年9月，联合国大会自1979年起连续多年保留民主柬的席位；各国公布的战争期间死亡人数与屠杀责任认定差异较大，相关审判至2006年后由柬埔寨法院特别法庭展开。",figures:["韩桑林","波尔布特"],place:"柬埔寨金边与豆蔻山脉边境",state:"柬埔寨／越南",sources:["1979年1月7日至8日金边方面公告与越南通讯社同期报道","联合国大会1979年11月关于柬埔寨代表权问题的表决记录与1982年7月全权证书委员会的决定"],tags:["政权更迭","驻军","代表权"]},related:["world--1975--m01", "world--1985--p01"]},
  {id:"world--1979--e01",track:"world",year:1979,yearApprox:false,dim:"economy",weight:2,title:"随身听在日本上市",summary:"七月一日立体声卡带随身听发售，便携重放成为消费品类。",detail:{background:"1963年紧凑式磁带格式确立后，重放设备长期以家用组合音响与车载为主，公司内已有供高管在长途航班使用的单声道样机。",process:"1979年7月1日TPS-L2型立体声随身听在日本上市，配双声道耳机与便携机芯；因缺少内置麦克风而在部分市场被质疑，随后各国陆续推出同类型号。",impact:"随身听与1979至1990年代卡带、光盘共同构成个人音乐消费市场，重放设备从家庭与车载延伸至通勤场景；1980年代唱片业的销售结构与随身听普及同步变化，1990年代后被闪存与网络分发取代。",figures:["盛田昭夫","井深大"],place:"日本东京",state:"日本",sources:["索尼公司1979年7月1日在日本上市的TPS-L2型随身听产品资料与当年经销目录","飞利浦1963年紧凑式磁带格式规范与日本录音带工业会1979至1985年统计"],tags:["消费电子","磁带","个人音乐"]},related:["world--1976--e01"]},
  {id:"world--1980--p01",track:"world",year:1980,yearApprox:false,dim:"politics",weight:3,title:"莫斯科奥运会遭到抵制",summary:"美国宣布不出席，多国跟进，四年后苏联阵营缺席洛杉矶奥运。",detail:{background:"1979年12月苏联进入阿富汗后，美国国会与国际奥委会内部就是否如期赴赛展开数月辩论。",process:"1980年3月卡特致函国际奥委会并提出推迟或改地，4月美国奥委会经表决放弃组队资格；至7月19日开幕前，另有多国以政府或奥委会名义宣布不出席，部分代表团以中立旗或改名方式参赛。",impact:"1984年洛杉矶奥运会期间苏联与若干国家宣布不参加，形成两届互相抵制的格局；国际奥委会此后把成员国政府干预参赛作为常设争议，1980年赛事的电视转播与奖牌榜统计在各口径下差异明显。",figures:["吉米·卡特","胡安·安东尼奥·萨马兰奇"],place:"苏联莫斯科与美国科罗拉多斯普林斯",state:"苏联／美国／国际奥委会",sources:["美国总统1980年3月关于莫斯科奥运会立场的公开声明与致国际奥委会信函","国际奥委会1980年4至7月各国家奥委会退出的通知与大会记录"],tags:["奥运","抵制","外交"]},related:["world--1979--p02", "world--1984--p01"]},
  {id:"world--1980--m01",track:"world",year:1980,yearApprox:false,dim:"military",weight:3,title:"两伊战争爆发",summary:"九月二十二日空袭与地面进攻开始，八年战事至一九八八年停火。",detail:{background:"1979年伊朗革命后两国关系恶化，1980年9月17日伊拉克宣布废除1975年《阿尔及尔协议》对阿拉伯河界线的划定。",process:"1980年9月22日伊拉克空袭伊朗多处机场并越境推进，9至11月占领霍拉姆沙赫尔等地；伊朗1981至1982年反攻并把战事推入伊拉克境内，1982年6月起出现停火斡旋，双方以油轮与城市为目标的袭击在1984年后扩大。",impact:"联合国安理会第479号决议要求停火，第598号决议在1987年7月通过后于1988年8月20日实现停火；战争双方与研究机构公布的军民死亡与损失数字差异较大，1990年8月伊拉克以战争债务与边界为由入侵科威特。",figures:["萨达姆·侯赛因","鲁霍拉·霍梅尼"],place:"阿拉伯河与胡齐斯坦省",state:"伊拉克／伊朗",sources:["联合国安全理事会第479号决议（1980年9月28日）与第598号决议（1987年7月20日）正文","伊拉克与伊朗1980年9月17至23日各自公布的废约声明与开战理由文件"],tags:["边界","消耗战","停火"]},related:["world--1979--m01", "world--1988--m01"]},
  {id:"world--1980--p02",track:"world",year:1980,yearApprox:false,dim:"politics",weight:3,title:"韩国光州事件",summary:"五月十八日起示威，空降部队进城，二十一日重新控制光州。",detail:{background:"1979年10月朴正熙遇刺后全斗焕掌握军权，1980年5月17日宣布全国戒严扩大并大学停课、国会活动停止。",process:"1980年5月18日光州全南地区大学学生示威遭镇暴部队殴打后市民加入，戒严军以空降师入城；至5月21日在道厅前发生射击与追击，27日部队重新控制道厅，此后数日各地出现搜捕与处决。",impact:"官方当年公布的死伤数字、地方治丧机构统计与1988年国会调查、1997年判决所认定的数字口径不一，至今各方统计差异较大；事件推动1987年六月民主抗争与总统直选入宪，全斗焕在1996年一审被判处死刑后于1997年获特赦。",figures:["全斗焕","金大中"],place:"韩国光州全罗南道道厅",state:"大韩民国",sources:["韩国1980年5月17日至21日戒严司令部公告与全罗南道公布的死伤登记","韩国国会1988年光州民主化运动国政调查特别委员会记录与1997年大法院相关判决"],tags:["戒严","民主化","镇压"]},related:["world--1979--p01", "world--1988--p02"]},
  {id:"world--1980--p03",track:"world",year:1980,yearApprox:false,dim:"politics",weight:3,title:"格但斯克协议与独立工会登记",summary:"八月三十一日签订协议承认自由工会，十一月获法院登记。",detail:{background:"1980年7至8月价格与补贴调整引发多地罢工，8月7日格但斯克列宁造船厂以解雇女焊工为由开始罢工。",process:"1980年8月14日起厂际罢工委员会提出二十一项要求，8月30至31日当局在什切青与格但斯克分别与罢工委员会签署协议，承认成立独立自治工会与罢工权并约定新闻条件；同年11月10日工会经法院登记取得合法地位。",impact:"会员数在1981年达到数百万，工会在1981年12月军管中被暂停活动、领导层被拘押；1988年夏季罢工与1989年圆桌协议使该工会重回合法政治进程，其模式亦影响1980年代东欧其他国家的异议组织。",figures:["莱赫·瓦文萨","安娜·瓦伦特诺维奇"],place:"波兰格但斯克与什切青",state:"波兰",sources:["1980年8月31日《格但斯克协议》与8月30日《什切青协议》文本","波兰当局1980年11月关于独立自治工会登记的法院记录与同期官方公报"],tags:["工会","罢工","协议"]},related:["world--1970--p01", "world--1981--p02"]},
  {id:"world--1981--p01",track:"world",year:1981,yearApprox:false,dim:"politics",weight:3,title:"里根就任美国总统",summary:"一月二十日就职，主张收紧福利并以减税法案为第一优先。",detail:{background:"1980年11月4日里根以选举人团多数胜出，卡特政府在通胀、失业与伊朗人质问题上承压，保守派联盟自1960年代起逐步成形。",process:"1981年1月20日里根宣誓就职，就职演说把联邦政府描述为问题的来源而非解药；同日伊朗方面完成人质释放，4月政府向国会提交减税与预算削减方案，8月以行政令推动公务员罢工者复岗。",impact:"1981年《综合预算协调法》以三年分阶段降低边际税率与扩大防务开支，1982年失业率与赤字同时上升；对外则以北约双轨决定后的在欧部署与对苏技术管制构成1980年代中期的政策底色。",figures:["罗纳德·里根","詹姆斯·贝克"],place:"美国华盛顿国会大厦",state:"美国",sources:["里根1981年1月20日就职演说全文与白宫同日公告","美国国会1981年《综合预算协调法》表决记录与经济顾问委员会同年证词"],tags:["就职","减税","保守派"]},related:["world--1974--p02", "world--1981--f01", "world--1985--p02"]},
  {id:"world--1981--f01",track:"world",year:1981,yearApprox:false,dim:"figure",weight:3,title:"里根遇刺未遂",summary:"三月三十日在希尔顿饭店外中枪，发言人布拉迪终身致残。",detail:{background:"里根就任十周后首次在国会大厦向员工讲话，当日夜间原定与工会代表午餐并赴饭店发表演说。",process:"1981年3月30日行凶者在华盛顿希尔顿饭店外连开六枪，里根中弹入胸，两名记者与一名警官、总统安保人员亦受伤；白宫新闻秘书布拉迪头部中弹后长期致残；里根当日手术，四月中旬恢复公开行程。",impact:"1982年6月联邦陪审团以精神错乱为由裁定行凶者无罪，其后被无限期收容；该判决直接推动1984年《精神错乱辩护改革法》收紧联邦标准，总统安保与特勤局通讯协议亦经国会听证修订。",figures:["罗纳德·里根","约翰·欣克利","詹姆斯·布拉迪"],place:"美国华盛顿华盛顿希尔顿饭店",state:"美国",sources:["白宫1981年3月30日关于总统伤情与手术的记者会记录","1982年6月欣克利案的联邦陪审团裁定与国会1984年《精神错乱辩护改革法》立法记录"],tags:["刺杀","安保","精神鉴定"]},related:["world--1963--p02", "world--1981--p01"]},
  {id:"world--1981--s01",track:"world",year:1981,yearApprox:false,dim:"science",weight:4,title:"首份艾滋病病例报告刊出",summary:"六月五日周报通报洛杉矶五例肺囊虫肺炎，两例已死亡。",detail:{background:"1970年代末美国与欧洲出现少见的机会性感染与卡波西肉瘤聚集，但病因与传播途径当时未明。",process:"1981年6月5日美国疾病控制中心《发病率与死亡率周报》刊出洛杉矶五例肺囊虫肺炎病例报告，其中两例死亡；同年7至9月该报继续通报同类病例与性接触者聚集，1982年9月正式使用「获得性免疫缺陷综合征」一词，1983年巴黎方面报告分离出相关逆转录病毒。",impact:"病例报告把一种新发综合征推入各国公共卫生监测，1985年起各国陆续推行献血筛查，1987年首个抗逆转录病毒药物获批；各国公布的感染者与死亡人数统计口径不同，差异较大。",figures:["迈克尔·戈特利布","詹姆斯·柯里"],place:"美国亚特兰大与洛杉矶",state:"美国",sources:["美国疾病控制中心《发病率与死亡率周报》第30卷第22期（1981年6月5日）关于五例肺囊虫肺炎的报道","戈特利布等在《新英格兰医学杂志》1981年12月31日刊出的病例系列报告"],tags:["免疫缺陷","病例报告","监测"]},related:["world--1986--s01", "world--1985--c01"]},
  {id:"world--1981--i01",track:"world",year:1981,yearApprox:false,dim:"institution",weight:3,title:"法国通过废除死刑法律",summary:"十月九日公布法律，永久废除刑事与军事法院的死刑。",detail:{background:"1970年代法国仍执行断头台，1972与1977年的处决引发全国抗议，1981年总统选举中废除死刑被列入左翼纲领。",process:"1981年8月政府提交废除死刑法案，9月国民议会与10月参议院先后表决通过，10月9日公布《关于废除死刑的第81-907号法律》，明确永久废除死刑并相应改写刑法与军事司法法典相关条款。",impact:"1981年2月与3月的最后两次执行之后法国再未处决犯人；该法与1981年赦免法、1981年司法改革一并推进，其后法国把废死写入1985与2007年议定书与2007年宪法修订条款。",figures:["弗朗索瓦·密特朗","罗贝尔·巴丹戴尔"],place:"法国巴黎",state:"法国",sources:["《关于废除死刑的第81-907号法律》（1981年10月9日）正文与《政府公报》公布件","法国国民议会1981年9月关于废除死刑案的辩论记录（《议会辩论记录》）"],tags:["废死","刑法","人权"]},related:["world--1977--p03", "world--1989--p02"]},
  {id:"world--1981--m01",track:"world",year:1981,yearApprox:false,dim:"military",weight:3,title:"以色列空袭奥西拉克反应堆",summary:"六月七日八架战斗机炸毁巴格达近郊在建反应堆，安理会谴责。",detail:{background:"1976年法国与伊拉克签订供应铀反应堆合同，1981年以色列以「不会允许邻近国家拥有核武器」为由推动动武决定。",process:"1981年6月7日下午八架战斗机以低空突防投弹摧毁图瓦勒达（奥西拉克）在建反应堆建筑与设备；国际原子能机构随后确认该堆尚未装载燃料并声明其处于保障监督之下；以色列称此举属预防性自卫。",impact:"安理会第487号决议（1981年6月19日）一致谴责该行动并重申不得攻击受保障监督的核设施；此次事件成为此后核不扩散与「先发制人」争论的常引先例，也影响了伊拉克后来的核设施分散部署。",figures:["梅纳赫姆·贝京","大卫·伊莱","萨达姆·侯赛因"],place:"伊拉克巴格达近郊奥西拉克",state:"以色列／伊拉克",sources:["联合国安全理事会第487号决议（1981年6月19日）正文与国际原子能机构1981年6月关于反应堆状况的说明","以色列政府1981年6月7日公告与伊拉克方面同日公布的损失与人员伤亡数字"],tags:["空袭","核设施","安理会"]},related:["world--1968--p03", "world--1981--i01"]},
  {id:"world--1981--p02",track:"world",year:1981,yearApprox:false,dim:"politics",weight:3,title:"波兰实施战时状态",summary:"十二月十三日宣布战时状态，工会领导层被拘押，煤矿发生开枪事件。",detail:{background:"1980年8月格但斯克协议后独立自治工会会员数以百万计，1981年经济形势与政治多元化并存，苏联多次举行华约会议施压。",process:"1981年12月12日国务委员会通过实施战时状态的法令，13日凌晨救国军事委员会宣布接管并由雅鲁泽尔斯基任总理，大批工会活动分子被拘押；12月16日卡托维兹伍耶克煤矿罢工遭射击，九名矿工死亡。",impact:"1982年12月战时状态中止、1983年7月22日解除，工会转入地下直至1988年恢复罢工；被拘押与被迫离职人数各方公布的统计不一致，差异较大；1989年圆桌协议与6月选举使同一批人重回合法政治进程。",figures:["沃伊切赫·雅鲁泽尔斯基","莱赫·瓦文萨"],place:"波兰华沙与卡托维兹",state:"波兰",sources:["波兰国务委员会1981年12月12日关于实施战时状态的法令与救国军事委员会12月13日公告","1982年12月中止与1983年7月解除战时状态的官方公告及伍耶克煤矿事件的检察记录"],tags:["军管","工会","拘押"]},related:["world--1970--p01", "world--1988--p02"]},
  {id:"world--1982--m01",track:"world",year:1982,yearApprox:false,dim:"military",weight:3,title:"马尔维纳斯群岛战争",summary:"四月二日阿军登陆，六月十四日群岛守军投降，历时七十余天。",detail:{background:"阿军1982年3月19日在南乔治亚升起国旗，英国特混舰队南下的同时联合国斡旋未果，军政府面临经济与社会压力。",process:"1982年4月2日阿军占领南乔治亚与福克兰群岛首府斯坦利；英国以核潜艇5月2日击沉阿根廷巡洋舰贝尔格拉诺号，5月4日导弹击中英舰谢菲尔德号，5月21日在圣卡洛斯湾登陆，6月14日群岛守军投降。",impact:"阿根廷方面公布的阵亡与失踪人数和英国国防部1982年6月通报的损失数字并存，其中贝尔格拉诺号一舰死者为323人；停火后经西班牙与联合国秘书长的斡旋谈判持续数轮，群岛地位与居民身份问题延续至今，英国1983年另立国籍法确认岛民身份。",figures:["利奥波多·加尔铁里","玛格丽特·撒切尔"],place:"南大西洋福克兰群岛与南乔治亚",state:"阿根廷／英国",sources:["联合国安全理事会第500、501、502号决议（1982年4月）正文与联合国秘书长1982年的斡旋记录","英国国防部1982年6月关于南大西洋行动损失的通报与阿根廷方面1982年公告及后来国防部公布的阵亡人数"],tags:["海战","登陆","停火"]},related:["world--1982--p01", "world--1974--e01"]},
  {id:"world--1982--m02",track:"world",year:1982,yearApprox:false,dim:"military",weight:3,title:"黎巴嫩战争与贝鲁特难民营事件",summary:"六月六日军事行动，九月十六至十八日萨布拉与沙提拉发生屠杀。",detail:{background:"1982年5月叙以贝卡谷地导弹与空战之后，以色列以清除边境与贝鲁特的巴解组织力量为由决定北进。",process:"1982年6月6日「加利利和平」行动进入黎巴嫩南部并围困贝鲁特，8月巴解武装在国际观察员监督下撤离；8月23日贝希尔·杰马耶勒当选总统，9月14日遇刺身亡，15至16日以军进入贝鲁特西区，16日至18日萨布拉与沙提拉两营发生针对居民的杀戮；以色列卡汉调查委员会1983年2月8日公布报告认定以方负间接责任并作出处分建议。",impact:"该委员会把营地死者数字表述为一个区间，黎巴嫩方面与新闻界公布的估计更高，各方统计差异较大；1983年多国驻贝鲁特部队营地遭汽车炸弹袭击后于1984年陆续撤离，黎巴嫩内战延续至1990年。",figures:["阿里尔·沙龙","伊扎克·卡汉"],place:"黎巴嫩贝鲁特与南部利塔尼河",state:"以色列／黎巴嫩／巴解组织",sources:["以色列调查委员会（卡汉委员会）关于贝鲁特营事件的报告（1983年2月8日）与委员会公布的死伤估计","联合国大会第37/123D号决议（1982年12月）正文与1982年9月16至18日贝鲁特方面公布的伤亡数字"],tags:["围城","屠杀","调查委员会"]},related:["world--1978--p01", "world--1983--m02"]},
  {id:"world--1982--e01",track:"world",year:1982,yearApprox:false,dim:"economy",weight:3,title:"墨西哥无力偿付外债",summary:"八月财政部分公告储备不足，拉美债务危机由此展开。",detail:{background:"1970年代石油抵押贷款与经常项目赤字使外债快速增长，1981至1982年美元利率上升与出口价格下跌同时收紧融资。",process:"1982年8月墨西哥财政与公共信贷部宣布外汇储备不足以支付到期账款并暂停部分偿付，随后比索实行多重汇率并转向国际货币基金组织与债权国寻求融资安排，另有多国同年出现偿付困难。",impact:"1982至1985年各国在多边框架下重组债务并推行结构调整，1985年后由美国财政部长以「贝克计划」等方案取代原先的短期重组思路；拉美各国的债务余额与资本外流数字在各机构统计中口径不一。",figures:["米格尔·德拉马德里","保罗·沃尔克"],place:"墨西哥城与美国华盛顿",state:"墨西哥／美国／国际货币基金组织",sources:["墨西哥财政与公共信贷部1982年8月关于停止部分外债偿付的公告与国际货币基金组织1982至1983年对墨融资安排文件","拉美与加勒比经济委员会1982至1984年对外债务统计公报"],tags:["债务危机","储备","重组"]},related:["world--1973--e01"]},
  {id:"world--1982--p01",track:"world",year:1982,yearApprox:false,dim:"politics",weight:2,title:"中美八·一七联合公报",summary:"八月十七日发表第三份联合公报，涉美对台军售条目。",detail:{background:"1981年至1982年初中美就建交后的对台军售与三个联合公报的衔接展开谈判，美国国内就军售与台湾关系法条文存在分歧。",process:"1982年8月17日双方发表联合公报，美方另发表声明表示不寻求长期对台军售、将逐步减少并最终解决这一问题，中方则重申台湾问题属中国内政、以和平方式解决为目标；同日双方各自说明立场。",impact:"该公报与1972年《上海公报》、1978年建交公报构成中美三个联合公报文本组，此后美方以《与台湾关系法》与国内程序处理对台军售，两国在1989至1996年间的多次危机中反复回到该公报的措辞上。",figures:["里根","赵紫阳"],place:"美国华盛顿与北京",state:"美国／中华人民共和国",sources:["《中华人民共和国和美利坚合众国联合公报》（1982年8月17日）全文","美国国务院1982年8月17日说明性文件与《美国对外关系文件集》1981至1988年中国卷"],tags:["公报","军售","台湾"]},related:["world--1972--p01", "world--1979--e01", "cn--1982--p02"]},
  {id:"world--1983--m01",track:"world",year:1983,yearApprox:false,dim:"military",weight:3,title:"美军进入格林纳达",summary:"十月二十五日多国部队登陆，毕晓夫政权在十日内被推翻。",detail:{background:"1979年毕晓夫上台后与赫德·奥斯汀等强硬派内斗，1983年10月毕晓夫被拘禁并处决，革命军事委员会接管，同时珍珠伞机场扩建由古巴人员承建。",process:"1983年10月21日至23日东加勒比国家组织与格林纳达总督斯昆先后请求外部干预，10月25日美军与加勒比多国部队在珍珠伞与萨尔斯河两地登陆，至11月2日主要战斗结束；1984年12月格林纳达举行大选。",impact:"美国公布的自身阵亡与古巴方面公布的死者数字并存，双方对格林纳达军民损失与处决事件责任人的统计差异较大；行动后美国与格林纳达中止外交关系至1990年代，干预主权与请求干预的合法性成为国会听证与联合国辩论的议题。",figures:["莫里斯·毕晓夫","保罗·斯昆","罗纳德·里根"],place:"格林纳达圣乔治与珍珠伞",state:"美国／格林纳达／古巴",sources:["东加勒比国家组织1983年10月致联合国秘书长的请求函与安全理事会1983年10月23至25日会议记录","美国参议院外交关系委员会1983年12月关于格林纳达行动的报告与美国国防部同期公告"],tags:["登陆","干预","加勒比"]},related:["world--1983--p01", "world--1984--p01"]},
  {id:"world--1983--m02",track:"world",year:1983,yearApprox:false,dim:"military",weight:3,title:"大韩航空零零七号被击落",summary:"九月一日波音客机在库页岛以西被截击导弹击中，二百六十九人全部遇难。",detail:{background:"该航班自安克雷奇起飞后航迹偏北，正值美军与苏军在堪察加与库页岛一带举行大规模演习，苏联防空以敌机拦截程序处置。",process:"1983年9月1日凌晨客机在库页岛以西海域被击落，机上人员全部遇难；美国与日本方面公布截听到的拦截通信，苏联最初否认，1983年9月6日承认并致歉；国际民航组织理事会随后决议并展开调查。",impact:"国际民航组织调查与理事会决议把事件定性为对民航安全的严重违反并修订飞行计划与拦截程序准则，苏联在1990年代移交部分记录并公布决策材料；双方与第三方对航线偏离成因与命令链条的解释存在长期分歧。",figures:["罗纳德·里根","尤里·安德罗波夫"],place:"库页岛以西鄂霍次克海",state:"苏联／大韩民国／美国",sources:["国际民航组织理事会1983年9月关于大韩航空007号班机的决议与1984年调查报告正文","美国与日本1983年9月1至6日公布的截听通信记录及苏联1990年代移交警告通话与决策材料"],tags:["民航","拦截","调查"]},related:["world--1979--m01", "world--1984--p01"]},
  {id:"world--1983--d01",track:"world",year:1983,yearApprox:false,dim:"disaster",weight:2,title:"埃塞俄比亚北部旱情显现",summary:"提格雷与沃洛连续降雨失败，救济机构评估首次提出粮荒警告。",detail:{background:"1976至1982年萨赫勒与东非反复干旱后，1983年雨季在埃塞俄比亚北部失败，内部流离与战事同时增加。",process:"1983年埃塞俄比亚救灾与复原委员会与联合国救灾协调机构先后就提格雷、沃洛的缺粮作出评估，国际机构随后确认牧场与粮仓同时耗竭；1984年8月起政府的定居与迁移计划把人口从受灾东部迁往西南。",impact:"1983至1985年的死亡人数因战事、迁移与救济受阻而难以统计，各国政府、联合国机构与学术研究的估计差异较大；饥荒的报道与救济动员在1984年末成为跨国舆论事件，直接促成1985年的两场大型慈善演出。",figures:["门格斯图·海尔·马里亚姆"],place:"埃塞俄比亚提格雷与沃洛",state:"埃塞俄比亚",sources:["埃塞俄比亚救灾与复原委员会1983至1984年的灾情通报与联合国救灾协调员的现场报告","联合国粮农组织与世界粮食计划署1984年关于埃塞俄比亚粮食缺口的联合评估报告"],tags:["旱灾","粮荒","救济"]},related:["world--1984--d02", "world--1985--c01"]},
  {id:"world--1983--p01",track:"world",year:1983,yearApprox:false,dim:"politics",weight:3,title:"战略防御计划提出",summary:"三月二十三日讲话主张以反导体系使核武器失效，预算与争议同步扩大。",detail:{background:"1972年反导条约把反弹道导弹限制在两处，1980年代初美国内部就「以防御取代相互确保摧毁」展开长期研究。",process:"1983年3月23日里根在关于国防预算的电视讲话中提出发展战略防御体系，要求科学界「使这些核武器变得无效与过时」；同年5月国防部设立战略防御计划组织，1984年1月该计划正式命名并公布预算。",impact:"1985至1988年国会就该计划的预算与技术可行性多次削减拨款，1986年10月雷克雅未克会谈因把防御研究与削减进攻性武器挂钩而未达成妥协；1990年代该计划改向有限战区防御，2002年美国退出反导条约并部署国家导弹防御。",figures:["罗纳德·里根","小爱德华·特勒"],place:"美国华盛顿",state:"美国",sources:["里根1983年3月23日关于战略防御的全国讲话全文与同日白宫事实说明","美国国会研究服务处与总审计局1983至1988年关于该计划预算与技术评估的报告"],tags:["反导","军备竞赛","国会"]},related:["world--1972--i02", "world--1987--p01"]},
  {id:"world--1983--p02",track:"world",year:1983,yearApprox:false,dim:"politics",weight:2,title:"北塞浦路斯宣布成立",summary:"十一月十五日土族区宣布独立，安理会以十三比一票认定非法。",detail:{background:"1974年后岛上南北分治，1975年2月土族方面成立联邦实体，1975至1983年两族会谈在总统制与领土比例问题上反复。",process:"1983年11月15日北部宣布成立北塞浦路斯土耳其共和国，登克塔什任总统，11月19日举行选举；11月18日安理会第541号决议以十三票赞成、一票反对认定该宣言在法律上无效并呼吁不承认。",impact:"1984年5月安理会第550号决议重申不承认并反对迁移选民，1990年代欧洲人权法院多次就北部财产与选举作出不利于土族当局的判决；南部1999年申请入盟与2004年安南计划的公投使分裂状态延续至今。",figures:["拉乌夫·登克塔什"],place:"塞浦路斯北部尼科西亚",state:"北塞浦路斯土耳其共和国／塞浦路斯",sources:["1983年11月15日北塞浦路斯土耳其共和国独立宣言与同期公告","联合国安全理事会第541号决议（1983年11月18日）与第550号决议（1984年5月11日）正文"],tags:["宣布独立","不承认","分治"]},related:["world--1974--m01", "world--1984--p01"]},
  {id:"world--1984--d01",track:"world",year:1984,yearApprox:false,dim:"disaster",weight:3,title:"博帕尔毒气泄漏",summary:"十二月二日夜异氰酸甲酯自工厂外泄，官方登记与后续统计差异大。",detail:{background:"联合碳化物印度公司在博帕尔的农药厂以甲基异氰酸酯为原料，1976至1984年间多次发生泄漏与设备故障，厂址紧邻居民区。",process:"1984年12月2日夜至3日该厂储存罐压力与温度失控，气体外泄扩散至市区；中央邦当局12月登记大量死亡与伤者，随后数月的失踪与迟发死亡难以归入统一口径。",impact:"1989年2月14日印度最高法院批准的和解令以金额与赔偿类别取代个案诉讼，此后关于场地清理与受害者登记的诉讼延续；1984年当年死亡人数、后续死亡与伤残登记在各机构统计中差异较大，2010年低级工程师方被定罪。",figures:["沃伦·安德森"],place:"印度中央邦博帕尔",state:"印度／美国",sources:["印度中央邦当局1984年12月的死亡与伤害登记及1989年2月14日印度最高法院批准的和解令","联合碳化物公司与印度政府1985至1994年关于释放量与场地污染的技术调查记录"],tags:["工业事故","赔偿","场地清理"]},related:["world--1979--d01", "world--1986--d01"]},
  {id:"world--1984--m01",track:"world",year:1984,yearApprox:false,dim:"military",weight:3,title:"英国矿工大罢工",summary:"三月十二日起矿区分裂，欧格里夫冲突与五月复工决定延续一年。",detail:{background:"1984年3月全国煤矿局宣布关闭二十个矿井，约两万岗位受影响，约克郡与苏格兰率先拒绝出勤，全国矿工工会未经投票发起行动。",process:"1984年3月12日起约克郡、苏格兰与南威尔士进入罢工，政府以警察与自愿复工维持生产；6月18日南约克郡欧格里夫焦化厂发生警察与纠察队冲突；1985年3月3日工会大会表决复工，共持续362天。",impact:"罢工失败后英国在1985至1994年间关闭大量深矿，1994年完成煤矿私有化；与罢工相关的死亡人数与欧格里夫事件的警员行为经1991年独立调查与2012年新验尸裁决两度改写，双方统计与责任认定差异较大。",figures:["阿瑟·斯卡吉尔","玛格丽特·撒切尔"],place:"英国约克郡、南约克郡与威尔士矿区",state:"英国",sources:["英国议会1984至1985年关于煤矿业与警察行为的辩论记录（《议会辩论记录》）与全国煤矿局1984年3月公告","《卫报》1984年6月19日关于欧格里夫冲突的现场报道与1991年欧格里夫事件独立调查报告"],tags:["罢工","矿工","警察"]},related:["world--1979--p03", "world--1974--e01"]},
  {id:"world--1984--d02",track:"world",year:1984,yearApprox:false,dim:"disaster",weight:3,title:"埃塞俄比亚饥荒经电视传播",summary:"十月二十三日英国广播公司自科克法因发回报道，各国救援随之展开。",detail:{background:"1983年北部旱情在1984年扩大，政府迁移计划与战事使外界进入受阻，救济机构多次发出呼吁。",process:"1984年10月23日英国广播公司九点新闻播出从科克法因难民营发回的报道，12月慈善单曲发行；1985年初美国政府、苏联与多国相继安排空运与粮食援助，国际机构的救济规模在当年达到峰值。",impact:"报道把饥荒救济与粮食主权、内战与人口迁移捆绑讨论，1985年7月两场跨洲演唱会募得款项经联合国机构与世界粮食计划署用于救灾；各国公布的受灾人口与死亡估计差异较大，至今无一致口径。",figures:["迈克尔·比尔克","鲍勃·格尔多夫"],place:"埃塞俄比亚科克法因与伦敦",state:"埃塞俄比亚／英国／美国",sources:["英国广播公司1984年10月23日九点新闻的科克法因报道与埃塞俄比亚救灾与复原委员会1984年11月呼吁书","联合国救灾协调专员办公室与世界粮食计划署1985年灾情通报"],tags:["饥荒","媒体","救济"]},related:["world--1983--d01", "world--1985--c01"]},
  {id:"world--1984--p01",track:"world",year:1984,yearApprox:false,dim:"politics",weight:2,title:"苏联等国缺席洛杉矶奥运",summary:"五月八日塔斯社宣布不参加，东方集团多数国家跟进。",detail:{background:"1980年美国带头抵制莫斯科奥运后，两国在奥运主办权问题上持续对峙，1984年洛杉矶组委会未能就安全保障与苏联代表团入境取得共识。",process:"1984年5月8日塔斯社发表声明称美方无法保障代表团安全，苏联正式宣布不出席，随后多个东方集团国家相继跟进；1984年7月28日开幕，参赛代表团数量少于1980年。",impact:"两国分别以1980与1984年两届形成互相抵制的先例，国际奥委会在此后主办契约中加入对成员国政府保证参赛的约束；由于缺席，1984年奖牌榜与各项目纪录的可比性成为体育统计中的长期争议。",figures:["胡安·安东尼奥·萨马兰奇"],place:"美国洛杉矶与莫斯科",state:"苏联／美国",sources:["塔斯社与苏联国家奥委会1984年5月8日声明及各国家奥委会随后退出的通知","国际奥委会1984年洛杉矶奥运会官方报告与参赛代表团统计"],tags:["奥运","抵制","安全"]},related:["world--1980--p01", "world--1988--c01"]},
  {id:"world--1985--p01",track:"world",year:1985,yearApprox:false,dim:"politics",weight:5,title:"戈尔巴乔夫当选苏共总书记",summary:"三月十一日中央全会选举戈尔巴乔夫为总书记，四月提出加速战略。",detail:{background:"1982至1985年安德罗波夫、契尔年科相继在任内去世，中央委员会内部对干部老化与经济停滞的讨论转向人事更替。",process:"1985年3月11日苏共中央全会选举戈尔巴乔夫为中央总书记；4月全会提出「加速社会经济发展战略」，同年启动反酒精运动与干部调整，1986年2月二十七大通过新的党纲与统计指标。",impact:"1986至1988年公开化与民主化改革陆续展开，1987年一月中央全会提出政治体制改革方案；1986年12月两国在华盛顿签署销毁中短程导弹条约，1988年从阿富汗撤军完成，东欧与苏联内部的民族与党务张力在此过程中同时释放。",figures:["米哈伊尔·戈尔巴乔夫","康斯坦丁·契尔年科"],place:"苏联莫斯科",state:"苏联",sources:["苏联《真理报》1985年3月11日关于中央全会选举戈尔巴乔夫为总书记的公报","1985年4月中央全会关于加速社会经济发展战略的决议与1986年2月苏共二十七大文件"],tags:["人事更替","改革","苏共"]},related:["world--1979--m01", "world--1987--p01"]},
  {id:"world--1985--c01",track:"world",year:1985,yearApprox:false,dim:"culture",weight:2,title:"生存援助演唱会两地同办",summary:"七月十三日伦敦与费城同时开唱，款项转交救济机构用于救灾。",detail:{background:"1984年10月埃塞俄比亚饥荒经英国广播公司报道后，音乐人于12月发行慈善单曲，随后筹办更大规模的现场演出。",process:"1985年7月13日「生存援助」演唱会在伦敦温布利球场与费城肯尼迪体育场同时举行，经卫星向多国转播，数十组艺人参演；主办者把款项交由救济与联合国机构用于埃塞俄比亚救灾。",impact:"该演出把跨国慈善与媒体动员结合成可复制的模式，1986年起多国音乐人仿其形式募捐；捐款在救济与长期发展之间的分配比例此后受到审计与媒体审查，各国公布的总额与去向数字口径不一。",figures:["鲍勃·格尔多夫","哈里·贝拉方特"],place:"英国伦敦与美国费城",state:"英国／美国",sources:["1985年7月13日生存援助演唱会主办方的现场记录与各国转播统计","接收捐款的救济机构与联合国机构1985至1986年公布的使用报告"],tags:["慈善","转播","音乐"]},related:["world--1984--d02", "world--1985--d01"]},
  {id:"world--1985--m01",track:"world",year:1985,yearApprox:false,dim:"military",weight:3,title:"彩虹勇士号在新西兰被炸",summary:"七月十日奥克兰港内爆炸起火，船上一人死亡，两名法国军人被拘。",detail:{background:"绿色和平组织的彩虹勇士号计划前往法属波利尼西亚穆鲁罗瓦环礁抗议大气层核试验，1985年7月停泊于奥克兰港补给。",process:"1985年7月10日凌晨两枚磁性水雷在船体水下部分引爆，船只在港内沉没，摄影师佩雷拉死亡；新西兰警方随即拘捕两名持伪造护照入境的法国军人，1986至1987年两国在联合国秘书长调解下达成拘禁与赔偿安排。",impact:"1986年法国政府公开承认行动系情报部门所实施并作出赔偿，新西兰法院以过失杀人等罪名判处两名军人监禁；该事件使南太平洋无核化运动获得国际声援，法国于1996年终止大气层核试验。",figures:["费尔南多·佩雷拉"],place:"新西兰奥克兰港与法属波利尼西亚穆鲁罗瓦",state:"法国／新西兰",sources:["新西兰警方与法院1985至1987年关于彩虹勇士号爆炸案的调查与审判记录","法国政府1986年关于责任归属的公开声明与联合国秘书长1986年调解下两国达成的协议文本"],tags:["水雷","核试验","赔偿"]},related:["world--1964--m01", "world--1986--p01"]},
  {id:"world--1985--d01",track:"world",year:1985,yearApprox:false,dim:"disaster",weight:3,title:"墨西哥城大地震",summary:"九月十九日八级地震袭击首都，数百栋建筑倒塌，救济动员展开。",detail:{background:"墨西哥城建于古湖床之上，软土放大使远距离地震波在市中心被放大，1957年曾发生类似震害。",process:"1985年9月19日墨西哥米却肯州沿岸近海发生矩震级约八点的地震，首都与周边州大量建筑倒塌，罗马区、埃斯坎东区与华雷斯区受损最重；震后民间自发组织挖掘与救济，政府随后接受国际搜救队。",impact:"官方登记的死亡数与泛美卫生组织及民间机构的估计差异较大，倒塌建筑与无家可归者人数亦因统计时点不同而异；事件促成1987年新的建筑抗震规范与1980年代末城市治理与民间组织的重组。",figures:["米格尔·德拉马德里"],place:"墨西哥墨西哥城与米却肯沿岸",state:"墨西哥",sources:["墨西哥政府1985年9月关于灾情的公告、死者登记与倒塌建筑清单","泛美卫生组织与世界银行1986年关于震害、伤亡与损失的评估报告"],tags:["地震","城市","民间救济"]},related:["world--1982--e01", "world--1985--c01"]},
  {id:"world--1986--d01",track:"world",year:1986,yearApprox:false,dim:"disaster",weight:5,title:"切尔诺贝利四号堆爆炸",summary:"四月二十六日汽轮机试验失控导致蒸汽爆炸与石墨火灾，扩散至欧洲。",detail:{background:"该站四号堆在建安全试验中以降低功率运行，控制棒设计与氙毒积累使堆处于不稳定状态。",process:"1986年4月26日凌晨汽轮机惰转试验中功率骤升，操作者按下紧急停堆按钮后发生蒸汽爆炸并掀开堆顶，石墨慢化剂燃烧；苏联5月通报堆芯损毁与操作人员死亡，多国在4月底至5月测到放射性沉降。",impact:"国际原子能机构1986年8月会后审评报告与后来的国际评定把事故列为最高级别；苏联公布的疏散与受照人数、世卫组织与各国研究机构对癌症死亡与损失的估计差异较大；该事故推动各国改组核监管与运行程序，并在1980年代后期加剧东欧对核能与信息公开的争议。",figures:["维克托·布里尤哈诺夫"],place:"乌克兰普里皮亚季与切尔诺贝利",state:"苏联",sources:["苏联政府1986年5月与8月的事故通报及国际原子能机构会后审评会议报告（INSAG-1，1986年）","联合国原子辐射影响科学委员会2000年报告第五部分与切尔诺贝利论坛2005年《切尔诺贝利的遗产》"],tags:["核事故","疏散","监管"]},related:["world--1979--d01", "world--1986--p01"]},
  {id:"world--1986--p01",track:"world",year:1986,yearApprox:false,dim:"politics",weight:3,title:"伊朗门事件曝光",summary:"十一月三日贝鲁特周刊披露对伊军售，资金转尼反政府武装。",detail:{background:"1985年起美国经由以色列向伊朗运送武器以换取人质渠道，同时国会以博兰条款限制对尼加拉瓜反政府武装的援助。",process:"1986年11月3日贝鲁特一份阿拉伯语周刊刊登对伊武器输送的独家报道，国会随后召开听证；11月里根承认部分资金被用于尼加拉瓜方面，国家安全委员会助理波因德克斯特辞职，1987年2月塔楼委员会公布报告。",impact:"两院1987年11月联合调查报告认定总统负有领导责任但无法证明其直接授权，多名官员被定罪后获减刑或赦免；该事件促使1980年代末对情报与准军事行动的通报制度被重写，并影响此后对伊、对尼政策的公开性。",figures:["罗纳德·里根","约翰·波因德克斯特","奥利弗·诺思"],place:"美国华盛顿与黎巴嫩贝鲁特",state:"美国／伊朗／尼加拉瓜",sources:["美国国会两院1987年11月伊朗门事件联合调查报告正文与1987年7至10月听证记录","里根1986年11月与1987年3月的全国讲话及塔楼委员会报告（1987年2月）"],tags:["情报","国会听证","武器输送"]},related:["world--1979--p02", "world--1987--p01"]},
  {id:"world--1986--p02",track:"world",year:1986,yearApprox:false,dim:"politics",weight:3,title:"菲律宾人民力量革命",summary:"二月二十二日军方倒向反对派，二十五日马科斯离国，阿基诺就职。",detail:{background:"1986年2月7日提前总统选举后，官方快数与全国自由运动的分别计票结果相互冲突，反对派发起不服从运动。",process:"1986年2月22日国防部长恩里莱与陆军参谋长拉莫斯退守克拉马军营，数十万人在马尼拉人民力量革命大道聚集；2月25日阿基诺夫人就职，同日马科斯在美军直升机护送下离国赴夏威夷，3月25日颁布临时宪法。",impact:"临时宪法把过渡期特别权力授予总统，1986至1987年间多次军事叛乱与左翼游击战同时存在；马科斯家族的资产追缴在菲律宾与美国法院持续多年，双方对其在任期间的债务与赔偿认定存在长期分歧。",figures:["科拉松·阿基诺","费迪南德·马科斯","胡安·恩里莱"],place:"菲律宾马尼拉克拉马与艾莎大道",state:"菲律宾",sources:["1986年2月7日总统选举的全国自由运动计票与官方快数结果对照记录","科·阿基诺1986年2月25日就职声明与1986年3月25日《自由宪法》即临时宪法文本"],tags:["政权更替","公民运动","临时宪法"]},related:["world--1965--p02", "world--1986--d01"]},
  {id:"world--1986--s01",track:"world",year:1986,yearApprox:false,dim:"science",weight:3,title:"献血筛查纳入抗体检测",summary:"首个抗体检测试剂获准后，各国输血机构在一九八五至八六年全面采用。",detail:{background:"1981至1983年间确认经血液与血制品传播的病例后，各国开始要求对献血者作筛查，早期依赖抗原与非特异方法。",process:"1985年3月首个人T细胞白血病与艾滋病相关病毒抗体筛查试剂在美国获准上市，输血行业组织随即建议全面筛查；1985至1986年欧洲、日本与拉美多国陆续把抗体检测纳入常规献血流程并延长了献血者随访。",impact:"筛查使经输血传播的病例在新诊断中迅速下降，但1985至1988年间仍出现检测窗口期与漏检的诉讼；日本与欧洲多国此后就血友病患者感染责任展开审判与赔偿，各国公布的感染人数与责任认定差异较大。",figures:["吕克·蒙泰尼耶"],place:"美国与法国、日本的血站与检测机构",state:"多国",sources:["美国食品与药物管理局1985年3月关于抗体筛查试剂批准的公开公告与世界卫生组织1986至1988年安全输血通报","蒙泰尼耶等1983年关于从高危患者分离相关逆转录病毒的论文（法国巴斯德研究所）与各国血液机构1985至1988年筛查规程"],tags:["血液筛查","公共卫生","责任"]},related:["world--1981--s01", "world--1987--i01"]},
  {id:"world--1987--p01",track:"world",year:1987,yearApprox:false,dim:"politics",weight:4,title:"中导条约签署",summary:"十二月八日两国签署消除中程与中短程导弹条约，首次整类销毁。",detail:{background:"1979年北约双轨决定后，苏方部署可覆盖西欧的中程弹道导弹，美方于1983至1984年在西欧部署巡航导弹与潘兴二型；1985至1987年日内瓦谈判把议题从削减改为消除。",process:"1987年12月8日戈尔巴乔夫与里根在华盛顿签署《中程与中短程导弹条约》，销毁射程五百至五千五百公里的陆基弹道与巡航导弹及其发射、保障与支援设施；1988年6月1日生效，销毁与现场视察在1991年6月1日前完成。",impact:"这是两国首次整类消除核投送系统并引入随时通知式现场视察；条约的核查条款与「中程」定义成为1988至2019年间双方争论的焦点，美国于2019年退出该约。",figures:["米哈伊尔·戈尔巴乔夫","罗纳德·里根"],place:"美国华盛顿",state:"苏联／美国",sources:["《美利坚合众国与苏维埃社会主义共和国联盟消除中程与中短程导弹条约》正文（1987年12月8日签署，1988年6月1日生效）及其销毁时间表","条约核查附件与双方1988至1991年公布的现场视察与销毁完成通报"],tags:["裁军","核查","导弹"]},related:["world--1979--m01", "world--1988--p02"]},
  {id:"world--1987--p02",track:"world",year:1987,yearApprox:false,dim:"politics",weight:3,title:"第一次因提法达爆发",summary:"十二月九日起加沙与西岸出现总罢工与街头对抗，持续数年。",detail:{background:"1967年后被占领土的行政与劳工安排、土地与用水纠纷及1980年代初的驱逐政策积累不满，1987年12月8日一辆军车与面包车相撞致多名巴勒斯坦工人死亡。",process:"1987年12月9日起加沙贾巴利亚难民营爆发示威并蔓延至西岸，各派别发表全国总罢工与抵抗号召，成立统一的民族起义领导机构；以色列当局实施宵禁、驱逐与拘留，冲突延续至1991年后。",impact:"安理会第605号决议（1987年12月22日）注意到被占领土局势并重申第四项日内瓦公约适用；双方在1988至1993年间公布的人员伤亡与被拘数字差异较大，1993年《奥斯陆协议》以该阶段的机构与诉求为前提展开。",figures:["亚西尔·阿拉法特"],place:"加沙地带贾巴利亚与约旦河西岸",state:"巴勒斯坦／以色列",sources:["1987年12月9日起巴勒斯坦各派别发布的总罢工与全国起义号召传单及统一领导机构公告","联合国安全理事会第605号决议（1987年12月22日）正文与双方同期公布的伤亡、拘留数字"],tags:["起义","占领","罢工"]},related:["world--1967--p01", "world--1988--m01"]},
  {id:"world--1987--i01",track:"world",year:1987,yearApprox:false,dim:"institution",weight:3,title:"《我们共同的未来》发表",summary:"世界环境与发展委员会把可持续发展定义为兼顾当代与后代需求。",detail:{background:"1983年成立的委员会以布伦特兰为主席，先后收到各国与机构的专题报告，围绕增长与生态约束的争论贯穿三年。",process:"1987年委员会发表《我们共同的未来》，把可持续发展界定为「满足当代需求而不损害后代满足其需求的能力」，并就人口、粮食、能源、工业与全球治理提出政策建议；同年12月联大注意到该报告并着手筹备专门大会。",impact:"该定义成为1992年里约会议与2015年可持续发展目标的通用表述；报告把贸易、债务与环境约束并列讨论，其后关于「绿色增长」与生态限制的分歧在历次环境大会上延续。",figures:["戈哈·布伦特兰","莫里斯·斯特朗"],place:"挪威奥斯陆与纽约",state:"世界环境与发展委员会",sources:["世界环境与发展委员会《我们共同的未来》（牛津大学出版社，1987年）正文与提交联合国大会的文件编号","联合国大会1987年12月关于该报告与环境发展议程的决议文本与《联合国大会正式记录》"],tags:["可持续发展","报告","环境"]},related:["world--1972--i01"]},
  {id:"world--1987--e01",track:"world",year:1987,yearApprox:false,dim:"economy",weight:3,title:"全球股市黑色星期一",summary:"十月十九日道指单日下挫两成二，多国交易所暂停交易。",detail:{background:"1987年美债与贸易逆差、利率上行与程序化交易、组合保险策略相互叠加，10月中旬市场连续下跌。",process:"1987年10月19日纽约股市道琼斯工业指数收跌五百余点、跌幅约两成二，伦敦与东京等主要市场同日大幅下挫，悉尼与香港当日停市；各国交易所在数日内引入熔断与涨跌停限制。",impact:"总统金融市场工作组1988年2月报告把跨市场信息与结算时滞列为放大机制，此后各国建立熔断与结算改革、1988年七国巴黎会议重申汇率与流动性协调；各国公布的单日跌幅与流动性数据因指数与统计口径不同而不宜直接比较。",figures:["艾伦·格林斯潘"],place:"美国纽约与伦敦、东京、香港",state:"多国",sources:["纽约证券交易所与芝加哥商品交易所1987年10月19至20日的成交与指数数据","总统金融市场工作组《股灾与市场结构》报告（1988年2月）及各国交易所引入熔断机制的公告"],tags:["股灾","熔断","跨市场"]},related:["world--1971--e01"]},
  {id:"world--1988--c01",track:"world",year:1988,yearApprox:false,dim:"culture",weight:2,title:"汉城奥运会举办",summary:"九月十七日至十月二日在汉城举行，朝鲜与古巴等国未出席。",detail:{background:"1981年国际奥委会选定汉城为主办城市后，朝鲜与韩国自1985年起会谈合办与共用旗号未果，1987年11月大韩航空858号班机被炸毁使安全议题提前升温。",process:"1988年9月17日至10月2日第二十四届夏季奥运会在汉城举行，官方报告统计的参赛代表团为一百五十余个，朝鲜、古巴、伊朗、阿尔巴尼亚、埃塞俄比亚与尼加拉瓜等未出席；两个德国分别组队参赛。",impact:"该届奥运把主办权与冷战后期东亚格局并置；1991年朝鲜与韩国同时加入联合国，奥运主办与参赛资格此后成为双方外交承认竞争的场域，国际奥委会则要求成员国政府保证运动员的参赛权利。",figures:["金云龙","胡安·安东尼奥·萨马兰奇"],place:"韩国汉城（首尔）",state:"大韩民国",sources:["国际奥委会1988年汉城奥运会官方报告与参赛代表团统计","朝鲜与古巴等国1988年宣布不出席的公开声明及1987年朝奥会谈记录"],tags:["奥运","东亚","抵制"]},related:["world--1980--p01", "world--1988--p01"]},
  {id:"world--1988--m01",track:"world",year:1988,yearApprox:false,dim:"military",weight:3,title:"伊朗航空六五五号被击落",summary:"七月三日巡洋舰在波斯湾发射导弹，机上二百九十人全部遇难。",detail:{background:"1988年4月美军军舰在伊朗水域触雷后于7月3日对伊朗炮艇发动「祈祷螳螂」行动，「文森斯」号同时向民航机发射导弹。",process:"1988年7月3日上午自阿巴斯港起飞的伊朗航空655号班机在爬升阶段被击落，机上人员全部遇难；美国方面称误判为军机，国际民航组织理事会随后决议并展开调查，1996年美国以自愿款项向遇难者家属支付赔偿而不承认法律责任。",impact:"伊朗1989年将案提交国际法院，1996年双方以和解结案；事件推动波斯湾民航航路与通告制度的修订，联合国大会每年决议的追悼与赔偿记录延续至今。",figures:["威廉·罗杰斯"],place:"波斯湾霍尔木兹海峡上空",state:"美国／伊朗",sources:["1988年7月3日至5日美国国防部关于击落事件的调查报告与伊朗政府同日照会","国际民航组织理事会1988年关于该事件的决议与伊朗提交国际法院的起诉文书及1996年和解记录"],tags:["民航","误判","赔偿"]},related:["world--1987--p02", "world--1980--m01"]},
  {id:"world--1988--p01",track:"world",year:1988,yearApprox:false,dim:"politics",weight:3,title:"缅甸八八八八起义",summary:"八月八日全国示威，九月十八日军委接管，随后展开镇压。",detail:{background:"1988年7月奈温辞职后党内外要求改革，学生与工人组织于8月发起集会，仰光在8月8日前后出现大规模游行。",process:"1988年8月8日起多地爆发示威，8月26日昂山素季在仰光大金塔前发表演说要求选举；9月18日军方成立国家恢复法律与秩序委员会接管政权，随后对示威与僧团网络实施镇压，军政府公布的死亡与被拘数字与各民间统计差异较大。",impact:"1990年5月大选中全国民主联盟获胜但军政府未交权，1990年代起联合国大会与人权委员会连续通过相关决议并对军政高层实施制裁；缅甸直到2011年后才开始新的政治与经济开放进程。",figures:["昂山素季","苏貌"],place:"缅甸仰光与曼德勒",state:"缅甸",sources:["缅甸国家恢复法律与秩序委员会1988年9月18日第一号公告与军政府随后公布的伤亡、拘押数字","1988年8月学生与僧侣组织的诉求书及联合国人权委员会1992至1994年关于缅甸局势的决议"],tags:["起义","军政府","制裁"]},related:["world--1988--c01", "world--1989--p02"]},
  {id:"world--1988--d01",track:"world",year:1988,yearApprox:false,dim:"disaster",weight:3,title:"亚美尼亚斯皮塔克大地震",summary:"十二月七日六点八级地震毁斯皮塔克与列宁纳坎，苏联首受西方援助。",detail:{background:"亚美尼亚北部处于活跃断裂带，斯皮塔克一带工业与居民建筑抗震等级偏低，1988年12月7日发生主震。",process:"1988年12月7日十一时四十一分矩震级约六点八的地震毁斯皮塔克、列宁纳坎（久姆里）与基洛瓦巴德（占贾）等城镇，苏联官方登记的死者数以万计、无家可归者以数十万计，各国包括美国与西欧的救援队与物资在数日内抵达。",impact:"官方死亡登记与后来亚美尼亚方面及研究机构公布的估计差异较大；灾难与地震应急失败加剧了对共和国当局的公开批评，与1988年11月卡拉巴赫委员会成立的诉求相互叠加，成为1990年代独立运动的背景之一。",figures:["尼古拉·雷日科夫"],place:"亚美尼亚斯皮塔克与列宁纳坎",state:"苏联",sources:["苏联政府1988年12月关于亚美尼亚灾情的通报与联合国救灾协调专员办公室的灾情报告","亚美尼亚方面后来公布的死者登记与各国地震台网测定的矩震级通报"],tags:["地震","援助","共和国"]},related:["world--1988--p01", "world--1991--p04"]},
  {id:"world--1988--d02",track:"world",year:1988,yearApprox:false,dim:"disaster",weight:3,title:"洛克比空难",summary:"十二月二十一日泛美一百零三号在小镇上空解体，地面与机上共二百七十人死亡。",detail:{background:"该班机自法兰克福经伦敦飞往底特律，1988年12月21日晚在苏格兰南部上空发生货舱爆炸并解体坠地。",process:"1988年12月21日洛克比一带的住宅区被残骸与燃油击中，机上与地面死亡合计二百七十人；英国检察当局1988至1991年主导调查，1991年11月起诉两名利比亚情报人员；1992年安理会先后通过第731与第748号决议要求移交嫌疑人。",impact:"2000年起在荷兰境内设置的苏格兰特别法庭于2001年1月31日判决一名被告有罪并判刑，另一名无罪；2009年该被告以人道理由获释并于2012年去世，两国与家属就赔偿与调查责任的谈判及各国后来公布的调查结论存在分歧。",figures:["阿卜杜拉·迈格拉希"],place:"苏格兰洛克比与荷兰蔡斯特营",state:"英国／美国／利比亚",sources:["英国航空事故调查局与苏格兰检察当局1988至1991年关于103号班机坠毁的调查与起诉文件","联合国安理会第731号与第748号决议（1992年）正文及2001年1月31日洛克比特别法庭判决书"],tags:["空难","起诉","制裁"]},related:["world--1983--m02", "world--1988--p01", "world--1986--m01"]},
  {id:"world--1988--p02",track:"world",year:1988,yearApprox:false,dim:"politics",weight:3,title:"波兰八月罢工与圆桌会谈开端",summary:"八月十五日起格但斯克等地再次罢工，当局同意与工会对话。",detail:{background:"1982年12月军管解除后团结工会长期处于非法状态，1987至1988年外债与物价压力使多地罢工再起。",process:"1988年5月与8月15日起华沙、克拉科夫与格但斯克列宁造船厂相继罢工，提出恢复工会合法性与提高工资；8月31日瓦文萨公开要求恢复团结工会并同意与内政部长基什查克电视对话，当局随后宣布允许多党对话。",impact:"1989年2月6日起的圆桌会议把工会、教会与当局纳入同一谈判程序，6月4日选举与8月新政府相继出现；该谈判程序成为1989年东欧多国政权交接被反复援引的模板，各方对罢工规模与参与人数的统计口径存在差异。",figures:["莱赫·瓦文萨","切斯瓦夫·基什查克"],place:"波兰格但斯克与华沙",state:"波兰",sources:["1988年8月各罢工委员会的诉求书与瓦文萨8月31日要求恢复团结工会合法性的声明","波兰当局1988年8至9月关于罢工与复工的官方公报及瓦文萨与基什查克的电视对话记录"],tags:["罢工","对话","工会"]},related:["world--1980--p03", "world--1989--p02"]},
  {id:"world--1989--p01",track:"world",year:1989,yearApprox:false,dim:"politics",weight:5,title:"柏林墙边界开放",summary:"十一月九日晚公布可即时出境，当日夜间多处口岸涌入人群。",detail:{background:"1989年8月起匈牙利与捷克斯洛伐克方向的旅行限制松动，9月11日匈牙利开放对民主德国公民的出境，5月与8月的地方选举抗议与10月莱比锡每周一示威持续扩大。",process:"1989年11月9日傍晚民主德国政府宣布公民可申请即时出境，官员沙博夫斯基在当日记者会上被问及生效时间时回答「立即」；当晚博恩霍尔默大街等口岸出现人群，边防人员在未收到清晰指令的情况下放行，11月10日起市民开始用工具拆除墙体。",impact:"边界开放后两德货币与条约谈判加速，1990年3月18日人民议院选举与10月3日统一条约相继完成；关于1961至1989年死于墙下与射击的人数，柏林墙研究机构与检察机关的统计口径长期存在差异。",figures:["君特·沙博夫斯基","米哈伊尔·戈尔巴乔夫"],place:"柏林博恩霍尔默大街与跨越边界口岸",state:"德意志民主共和国／德意志联邦共和国",sources:["民主德国政府1989年11月9日关于开放出境旅行的公告与沙博夫斯基当日记者会记录","柏林墙研究中心与13·8工作团体关于1961至1989年死亡人数与1989年11月通行记录的整理"],tags:["边界","放行","统一"]},related:["world--1961--p02", "world--1990--p01"]},
  {id:"world--1989--p02",track:"world",year:1989,yearApprox:false,dim:"politics",weight:3,title:"捷克斯洛伐克天鹅绒革命",summary:"十一月十七日学生示威遭镇压后全国总罢工，十二月底哈维尔当选总统。",detail:{background:"1969年1月帕拉赫自焚后异议团体长期受监控，1989年1月其二十周年纪念活动被警方驱散，波兰与匈牙利的变化提供参照。",process:"1989年11月17日布拉格学生的纪念游行遭警棍驱散，11月19日公民论坛成立并要求对话；11月20至27日连日示威与11月27日全国总罢工后，联邦议会于11月29日删除宪法中党的领导条款，12月10日总统胡萨克辞职，12月29日哈维尔当选。",impact:"1990年6月首次自由选举与1992至1993年的解体表决沿用本阶段的谈判程序；1989年12月至1990年对国家安全机关人员的审查与档案公开成为此后历届政府争议的焦点，各方对镇压责任人的追究范围认定不一。",figures:["瓦茨拉夫·哈维尔","亚历山大·杜布切克"],place:"捷克斯洛伐克布拉格与布拉迪斯拉发",state:"捷克斯洛伐克",sources:["1989年11月19日《公民论坛》成立宣言与11至12月的请愿、罢工号召文本","捷克斯洛伐克联邦议会1989年11月29日关于撤销宪法领导条款的修正案与12月29日总统选举记录"],tags:["异议","罢工","制宪"]},related:["world--1968--p01", "world--1989--p03"]},
  {id:"world--1989--p03",track:"world",year:1989,yearApprox:false,dim:"politics",weight:4,title:"罗马尼亚齐奥塞斯库覆灭",summary:"十二月十五日蒂米什瓦拉起因，二十二日政权更迭，二十五日夫妇被处决。",detail:{background:"1988至1989年罗马尼亚因还债与紧缩配给使城市供应紧张，1989年3月六名党元老公开信要求改变经济与安全政策，匈牙利方向的边界开放使出境渠道可及。",process:"1989年12月15日蒂米什瓦拉当局试图驱逐匈牙利族牧师陶卡奇，信众游行转为反政府示威并遭武装射击；12月21日齐奥塞斯库在中央委员会大楼前的集会上被人群打断，22日军方倒向抗议者，夫妇出逃后被拘，救国阵线委员会公布接管声明；12月25日军事法庭宣判并当日执行。",impact:"1989年12月至1990年初的死亡与处决数字在军政府公告、检察卷宗与议会调查委员会之间口径差异较大；1990年5月选举后关于前保安机关人员留任与审判范围的争论延续至2000年代的历史委员会报告。",figures:["尼古拉·齐奥塞斯库","陶卡奇·洛绍林奇"],place:"罗马尼亚蒂米什瓦拉与布加勒斯特、特勒戈维斯特",state:"罗马尼亚",sources:["罗马尼亚救国阵线委员会1989年12月22日第一号公告与12月25日关于军事法庭审判与执行的公告","1990年代罗马尼亚检察机关重开的案卷与议会调查委员会关于1989年12月死亡人数与责任认定的结论"],tags:["起义","审判","政权更迭"]},related:["world--1989--p02", "world--1990--p01"]},
  {id:"world--1989--p04",track:"world",year:1989,yearApprox:false,dim:"politics",weight:3,title:"美苏马耳他会晤",summary:"十二月二至三日两国元首在地中海会谈，双方就东欧变化与裁军口径接近。",detail:{background:"1989年波兰与匈牙利的圆桌与选举、柏林墙开放与捷克斯洛伐克的政权更迭同时发生，美方要求苏联对东欧变化不采取军事干预。",process:"1989年12月2至3日戈尔巴乔夫与老布什在马耳他会谈三轮，就德国问题、欧洲裁军谈判与地区冲突交换立场；因天气与日程，原定次日会议未进行，双方以记者会说明共识范围而未签署联合文件。",impact:"会后双方分别以「不再把对方视为对手」的措辞公开表态；1990年起关于德国统一与北约归属的谈判、1990年11月《欧洲常规武装力量条约》以及1991年的削减进攻性战略武器安排均在此后展开。",figures:["米哈伊尔·戈尔巴乔夫","乔治·赫伯特·沃克·布什"],place:"马耳他瓦莱塔外海与停泊船只",state:"苏联／美国",sources:["美苏1989年12月2至3日马耳他会谈双方记者会记录与随行官员公布会谈纪要文本","戈尔巴乔夫1989年12月3日与布什同日离会时的公开声明"],tags:["峰会","裁军","东欧"]},related:["world--1989--p01", "world--1991--p02"]},
  {id:"world--1989--d01",track:"world",year:1989,yearApprox:false,dim:"disaster",weight:3,title:"埃克森瓦尔迪兹号溢油",summary:"三月二十四日油轮在暗礁触底，原油沿威廉王子湾扩散。",detail:{background:"该船自瓦尔德兹装运原油南下，三副值班，航线为避开浮冰而偏离常规水道，1989年3月24日凌晨在布莱夫礁触底。",process:"1989年3月24日船体八处货舱破口泄漏，国家运输安全委员会与法院程序认定的泄漏量以加仑与桶两种单位公布；清理在1989年夏至1992年间分段进行，海獭、海鸟与鲑鱼等种群受创，各方公布的死亡数量差异较大。",impact:"1990年8月《石油污染法》确立漏油责任基金、双壳船期限与联邦、州和部落的索赔主体；民事与惩罚性赔偿经多轮上诉后确定数额，1989至2000年代关于渔场补偿与生态恢复的评估在各方统计中长期不一致。",figures:["约瑟夫·黑泽伍德"],place:"美国阿拉斯加威廉王子湾",state:"美国",sources:["美国国家运输安全委员会《关于1989年3月24日埃克森瓦尔迪兹号触礁溢油事故的调查报告》（1990年）","《1990年石油污染法》正文与联邦法院关于民事与惩罚性赔偿数额的历次判决记录"],tags:["溢油","清理","油污法"]},related:["world--1989--e01", "world--1991--d01"]},
  {id:"world--1989--x01",track:"world",year:1989,yearApprox:false,dim:"explore",weight:2,title:"旅行者二号飞掠海王星",summary:"八月二十五日近距离掠过海王星，公布大暗区与新环带数据。",detail:{background:"1977年发射的旅行者二号借行星连珠依次外推，天王星飞掠后轨道计算指向海王星，1989年8月为最后一个大行星目标。",process:"1989年8月25日探测器以约四千九百公里的最近距离掠过海王星云顶，成像与掩星实验公布大暗区、高速风场与环带弧状结构，并在9月前后确认多颗新卫星；随后飞掠海卫一并测得其表面温度与喷发迹象。",impact:"该次飞掠使太阳系四大行星外缘均取得近距离数据，其无线电掩星资料至今是海王星大气模型的基础；探测器转入日球层边缘观测，1990年代后与先驱者号、旅行者一号共同测定日球层界面。",figures:["爱德华·斯通"],place:"海王星系统与外海王星卫星轨道",state:"美国",sources:["美国国家航空与航天局喷气推进实验室1989年8月25日至9月关于海王星近掠的数据通报","旅行者二号成像与射电科学团队1989年在《科学》杂志刊出的海王星观测专辑"],tags:["海王星","掩星","外行星"]},related:["world--1977--x01", "world--1990--s01"]},
  {id:"world--1989--e01",track:"world",year:1989,yearApprox:false,dim:"economy",weight:3,title:"日本股价与地价达顶点",summary:"十二月二十九日日经指数收在历史最高，都市地价同期见顶。",detail:{background:"1985年广场协议后日元升值与国内低利率、金融自由化叠加，企业与个人以土地作担保扩张融资，银行资金大量流向不动产。",process:"1989年12月29日东京股市日经225指数收于当年最后一个交易日的历史最高点，同年六大都市商业地价与住宅地价涨幅居前；日本银行自1989年5月起陆续上调官方贴现率，1990年8月升至逾六年水平。",impact:"股价在1990年内下跌过半，地价在1991年后连续多年回落，不良债权问题在1990年代中后期集中暴露；关于泡沫期资产价格与银行损失的统计因指数、地价口径与评估时点不同而存在差异。",figures:["三重野康"],place:"日本东京与六大都市圈",state:"日本",sources:["东京证券交易所1989年12月29日日经225指数收市记录与日本银行《金融经济统计月报》","日本大藏省1989至1990年关于地价与银行融资的统计及历次官方贴现率调整公告"],tags:["泡沫","地价","贴现率"]},related:["world--1971--e01", "world--1990--p01"]},
  {id:"world--1990--p01",track:"world",year:1990,yearApprox:false,dim:"politics",weight:5,title:"两德统一条约生效",summary:"十月三日民主德国五州加入基本法适用范围，统一条约同日生效。",detail:{background:"1990年3月18日人民议院首次自由选举，主张快速统一的德国联盟胜出；7月1日货币、经济与社会联盟条约生效，德马克成为共同货币。",process:"1990年8月31日两德签署统一条约，9月12日四国与两德在莫斯科签署关于德国最终解决的条约，规定军队规模、外国军队与核武器限制；10月3日依基本法第二十三条，五个新州加入联邦共和国。",impact:"统一后的边界与财产归还、托管与私有化机构处理前东德国有资产，各方就失业、迁移与补偿公布的统计口径不同；1991年起联邦议院与政府迁都的程序、以及东部州政治格局的长期分化，均以此为起点。",figures:["赫尔穆特·科尔","洛塔尔·德梅齐埃","米哈伊尔·戈尔巴乔夫"],place:"柏林与莫斯科",state:"德意志联邦共和国／德意志民主共和国",sources:["《德意志联邦共和国与德意志民主共和国关于建立德国统一的条约》（1990年8月31日签署，10月3日生效）正文","《关于德国的最终解决条约》（1990年9月12日莫斯科签署）正文与民主德国1990年3月18日人民议院选举官方计票公告"],tags:["统一","条约","北约"]},related:["world--1989--p01", "world--1990--m01"]},
  {id:"world--1990--p02",track:"world",year:1990,yearApprox:false,dim:"politics",weight:4,title:"曼德拉获释与南非解禁",summary:"二月二日宣布解禁政治组织，二月十一日曼德拉出狱。",detail:{background:"1980年代反种族隔离运动与国内紧急状态、国际制裁与谈判接触并行，1989年9月政府与非洲人国民大会在开普顿会见，1990年2月议会开幕前达成步骤安排。",process:"1990年2月2日德克勒克在议会宣布解除对非洲人国民大会、泛非主义者大会与南非共产党等组织的禁令并释放政治犯；2月11日曼德拉自开普顿郊区的监狱出狱并在市政厅前宣读声明，5月双方签署格罗特施库尔要点。",impact:"1991年废除种族隔离三大法律、1993至1994年多党谈判与首次不分种族选举相继完成；1990至1994年间纳塔尔与城镇的暴力死亡人数由真相委员会与各方分别统计，口径差异较大。",figures:["纳尔逊·曼德拉","弗雷德里克·威廉·德克勒克"],place:"南非开普顿与比勒陀利亚",state:"南非",sources:["南非总统1990年2月2日议会开幕演说的政府公报文本与解除禁令的政府公告","纳尔逊·曼德拉1990年2月11日在开普顿市政厅前的声明全文与监狱当局的释放登记"],tags:["释放","解禁","谈判"]},related:["world--1964--i01", "world--1991--p02"]},
  {id:"world--1990--p03",track:"world",year:1990,yearApprox:false,dim:"politics",weight:3,title:"纳米比亚独立",summary:"联合国监督下选出制宪议会并通过宪法，三月二十一日宣布独立。",detail:{background:"南非自1915年委任统治后长期拒绝联合国托管终止决定，1978年安理会第435号决议规定过渡方案，1989年各方同意在联合国监督下选举。",process:"1989年4月起联合国过渡团监督停火与登记，11月制宪议会选举由西南非洲人民组织胜出；1990年2月议会通过宪法，3月21日午夜宣布独立，努乔马任总统，同日南非撤回行政管辖。",impact:"独立后土地分配与归还程序成为长期议题，1990年代起南非与纳米比亚就鲸湾港与离岸群岛的地位按国内立法与双边协议逐步处理；安哥拉与纳米比亚边境的军事与难民问题在1991年后继续由联合国监测。",figures:["萨姆·努乔马","马蒂·阿赫蒂萨里"],place:"纳米比亚温得和克",state:"纳米比亚／南非／联合国",sources:["联合国安全理事会第435号决议（1978年9月29日）与联合国过渡团关于1989年11月制宪议会选举结果的公告","纳米比亚1990年2月制宪议会通过的宪法文本与1990年3月21日独立公告"],tags:["托管终止","选举","独立"]},related:["world--1960--i01", "world--1990--p02"]},
  {id:"world--1990--m01",track:"world",year:1990,yearApprox:false,dim:"military",weight:4,title:"伊拉克军队占领科威特",summary:"八月二日凌晨越境，八日宣布合并，安理会随后启动制裁与授权。",detail:{background:"两伊战争结束后伊拉克就债务、欧佩克产量配额与鲁迈拉油田边界与科威特争执，1990年7月在吉达会谈未果。",process:"1990年8月2日凌晨伊拉克部队进入科威特，埃米尔出逃沙特，8月8日宣布合并并称其为「第十九省」；安理会第660号决议要求撤军，第661号决议实施全面制裁，11月29日第678号决议设定1991年1月15日为最后期限并授权「一切必要手段」。",impact:"1991年1月17日至2月28日多国部队行动后伊军撤出并纵火油井，战后边界由联合国划界委员会确定，1991年4月起以赔偿与核查机制处理；双方及联合国机构公布的平民死亡与被俘人数、油井火灾与环境损失估计差异较大。",figures:["萨达姆·侯赛因","贾比尔·艾哈迈德·萨巴赫"],place:"科威特城与伊科边界",state:"伊拉克／科威特／联合国",sources:["联合国安理会第660、661、662号决议（1990年8月）与第678号决议（1990年11月29日）正文","伊拉克革命指挥委员会1990年8月2日与8月8日公告及科威特流亡政府同期声明"],tags:["占领","制裁","授权"]},related:["world--1980--m01", "world--1991--m01"]},
  {id:"world--1990--s01",track:"world",year:1990,yearApprox:false,dim:"science",weight:3,title:"哈勃空间望远镜入轨",summary:"四月二十五日由发现号部署，主镜缺陷在1993年首次维修中矫正。",detail:{background:"该望远镜自1970年代立项，由美欧机构联合研制，原定1983年发射因挑战号事故与经费问题推迟。",process:"1990年4月24至25日发现号航天飞机在STS-31任务中把望远镜送入约六百公里的轨道，主镜直径约2.4米；1990年末地面检验发现主镜球面像差，1993年12月STS-61维修任务装入矫正光学系统后恢复设计分辨能力。",impact:"其后多次维修更换仪器并延长寿命，深场影像与哈勃常数测量成为宇宙学参数估计的基础数据；1990年代至2020年代的世代更替由詹姆斯·韦布空间望远镜承接，二者观测波段的差异成为公开争论焦点。",figures:["南希·罗曼"],place:"美国佛罗里达与近地轨道",state:"美国／欧洲机构合作",sources:["美国国家航空与航天局《STS-31任务报告》（1990年）与1990年12月关于主镜像差的技术通报","STS-61维修任务报告（1994年）与后来哈勃数据档案公布的测光与光谱资料"],tags:["空间望远镜","维修","宇宙学"]},related:["world--1989--x01", "world--1991--p02"]},
  {id:"world--1990--s02",track:"world",year:1990,yearApprox:false,dim:"science",weight:4,title:"万维网提案在核子研究中心提交",summary:"三月提出信息管理提案，年底首台服务器与浏览器在组织内运行。",detail:{background:"1980年代该组织内部实验数据分散于不同系统与文档格式，伯纳斯-李以超文本与传输协议结合的设想撰写方案。",process:"1990年3月《信息管理：一份提案》提交该组织管理部门并于9月修订，文件获上级批注鼓励；同年圣诞前后首台网页服务器与浏览器在组织内运行，1991年8月网页说明文档向组织外公开。",impact:"1993年4月该组织把万维网软件置于公有领域，1994年万维网联盟成立并制定标准；协议的开放性与无中心许可成为此后二十年网络服务扩张的制度前提，其技术标准与专利许可模式在1990年代末起持续引发争议。",figures:["蒂姆·伯纳斯-李","迈克·森达尔"],place:"瑞士日内瓦附近欧洲核子研究中心",state:"欧洲核子研究中心",sources:["蒂姆·伯纳斯-李《信息管理：一份提案》（欧洲核子研究中心，1990年3月）原件与同年9月修订版（该组织档案）","1991年8月向组织外公开的首版网页说明文档与1993年4月该组织关于软件置于公有领域的公告"],tags:["万维网","超文本","标准"]},related:["world--1969--s01", "world--1991--s01"]},
  {id:"world--1991--p01",track:"world",year:1991,yearApprox:false,dim:"politics",weight:3,title:"八一九事变与苏共被中止",summary:"八月十九日紧急状态委员会接管，二十二日戈尔巴乔夫复职，党活动被停。",detail:{background:"1991年3月全苏公投与4月起共和国主权宣言使联盟条约谈判提速，8月15日俄罗斯方面宣布将于8月20日签署新联盟条约。",process:"1991年8月18日副总统等人组成国家紧急状态委员会并宣布总统无法履职，19日坦克进入莫斯科；俄罗斯总统叶利钦在白宫前号召抵制，21至22日部队撤回、戈尔巴乔夫自克里米亚返莫斯科；23日叶利钦下令暂停俄境内共产党活动，11月6日禁止该党在俄活动。",impact:"事变后八个共和国在秋季宣布独立，联盟机构与共和国机构的权力划分成为实际议题；各方对8月19至21日莫斯科死亡人数、事件责任人与审判范围的认定在检察卷宗与议会调查之间存在差异。",figures:["米哈伊尔·戈尔巴乔夫","鲍里斯·叶利钦","根纳季·亚纳耶夫"],place:"莫斯科与克里米亚福罗斯",state:"苏联",sources:["苏联国家紧急状态委员会1991年8月19日声明与苏联最高苏维埃主席团同日关于中止总统职权的通知","俄罗斯苏维埃联邦社会主义共和国总统1991年8月23日关于暂停共产党活动的命令与同年11月6日的禁令文本"],tags:["政变","党禁","共和国"]},related:["world--1990--p01", "world--1991--p02"]},
  {id:"world--1991--p02",track:"world",year:1991,yearApprox:false,dim:"politics",weight:5,title:"苏联停止存在",summary:"十二月八日别洛韦日协定、二十一日阿拉木图议定书，二十五日总统辞职。",detail:{background:"1991年8月事变后乌克兰在12月1日公投确认独立，俄、乌、白三国领导人就此前的联盟条约另寻安排。",process:"1991年12月8日三国领导人在别洛韦日签署协定，宣告苏联作为国际法主体停止存在并成立独立国家联合体；12月21日八国签署《阿拉木图议定书》扩大成员，12月25日戈尔巴乔夫辞去总统职务并移交核按钮控制权，12月26日共和国院通过苏联终止存在的宣言。",impact:"1992年起各共和国分别加入国际组织并承担各自义务，核武器与黑海舰队的归属经由1992年明斯克与1994年布达佩斯安排处理；各方对解体责任、边界与公民身份的统计与法律认定在1990年代持续争议。",figures:["米哈伊尔·戈尔巴乔夫","鲍里斯·叶利钦","列昂尼德·克拉夫丘克"],place:"白俄罗斯别洛韦日与哈萨克斯坦阿拉木图",state:"苏联／独立国家联合体",sources:["《独立国家联合体成立协定》（1991年12月8日别洛韦日签署）与《阿拉木图议定书》（1991年12月21日）文本","戈尔巴乔夫1991年12月25日辞职演说与苏联最高苏维埃共和国院12月26日关于苏联终止存在的宣言"],tags:["解体","独联体","核继承"]},related:["world--1991--p01", "world--1991--p04"]},
  {id:"world--1991--m01",track:"world",year:1991,yearApprox:false,dim:"military",weight:4,title:"沙漠风暴行动",summary:"一月十七日开始空袭，二月二十四日地面战，二十八日停火。",detail:{background:"1990年11月29日安理会第678号决议授权会员国以一切必要手段在1991年1月15日后恢复科威特主权，多国部队在沙特集结。",process:"1991年1月17日起多国部队对伊拉克防空、指挥与战略设施实施空袭，2月24日地面部队分路进入科威特与伊拉克南部，27日宣布收复科威特城，28日在萨夫万达成停火；伊军撤退时点燃油井。",impact:"3月安理会第686、687号决议规定停火条件、武器核查与赔偿机制，此后核查由特别委员会与后来的机构执行；双方与联合国机构公布的军人和平民死亡、被俘与油井火灾及环境损失数字差异较大。",figures:["诺曼·施瓦茨科普夫","乔治·赫伯特·沃克·布什","萨达姆·侯赛因"],place:"科威特与伊拉克南部",state:"伊拉克／科威特／多国部队",sources:["联合国安理会第678号决议（1990年11月29日）与第686、687号决议（1991年3月）正文","美国国防部1992年《海湾战争最终报告》与伊拉克、科威特方面1991年公布的伤亡及被俘数字"],tags:["空袭","地面战","停火"]},related:["world--1990--m01", "world--1991--p02"]},
  {id:"world--1991--p03",track:"world",year:1991,yearApprox:false,dim:"politics",weight:3,title:"欧盟条约草案在马斯特里赫特通过",summary:"十二月九至十日首脑会批准联盟条约草案，设三大支柱与货币时间表。",detail:{background:"1989年德洛尔报告与1990年政府间会议启动货币联盟谈判，1991年2月起政治联盟草案在多轮次中反复修改。",process:"1991年12月9至10日欧洲共同体马斯特里赫特首脑会通过《欧洲联盟条约》草案文本，规定公民身份、共同外交与安全政策、司法与内务合作三大支柱以及经济与货币联盟的阶段表；英国与丹麦就社会条款与货币联盟取得豁免安排；条约于1992年2月7日签署。",impact:"1992年6月丹麦首次公投否决、同年11月法国以微弱多数通过后，条约于1993年11月1日生效；1997年阿姆斯特丹与2001年尼斯、2007年里斯本条约先后改写其机构与表决规则，豁免安排成为此后成员国谈判的先例。",figures:["赫尔穆特·科尔","弗朗索瓦·密特朗","约翰·梅杰"],place:"荷兰马斯特里赫特",state:"欧洲共同体十二成员国",sources:["欧洲共同体马斯特里赫特首脑会议1991年12月10日《主席声明与附件》与《欧洲联盟条约》草案文本","《欧洲联盟条约》正文（1992年2月7日签署，1993年11月1日生效）及英国、丹麦关于豁免议定书的政府声明"],tags:["一体化","三支柱","豁免"]},related:["world--1957--p01", "world--1992--p01"]},
  {id:"world--1991--s01",track:"world",year:1991,yearApprox:false,dim:"science",weight:3,title:"Linux 〇点〇一版对外发布",summary:"八月二十五日发帖宣布项目，九月起源码在芬兰站点公开下载。",detail:{background:"托瓦兹自1990年末在教学用机上编写类 unix 结构的内核，1991年1月购入386处理器机器，早期以教学系统的文件系统与终端仿真程序为起点。",process:"1991年8月25日他在 comp.os.minix 新闻组宣布正在编写「只是个人爱好，不会做成庞大的专业项目」的内核，9月17日0.01版源码经赫尔辛基理工大学的公开文件服务器发布，10月5日0.02版随同说明发布。",impact:"1992年1月的0.12版仍用限制商业分发的条款，1992年12月的〇点九九版起采用通用公共许可；随着1993年开发者网络扩大与1994年发行版出现，该内核成为服务器与嵌入式设备的基座，2010年代后延伸至移动设备与超算领域。",figures:["林纳斯·托瓦兹"],place:"芬兰赫尔辛基",state:"芬兰",sources:["林纳斯·托瓦兹1991年8月25日在 comp.os.minix 新闻组的发帖与1991年9至10月的0.01、0.02版源码存档","赫尔辛基理工大学公开文件服务器的发布记录与1992年关于许可证条款变更的说明"],tags:["内核","开源","发布"]},related:["world--1990--s02", "world--1969--s01"]},
  {id:"world--1991--p04",track:"world",year:1991,yearApprox:false,dim:"politics",weight:3,title:"波罗的海三国独立获承认",summary:"一月维尔纽斯流血，八月三国恢复独立，九月六日获苏联承认并入联合国。",detail:{background:"1989年8月绵延数百公里的波罗的海人链与1990年3月立陶宛独立宣言之后，苏联以经济封锁与奥蒙部队施压，拉脱维亚与爱沙尼亚各自宣布进入过渡期。",process:"1991年1月13日维尔纽斯电视塔与议会大楼前的冲突致十余人死亡；8月17至21日苏联方面试图接管，爱沙尼亚议会8月20日、拉脱维亚8月21日、立陶宛8月22日恢复独立决议生效，9月6日苏联国务委员会承认三国独立，9月17日三国同时被接纳为联合国会员国。",impact:"独立后公民身份以属地与血统条件重新划定，俄语居民的国籍与登记问题由欧安组织与威尼斯委员会多次评估；两国于2003至2004年加入北约与欧洲联盟，边境与撤军依1992至1994年双边协议处理。",figures:["兰茨贝尔吉斯","阿尔吉尔达斯·布拉藻斯卡斯"],place:"立陶宛维尔纽斯与拉脱维亚里加、爱沙尼亚塔林",state:"爱沙尼亚／拉脱维亚／立陶宛",sources:["三国1991年8月关于恢复独立生效的议会决议文本与苏联国务委员会1991年9月6日承认独立的决议","联合国大会1991年9月17日接纳三国为会员国的决议与1991年1月13日维尔纽斯事件的检察卷宗"],tags:["独立","承认","会员国"]},related:["world--1977--p02", "world--1991--p02", "world--1991--p07"]},
  {id:"world--1991--m02",track:"world",year:1991,yearApprox:false,dim:"military",weight:3,title:"克罗地亚与斯洛文尼亚战争爆发",summary:"六月二十五日宣布独立后南人民军介入，十一月武里达尔陷落。",detail:{background:"1990年克罗地亚境内塞族地区成立自治组织并提出改造南斯拉夫的要求，1991年3月普利特维采发生武装冲突，5月塞族自治区宣布并入塞尔维亚。",process:"1991年6月25日两国议会宣布独立，7月南人民军在斯洛文尼亚十日行动后依《布里俄尼协议》撤出；8月起克境内战事扩大，9月19日安理会第713号决议实施武器禁运，11月18日武里达尔在围城与炮击后陷落，12月杜布罗夫尼克遭炮击。",impact:"1992年1月欧共体承认两国、2月设立保护部队；1991至1995年的死亡与失踪人数由双方政府、检方与非政府组织分别统计，口径差异较大；2000年代前南刑庭的判决认定了多起针对平民的罪行与指挥责任。",figures:["弗拉尼奥·图季曼","米洛万·久拉诺维奇"],place:"斯洛文尼亚与克罗地亚武里达尔、杜布罗夫尼克",state:"南斯拉夫／克罗地亚／斯洛文尼亚",sources:["1991年6月25日斯洛文尼亚与克罗地亚独立宣言及同年7月8日《布里俄尼协议》文本","联合国安理会第713号决议（1991年9月25日）正文与前南问题国际会议及刑庭1990年代公布的伤亡与判决记录"],tags:["独立","围城","武器禁运"]},related:["world--1991--p04", "world--1992--p01"]},
  {id:"world--1991--i01",track:"world",year:1991,yearApprox:false,dim:"institution",weight:3,title:"削减进攻性战略武器条约签署",summary:"七月三十一日两国在莫斯科签署，设定六千枚部署弹头限额。",detail:{background:"1982年起日内瓦削减与限制战略武器谈判长期中断，1985年后与防御议题并行推进，1990年双方就数据与核查交换清单。",process:"1991年7月31日老布什与戈尔巴乔夫在莫斯科签署《削减与限制进攻性战略武器条约》，规定双方部署战略核弹头上限与运载工具限额，并建立数据交换、现场视察与通报机制；苏联解体后由四国承担义务。",impact:"1994年12月5日条约随乌克兰、白俄罗斯与哈萨克斯坦加入不扩散核武器条约并移交核武器后生效；此后以2002年《莫斯科条约》与2010年《新削减战略武器条约》延续其核查与数据交换框架，限额与计数规则沿用本约口径。",figures:["乔治·赫伯特·沃克·布什","米哈伊尔·戈尔巴乔夫"],place:"苏联莫斯科",state:"苏联／美国",sources:["《削减与限制进攻性战略武器条约》正文与议定书（1991年7月31日莫斯科签署，1994年12月5日生效）","1993年11月四国关于条约适用的备忘录与乌克兰、白俄罗斯、哈萨克斯坦1994年加入不扩散核武器条约的交存记录"],tags:["核裁军","核查","继承国"]},related:["world--1972--i02", "world--1991--p02"]},
  {id:"world--1991--d01",track:"world",year:1991,yearApprox:false,dim:"disaster",weight:3,title:"皮纳图博火山大爆发",summary:"六月十五日的爆发式喷发使平流层气溶胶增加，拉哈尔掩埋村镇。",detail:{background:"1991年4月起吕宋岛西南部皮纳图博出现地震群与喷气活动，当局在5月开始分批疏散，美军克拉克与苏比克基地处于下风向。",process:"1991年6月15日爆发式喷发形成数十公里高的喷发柱与碎屑流，火山灰降落至邻近各省；同年11月连续暴雨触发拉哈尔，安赫莱斯与巴科拉尔一带被泥沙掩埋，各国公布的死亡与失踪人数因统计时点不同而存在差异。",impact:"美国地质调查局与菲律宾火山地震研究所依据喷发柱高度与体积将本次喷发列为二十世纪规模最大的陆地喷发之一，平流层二氧化硫使全球气温在随后一至二年出现可测降幅；疏散、拉哈尔治理与基地撤离改变了当地土地利用与人口分布。",figures:["菲德尔·拉莫斯"],place:"菲律宾吕宋岛中南部",state:"菲律宾／美国",sources:["美国地质调查局与菲律宾火山地震研究所1991年关于皮纳图博喷发的观测报告与喷发指数评估","联合国减灾机构与菲律宾政府1991至1992年关于拉哈尔伤亡与疏散人数的统计"],tags:["火山","拉哈尔","平流层"]},related:["world--1989--d01", "world--1991--p04"]},
];
